}

package com.corclan.clan;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.TreeMap;

/**
 * Clan members grouped by in-game clan rank, highest rank first; within a rank, online members
 * first, then by name. Pure Java so it can be unit tested; the plugin feeds it from ClanSettings.
 */
public final class ClanRoster
{
	/** One clan member as the roster needs it. */
	public static final class Member
	{
		public final String name;
		/** RuneLite ClanRank number: 126 owner, 125 deputy owner, 100 admin, ... */
		public final int rank;
		/** The clan's own title for that rank, e.g. "Captain"; null if the game didn't give one */
		public final String title;
		public final boolean online;

		public Member(String name, int rank, String title, boolean online)
		{
			this.name = name;
			this.rank = rank;
			this.title = title;
			this.online = online;
		}

		@Override
		public boolean equals(Object o)
		{
			if (!(o instanceof Member))
			{
				return false;
			}
			Member m = (Member) o;
			return rank == m.rank && online == m.online && name.equals(m.name) && Objects.equals(title, m.title);
		}

		@Override
		public int hashCode()
		{
			return Objects.hash(name, rank, title, online);
		}
	}

	/** Everyone holding one rank. */
	public static final class RankGroup
	{
		public final int rank;
		public final String title;
		public final List<Member> members;

		RankGroup(int rank, String title, List<Member> members)
		{
			this.rank = rank;
			this.title = title;
			this.members = Collections.unmodifiableList(members);
		}

		public int onlineCount()
		{
			return (int) members.stream().filter(m -> m.online).count();
		}

		@Override
		public boolean equals(Object o)
		{
			if (!(o instanceof RankGroup))
			{
				return false;
			}
			RankGroup g = (RankGroup) o;
			return rank == g.rank && Objects.equals(title, g.title) && members.equals(g.members);
		}

		@Override
		public int hashCode()
		{
			return Objects.hash(rank, title, members);
		}
	}

	private ClanRoster()
	{
	}

	/** @return rank groups, highest rank first; empty if there are no members */
	public static List<RankGroup> group(List<Member> members)
	{
		Map<Integer, List<Member>> byRank = new TreeMap<>(Comparator.reverseOrder());
		for (Member m : members)
		{
			if (m != null && m.name != null && !m.name.isEmpty())
			{
				byRank.computeIfAbsent(m.rank, r -> new ArrayList<>()).add(m);
			}
		}

		List<RankGroup> groups = new ArrayList<>();
		byRank.forEach((rank, list) ->
		{
			list.sort(Comparator.comparing((Member m) -> !m.online)
				.thenComparing(m -> m.name, String.CASE_INSENSITIVE_ORDER));
			groups.add(new RankGroup(rank, titleOf(rank, list), list));
		});
		return groups;
	}

	private static String titleOf(int rank, List<Member> members)
	{
		for (Member m : members)
		{
			if (m.title != null && !m.title.isEmpty())
			{
				return m.title;
			}
		}
		return "Rank " + rank;
	}

	public static int total(List<RankGroup> groups)
	{
		return groups.stream().mapToInt(g -> g.members.size()).sum();
	}

	public static int online(List<RankGroup> groups)
	{
		return groups.stream().mapToInt(RankGroup::onlineCount).sum();
	}
}

package com.corclan.clan;

import com.corclan.icons.MemberCosmetics;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Collections;
import java.util.Set;

/**
 * JoeBoob's daily Infernal cape reminder: every time he logs in he is told to go and get one, with a running count of
 * the days he has been reminded. Only he and uimfartqueef ever see it (on his client when he logs in, on Ray's when Ray
 * sees him log in). Each client keeps its own count, raised once per calendar day it reminds. Pure logic.
 */
public final class InfernoReminder
{
	/** Who gets reminded, as {@link MemberCosmetics#key} names. */
	public static final Set<String> TARGETS = Collections.singleton("joeboob");
	/** Who sees him being reminded, besides himself. */
	public static final String WATCHER = "uimfartqueef";

	static final String COLOR = "ff5a1f";

	private InfernoReminder()
	{
	}

	public static boolean isTarget(String name)
	{
		return name != null && TARGETS.contains(MemberCosmetics.key(name));
	}

	public static boolean isWatcher(String name)
	{
		return name != null && WATCHER.equals(MemberCosmetics.key(name));
	}

	/**
	 * The count after reminding today: one more than before on the first reminder of a day, the same again on later
	 * logins that day.
	 * @param stored the last {@link #store} value, or null the first time
	 */
	public static int countAfter(String stored, LocalDate today)
	{
		Day last = Day.parse(stored);
		if (last == null)
		{
			return 1;
		}
		return last.date.equals(today) ? last.count : last.count + 1;
	}

	/** What to keep after reminding today with {@code count}. */
	public static String store(LocalDate today, int count)
	{
		return today + "|" + count;
	}

	/** The line on JoeBoob's own client. */
	public static String targetLine(String iconTag, int day)
	{
		return (iconTag == null ? "" : iconTag + " ") + "<col=" + COLOR + ">Daily reminder #" + day
			+ ": go and get your Infernal cape.</col>";
	}

	/** The line on Ray's client when he sees JoeBoob log in. */
	public static String watcherLine(String iconTag, String name, int day)
	{
		return (iconTag == null ? "" : iconTag + " ") + "<col=" + COLOR + ">" + Legion.clean(name)
			+ " has been reminded to get his Infernal cape (day " + day + "). Still no cape.</col>";
	}

	private static final class Day
	{
		final LocalDate date;
		final int count;

		Day(LocalDate date, int count)
		{
			this.date = date;
			this.count = count;
		}

		static Day parse(String stored)
		{
			if (stored == null)
			{
				return null;
			}
			String[] parts = stored.split("\\|");
			try
			{
				int count = Integer.parseInt(parts[1]);
				return count < 1 ? null : new Day(LocalDate.parse(parts[0]), count);
			}
			catch (DateTimeParseException | NumberFormatException | ArrayIndexOutOfBoundsException e)
			{
				return null;
			}
		}
	}
}

package com.corclan.clan;

import com.corclan.icons.MemberCosmetics;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;

/**
 * Login alerts for the CoR leaders: when one of the legionnaires ({@link ClanLeaders}) logs in, every plugin user in
 * the clan gets a line in chat; when the Spartan (Ray) lands, a golden one with a little extra. World hops are not
 * logins: in the clan channel a hop is the player leaving and joining again a few seconds later, so a join soon after
 * that player left is ignored. Pure logic; the plugin calls it on the client thread.
 */
public final class Legion
{
	/** The one leader whose login is a landing, as a {@link MemberCosmetics#key} name. */
	public static final String SPARTAN = "uimfartqueef";
	/** A join this soon after the same player left the channel is a world hop (or a quick relog), not a login. */
	static final long HOP_MILLIS = 60_000L;

	static final String LEGION_COLOR = "e0603a";
	static final String SPARTAN_COLOR = "ffc832";

	/** leader key -> when they last left the clan channel */
	private final Map<String, Long> leftAt = new HashMap<>();

	public static boolean isLegionnaire(String name)
	{
		return ClanLeaders.isLeader(name) || isSpartan(name);
	}

	public static boolean isSpartan(String name)
	{
		return name != null && SPARTAN.equals(MemberCosmetics.key(name));
	}

	/** A leader left the clan channel (logged out, or the first half of a world hop). */
	public void left(String name, long now)
	{
		if (isLegionnaire(name))
		{
			leftAt.put(MemberCosmetics.key(name), now);
		}
	}

	/** True when a leader joining the clan channel now has just logged in, not hopped worlds. */
	public boolean isLogin(String name, long now)
	{
		if (!isLegionnaire(name))
		{
			return false;
		}
		Long left = leftAt.remove(MemberCosmetics.key(name));
		return left == null || now - left > HOP_MILLIS;
	}

	public void clear()
	{
		leftAt.clear();
	}

	/**
	 * The chat line for a leader's login.
	 * @param iconTag an {@code <img=N>} tag to decorate it with, or null
	 */
	public static String line(String name, String iconTag)
	{
		String icon = iconTag == null ? "" : iconTag + " ";
		if (isSpartan(name))
		{
			return icon + "<col=" + SPARTAN_COLOR + ">A Spartan has landed!</col>" + (iconTag == null ? "" : " " + iconTag);
		}
		return icon + "<col=" + LEGION_COLOR + ">One of the legionnaires has logged in: " + clean(name) + "</col>";
	}

	/** Names come from the game, but they go into chat markup, so no tag can ever get through. */
	static String clean(String name)
	{
		return name == null ? "" : name.replace("<", "").replace(">", "").replace(' ', ' ').trim();
	}
}

package com.corclan.clan;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;

/**
 * Lays the clan's rank groups out as the CoR org chart. Two chains of boxes, top to bottom:
 * <ul>
 * <li>staff: three tiers of leadership ranks, matched by title</li>
 * <li>competitive: the Gem League entry ranks (Zenyte ... Opal) players start in, then the letter tiers
 * (S = Soul ... F = Gnome child) players will graduate into. The letter tiers aren't open yet, so they
 * come last and are marked {@link Tier#lockedNote locked}</li>
 * </ul>
 * Ranks are matched by their in-game title, since clans rename ranks freely. Every listed rank is
 * shown, vacant if nobody holds it. Anything left over goes into {@link Chart#others}.
 */
public final class OrgChart
{
	/** One tier's definition: a label, its rank titles in display order, and optional letter grades. */
	static final class TierDef
	{
		final String name;
		final List<String> titles;
		/** one letter per title (e.g. "SABCDEF"), or null for ungraded tiers */
		final String grades;

		TierDef(String name, String... titles)
		{
			this(name, null, Arrays.asList(titles));
		}

		private TierDef(String name, String grades, List<String> titles)
		{
			if (grades != null && grades.length() != titles.size())
			{
				throw new IllegalArgumentException(name + ": need one grade per title");
			}
			this.name = name;
			this.titles = titles;
			this.grades = grades;
		}

		static TierDef graded(String name, String grades, String... titles)
		{
			return new TierDef(name, grades, Arrays.asList(titles));
		}
	}

	/** The CoR staff hierarchy, top tier first. Edit here to change the chart. */
	static final List<TierDef> STAFF_TIERS = Arrays.asList(
		new TierDef("Owners", "Owner", "Deputy Owner"),
		new TierDef("Staff", "Marshal", "General", "Brigadier", "Colonel", "Administrator"),
		new TierDef("Hall of Fame", "Major", "Goon", "Executive", "Short green guy", "Hero"));

	/** Entry league, highest first: players start at Opal and work up to Zenyte. */
	static final TierDef GEM_LEAGUE = new TierDef("Gem League",
		"Zenyte", "Onyx", "Dragonstone", "Diamond", "Ruby", "Emerald", "Sapphire", "Opal");

	/** Competitive bracket, S tier first (placeholder titles; edit here). Earned by gz count. */
	static final TierDef LETTER_TIERS = TierDef.graded("Challenger League", "SABCDEF",
		"Soul", "Achiever", "Beast", "Competitor", "Dragon", "Elite", "Gnome child");

	/** Why the Challenger League is greyed out; set to null once its requirements are announced. */
	static final String LETTER_TIERS_LOCKED = "Not unlocked yet. Requirements to be announced soon";

	/** One rank slot in a tier: the title as charted, and whoever holds it (empty = vacant). */
	public static final class Slot
	{
		/** letter grade for the competitive tiers ("S", "A", ...), otherwise null */
		public final String grade;
		public final String title;
		public final List<ClanRoster.Member> members;

		Slot(String grade, String title, List<ClanRoster.Member> members)
		{
			this.grade = grade;
			this.title = title;
			this.members = Collections.unmodifiableList(members);
		}

		public int onlineCount()
		{
			return (int) members.stream().filter(m -> m.online).count();
		}
	}

	public static final class Tier
	{
		public final String name;
		public final List<Slot> slots;
		/** why nobody can reach this tier yet (show it greyed out), or null when it is open */
		public final String lockedNote;

		Tier(String name, List<Slot> slots, String lockedNote)
		{
			this.name = name;
			this.slots = Collections.unmodifiableList(slots);
			this.lockedNote = lockedNote;
		}
	}

	public static final class Chart
	{
		/** leadership tiers, top first */
		public final List<Tier> staff;
		/** the Gem League, then the (locked) letter tiers */
		public final List<Tier> competitive;
		/** rank groups that aren't in any tier, highest rank first */
		public final List<ClanRoster.RankGroup> others;

		Chart(List<Tier> staff, List<Tier> competitive, List<ClanRoster.RankGroup> others)
		{
			this.staff = Collections.unmodifiableList(staff);
			this.competitive = Collections.unmodifiableList(competitive);
			this.others = Collections.unmodifiableList(others);
		}
	}

	private OrgChart()
	{
	}

	/**
	 * @param groups     the roster from {@link ClanRoster#group}, highest rank first
	 * @param rankTitles every rank the clan has set up (rank number to title), including ranks
	 *                   nobody holds (their titles are shown as the game spells them)
	 */
	public static Chart build(List<ClanRoster.RankGroup> groups, Map<Integer, String> rankTitles)
	{
		// all known ranks: the clan's setup, plus any rank a member holds that the setup didn't list
		Map<Integer, String> ranks = new TreeMap<>(Collections.reverseOrder());
		ranks.putAll(rankTitles);
		for (ClanRoster.RankGroup g : groups)
		{
			ranks.putIfAbsent(g.rank, g.title);
		}

		Map<Integer, ClanRoster.RankGroup> byRank = new LinkedHashMap<>();
		for (ClanRoster.RankGroup g : groups)
		{
			byRank.put(g.rank, g);
		}

		Set<Integer> charted = new HashSet<>();
		List<Tier> staff = new ArrayList<>();
		for (TierDef def : STAFF_TIERS)
		{
			staff.add(titledTier(def, ranks, byRank, charted));
		}

		Tier gems = titledTier(GEM_LEAGUE, ranks, byRank, charted);
		Tier letters = titledTier(LETTER_TIERS, ranks, byRank, charted);
		List<Tier> competitive = Arrays.asList(gems,
			new Tier(letters.name, letters.slots, LETTER_TIERS_LOCKED));

		List<ClanRoster.RankGroup> others = new ArrayList<>();
		for (ClanRoster.RankGroup g : groups)
		{
			if (!charted.contains(g.rank))
			{
				others.add(g);
			}
		}
		return new Chart(staff, competitive, others);
	}

	/** A tier whose slots are fixed titles; each slot gathers every rank number carrying that title. */
	private static Tier titledTier(TierDef def, Map<Integer, String> ranks, Map<Integer, ClanRoster.RankGroup> byRank,
		Set<Integer> charted)
	{
		List<Slot> slots = new ArrayList<>();
		for (int i = 0; i < def.titles.size(); i++)
		{
			String title = def.titles.get(i);
			String grade = def.grades == null ? null : String.valueOf(def.grades.charAt(i));
			List<ClanRoster.Member> members = new ArrayList<>();
			String shownTitle = title;
			for (Map.Entry<Integer, String> rank : ranks.entrySet())
			{
				if (!charted.contains(rank.getKey()) && normalize(rank.getValue()).equals(normalize(title)))
				{
					shownTitle = rank.getValue();
					charted.add(rank.getKey());
					ClanRoster.RankGroup g = byRank.get(rank.getKey());
					if (g != null)
					{
						members.addAll(g.members);
					}
				}
			}
			slots.add(new Slot(grade, shownTitle, members));
		}
		return new Tier(def.name, slots, null);
	}

	/** Case, spacing and the common "Marshall" spelling don't matter when matching titles. */
	public static String normalize(String title)
	{
		String t = title == null ? "" : title.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
		return t.equals("marshall") ? "marshal" : t;
	}
}

package com.corclan.clan;

import com.corclan.icons.MemberCosmetics;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.Objects;

/**
 * The staff's promotion assistant for the Gem League: who has earned a higher gem rank, and who is close. Pure Java so
 * it can be unit tested; the plugin feeds it the clan's member list (names, rank titles, join dates from the game) and
 * the gz's each member has given. It only ever suggests: a staff member changes the rank in the game by hand, because
 * plugins can't (and must not) change clan ranks.
 * <p>
 * A member whose gz's nobody counted (no plugin, or clan sync off) counts as 0 gz: steps that need gz's can't be
 * checked for them, so they are never suggested on time alone.
 */
public final class Promotions
{
	/** One step up the Gem League: how long in the clan and how many gz's given it takes to go from one gem to the next. */
	public static final class Step
	{
		public final String from;
		public final String to;
		/** days since the member joined the clan */
		public final int days;
		/** all-time gz's given; 0 = time only */
		public final int gz;

		Step(String from, String to, int days, int gz)
		{
			this.from = from;
			this.to = to;
			this.days = days;
			this.gz = gz;
		}
	}

	/**
	 * The CoR Gem League ladder, lowest first. Everyone starts at Opal; the first rank-up needs 100 gz's and Zenyte 5000
	 * (Ray); the steps between are spread out evenly. You need the plugin to rank up: uncounted gz's are 0. Edit here.
	 * Titles must match {@link OrgChart#GEM_LEAGUE}.
	 */
	public static final List<Step> LADDER = Collections.unmodifiableList(Arrays.asList(
		new Step("Opal", "Sapphire", 7, 100),
		new Step("Sapphire", "Emerald", 14, 250),
		new Step("Emerald", "Ruby", 30, 500),
		new Step("Ruby", "Diamond", 60, 1000),
		new Step("Diamond", "Dragonstone", 90, 2000),
		new Step("Dragonstone", "Onyx", 180, 3500),
		new Step("Onyx", "Zenyte", 365, 5000)));

	/** members this many days or fewer from their next step show as coming up */
	static final int SOON_DAYS = 7;
	/** ... or with this share of the step's gz's still to give, at most */
	static final double SOON_GZ_SHARE = 0.2;

	/** One clan member as the assistant needs it. */
	public static final class Member
	{
		final String name;
		final String title;
		/** null when the game didn't say */
		final LocalDate joined;
		final boolean online;

		public Member(String name, String title, LocalDate joined, boolean online)
		{
			this.name = name;
			this.title = title;
			this.joined = joined;
			this.online = online;
		}
	}

	/** A member who is due a promotion, or close to one. */
	public static final class Candidate
	{
		public final String name;
		/** their gem now */
		public final String from;
		/** the highest gem they have earned (due), or the next one (coming up) */
		public final String to;
		public final int days;
		/** all-time gz's given, or null when nobody counted them */
		public final Integer gz;
		public final boolean online;
		/** coming up only: days and gz's still to go (0 when that part is met) */
		public final int daysLeft;
		public final int gzLeft;

		Candidate(String name, String from, String to, int days, Integer gz, boolean online, int daysLeft, int gzLeft)
		{
			this.name = name;
			this.from = from;
			this.to = to;
			this.days = days;
			this.gz = gz;
			this.online = online;
			this.daysLeft = daysLeft;
			this.gzLeft = gzLeft;
		}

		/** coming up only, e.g. "3 days" or "3 days, 12 gz" */
		public String still()
		{
			List<String> parts = new ArrayList<>();
			if (daysLeft > 0)
			{
				parts.add(daysLeft == 1 ? "1 day" : daysLeft + " days");
			}
			if (gzLeft > 0)
			{
				parts.add(gzLeft + " gz");
			}
			return String.join(", ", parts);
		}

		@Override
		public boolean equals(Object o)
		{
			if (!(o instanceof Candidate))
			{
				return false;
			}
			Candidate c = (Candidate) o;
			return days == c.days && online == c.online && daysLeft == c.daysLeft && gzLeft == c.gzLeft
				&& name.equals(c.name) && from.equals(c.from) && to.equals(c.to) && Objects.equals(gz, c.gz);
		}

		@Override
		public int hashCode()
		{
			return Objects.hash(name, from, to, days, gz, online, daysLeft, gzLeft);
		}
	}

	/** What the assistant found. */
	public static final class Result
	{
		/** earned a higher gem; highest target first */
		public final List<Candidate> due;
		/** close to the next gem; closest first */
		public final List<Candidate> soon;

		Result(List<Candidate> due, List<Candidate> soon)
		{
			this.due = Collections.unmodifiableList(due);
			this.soon = Collections.unmodifiableList(soon);
		}

		@Override
		public boolean equals(Object o)
		{
			return o instanceof Result && due.equals(((Result) o).due) && soon.equals(((Result) o).soon);
		}

		@Override
		public int hashCode()
		{
			return Objects.hash(due, soon);
		}
	}

	private Promotions()
	{
	}

	/**
	 * @param today the game's date (UTC)
	 * @param gzGiven all-time gz's given, by {@link MemberCosmetics#key}; a missing name means not counted
	 */
	public static Result check(List<Member> members, LocalDate today, Map<String, Integer> gzGiven)
	{
		List<Candidate> due = new ArrayList<>();
		List<Candidate> soon = new ArrayList<>();
		for (Member m : members)
		{
			int step = stepFrom(m.title);
			if (m.name == null || step < 0 || m.joined == null)
			{
				continue;
			}
			int days = (int) Math.max(0, ChronoUnit.DAYS.between(m.joined, today));
			Integer gz = gzGiven.get(MemberCosmetics.key(m.name));

			int reached = step;
			while (reached < LADDER.size() && met(LADDER.get(reached), days, gz))
			{
				reached++;
			}
			String from = LADDER.get(step).from;
			if (reached > step)
			{
				due.add(new Candidate(m.name, from, LADDER.get(reached - 1).to, days, gz, m.online, 0, 0));
				continue;
			}

			Step next = LADDER.get(step);
			int daysLeft = Math.max(0, next.days - days);
			int gzLeft = Math.max(0, next.gz - (gz == null ? 0 : gz));
			if (daysLeft <= SOON_DAYS && gzLeft <= Math.ceil(next.gz * SOON_GZ_SHARE))
			{
				soon.add(new Candidate(m.name, from, next.to, days, gz, m.online, daysLeft, gzLeft));
			}
		}
		due.sort(Comparator.comparingInt((Candidate c) -> -stepTo(c.to))
			.thenComparing(c -> c.name, String.CASE_INSENSITIVE_ORDER));
		soon.sort(Comparator.comparingInt((Candidate c) -> c.daysLeft)
			.thenComparingInt(c -> c.gzLeft)
			.thenComparing(c -> c.name, String.CASE_INSENSITIVE_ORDER));
		return new Result(due, soon);
	}

	private static boolean met(Step step, int days, Integer gz)
	{
		return days >= step.days && (gz == null ? 0 : gz) >= step.gz;
	}

	/** index of the step that leaves this gem, or -1 (not a gem, or already Zenyte) */
	private static int stepFrom(String title)
	{
		if (title == null)
		{
			return -1;
		}
		String t = OrgChart.normalize(title);
		for (int i = 0; i < LADDER.size(); i++)
		{
			if (OrgChart.normalize(LADDER.get(i).from).equals(t))
			{
				return i;
			}
		}
		return -1;
	}

	private static int stepTo(String title)
	{
		for (int i = 0; i < LADDER.size(); i++)
		{
			if (LADDER.get(i).to.equals(title))
			{
				return i;
			}
		}
		return -1;
	}
}

package com.corclan.fun;

import net.runelite.api.SoundEffectVolume;

/**
 * Sound bites for raids, played on this client only. In the Chambers of Xeric, every death of a player in view plays
 * a chicken's death squawk for each CoR plugin user in the raid (each client plays it for itself; nothing is sent).
 * The game's own sound effects, so nothing is bundled in the plugin.
 */
public final class RaidSounds
{
	/** The game's "chicken_death" sound effect (OSRS Wiki, List of in-game sound IDs). */
	public static final int CHICKEN_DEATH = 356;
	/** Olm's blood red */
	static final String SACRIFICE_COLOR = "c8102e";

	private RaidSounds()
	{
	}

	/** "Olm demands a blood sacrifice: Bob", in blood red, for a death in the Chambers. Shown on this client only. */
	public static String sacrificeLine(String name)
	{
		return "<col=" + SACRIFICE_COLOR + ">Olm demands a blood sacrifice: " + name + "</col>";
	}

	/**
	 * The game's sound effect volume for a volume setting.
	 * @param volume 0 (silent) to 100 (as loud as the game plays sound effects)
	 */
	public static int volume(int volume)
	{
		int clamped = Math.max(0, Math.min(volume, 100));
		return Math.round(clamped * SoundEffectVolume.HIGH / 100f);
	}
}

package com.corclan.glow;

import com.corclan.CorClanConfig;
import com.corclan.icons.MemberCosmetics;
import java.awt.Color;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.gameval.SpotanimID;

/**
 * DAYLlGHT's founder aura, built in by name like {@link LavaAura}: a Tormented Demon's fire turned red and a
 * black swirl climbing up them (both {@link TintedFx}), a smoke cloud playing on them nonstop (restarted the
 * moment each play ends), and red gem sparkles drawn by {@link SignatureGlowOverlay}. Every plugin user sees it (no clan sync needed) while "Show clan rank glows" is on.
 * DAYLlGHT can switch each part off ({@link FounderGlow}); other players see their choice once it arrives through
 * the clan server (clan sync), and everything until then. Drawn on this client only. All methods must run on the client thread.
 */
@Singleton
public class DaylightAura
{
	/**
	 * Players who wear the aura, as {@link MemberCosmetics#key} names. DAYLlGHT is spelt with a lowercase L,
	 * not an I.
	 */
	public static final Set<String> WEARERS = Collections.singleton("dayllght");

	/** Our own spot-anim slot (Ray's storm uses 3082-3084, Lavasockz's flames 3090). */
	static final int SMOKE_SLOT = 3092;
	/** Tormented Demons are Lucien's undead demons, so the cache calls their graphics LUC2_UNDEAD_DEMON_*. */
	static final int DEFAULT_FLAMES = SpotanimID.LUC2_UNDEAD_DEMON_EXPLOSION_FIRE_SPOT;
	static final int DEFAULT_SWIRL = SpotanimID.WYVERN_CYCLONE_LOOP;
	/** Best match for the Ring of Shadows teleport smoke: the cache does not name the ring, but this is the
	 * shadow teleport added with Desert Treasure II, where the ring comes from. */
	static final int DEFAULT_SMOKE = SpotanimID.VFX_MAHJARRAT_HUMAN_TELEPORT_SHADOW;
	/** The swirl climbs from the feet to about head height, then starts again at the feet. */
	public static final int DEFAULT_SWIRL_RISE = 250;
	static final long SWIRL_RISE_MILLIS = 2400L;
	/** Red stars for the gem sparkle, matching the red flames ({@link TintedFx#tint}), with a hot pink-orange point. */
	static final GemStyle.Sparkle SPARKLE = new GemStyle.Sparkle(8, new Color(225, 20, 20), new Color(255, 150, 120), 14);

	private final Client client;
	private final CorClanConfig config;
	/** wearer key -> the parts they shared through the clan server; replaced whole */
	private Map<String, List<String>> sharedPicks = Collections.emptyMap();

	private final TintedFx flames;
	private final TintedFx swirl;
	// the smoke in use this session; ::dayfx swaps it to try other ids
	private int smokeId = DEFAULT_SMOKE;
	/** how high the smoke plays, in local units above the ground (a character is ~200) */
	private int smokeHeight;

	@Inject
	DaylightAura(Client client, CorClanConfig config)
	{
		this.client = client;
		this.config = config;
		flames = new TintedFx(client, TintedFx.Tint.RED, DEFAULT_FLAMES, 0, 1L);
		swirl = new TintedFx(client, TintedFx.Tint.BLACK, DEFAULT_SWIRL, DEFAULT_SWIRL_RISE, SWIRL_RISE_MILLIS);
	}

	/** True for a clan member whose name wears the aura. */
	static boolean wears(Player player)
	{
		return player != null && player.isClanMember() && player.getName() != null
			&& WEARERS.contains(MemberCosmetics.key(player.getName()));
	}

	/** The parts of the aura {@code player} shows: empty unless they wear it. Client thread. */
	public Set<FounderGlow> effectsFor(Player player)
	{
		if (!wears(player))
		{
			return Collections.emptySet();
		}
		if (player == client.getLocalPlayer())
		{
			Set<FounderGlow> mine = EnumSet.noneOf(FounderGlow.class);
			for (FounderGlow glow : FounderGlow.values())
			{
				if (FounderGlow.picked(config, glow))
				{
					mine.add(glow);
				}
			}
			return mine;
		}
		return FounderGlow.active(sharedPicks.get(MemberCosmetics.key(player.getName())));
	}

	/** The parts this client's player switched on, as ids for the clan server. */
	public List<String> localPicks()
	{
		List<String> ids = new ArrayList<>();
		for (FounderGlow glow : FounderGlow.values())
		{
			if (FounderGlow.picked(config, glow))
			{
				ids.add(glow.id);
			}
		}
		return ids;
	}

	/**
	 * Everyone's glow picks arrived from the clan server; only wearers' are kept.
	 * @param picks {@link MemberCosmetics#key} -> the glow ids that player shared
	 */
	public void setSharedPicks(Map<String, List<String>> picks)
	{
		Map<String, List<String>> kept = new HashMap<>();
		for (String wearer : WEARERS)
		{
			List<String> glows = picks == null ? null : picks.get(wearer);
			if (glows != null)
			{
				kept.put(wearer, glows);
			}
		}
		sharedPicks = kept;
	}

	public void clearSharedPicks()
	{
		sharedPicks = Collections.emptyMap();
	}

	/**
	 * Every client frame (20 ms): keeps the red flames and black swirl on whoever shows them, and the smoke
	 * going. The game drops a spot anim from its slot when it finishes, so an empty slot means the smoke just
	 * ended and starts again straight away. Parts switched off are removed.
	 */
	public void onClientTick()
	{
		if (!config.rankGlow())
		{
			return;
		}
		List<Player> withFlames = new ArrayList<>();
		List<Player> withSwirl = new ArrayList<>();
		for (Player player : client.getTopLevelWorldView().players())
		{
			if (!wears(player))
			{
				continue;
			}
			Set<FounderGlow> on = effectsFor(player);
			if (on.contains(FounderGlow.DEMON_FLAMES))
			{
				withFlames.add(player);
			}
			if (on.contains(FounderGlow.BLACK_SWIRL))
			{
				withSwirl.add(player);
			}
			keepPlaying(player, SMOKE_SLOT, smokeId, smokeHeight, on.contains(FounderGlow.SMOKE_CLOUD));
		}
		flames.update(withFlames);
		swirl.update(withSwirl);
	}

	private static void keepPlaying(Player player, int slot, int id, int height, boolean on)
	{
		boolean playing = player.getSpotAnims().get(slot) != null;
		if (on && !playing)
		{
			player.createSpotAnim(slot, id, height, 0);
		}
		else if (!on && playing)
		{
			player.removeSpotAnim(slot);
		}
	}

	/**
	 * ::dayfx: uses another game graphic for one part this session, to try out effects. Local only.
	 * <ul>
	 * <li>flames|swirl: recolored red or black; for the swirl {@code extra} is how far it climbs (0 stays at the
	 * feet)</li>
	 * <li>smoke [height]: played as the game draws it (and once on you now)</li>
	 * </ul>
	 * @param label what to call the graphic in chat
	 * @return the chat line to show, or null if the arguments are wrong
	 */
	public String preview(String part, int id, int extra, String label)
	{
		if (part.equalsIgnoreCase(FounderGlow.DEMON_FLAMES.shortName) || part.equalsIgnoreCase(FounderGlow.BLACK_SWIRL.shortName))
		{
			boolean isFlames = part.equalsIgnoreCase(FounderGlow.DEMON_FLAMES.shortName);
			TintedFx fx = isFlames ? flames : swirl;
			if (!fx.use(id, isFlames ? 0 : extra))
			{
				return "CoR: " + label + " couldn't be read from the game cache";
			}
			return "CoR: " + part.toLowerCase() + " set to " + label + " for this session";
		}
		if (part.equalsIgnoreCase(FounderGlow.SMOKE_CLOUD.shortName))
		{
			smokeId = id;
			smokeHeight = extra;
			Player me = client.getLocalPlayer();
			if (me != null)
			{
				me.createSpotAnim(SMOKE_SLOT, id, extra, 0);
			}
			return "CoR: smoke set to " + label + " for this session";
		}
		return null;
	}

	/** Removes our graphics from everyone (glows turned off or plugin stopped). */
	public void clear()
	{
		flames.clear();
		swirl.clear();
		for (Player player : client.getTopLevelWorldView().players())
		{
			if (player != null)
			{
				player.removeSpotAnim(SMOKE_SLOT);
			}
		}
	}
}

