package com.corclan.glow;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import net.runelite.api.gameval.SpotanimID;

/**
 * The named game graphics the effect preview commands (::glowzap, ::glowshock, ::glowstrike, ::dayfx, ::naturefx)
 * let anyone pick from. RuneLite's Plugin Hub does not accept player-typed game ids, but a fixed list is fine, so a
 * raw spot anim id only works in RuneLite's developer mode, to try out graphics before adding them here.
 */
public final class FxPresets
{
	/** Preset name to spot anim id, in the order the chat lists them. */
	public static final Map<String, Integer> ALL;

	static
	{
		Map<String, Integer> presets = new LinkedHashMap<>();
		// the auras' own graphics
		presets.put("Sepulchre lightning", SpotanimID.HALLOWED_STATUE_LIGHTNING_STRIKE);
		presets.put("Killerwatt shock", SpotanimID.SKELETON_KILLERWATT_ELECTRICSHOCK);
		presets.put("Lucien lightning", SpotanimID.LUC2_LUCIEN_LIGHTNING_SPOT);
		presets.put("Mahjarrat shadow", SpotanimID.VFX_MAHJARRAT_HUMAN_TELEPORT_SHADOW);
		presets.put("Fairy ring", SpotanimID.FAIRY_FLOWER_RING);
		presets.put("Growing leaves", SpotanimID.LEAVES_GROWING);
		presets.put("Druid bloom", SpotanimID.DRUIDICSPIRIT_BLOOM_PLAYER_SPOTANIM);
		// the fires and swirls the recolored parts were made for
		for (TintedFx.Def def : TintedFx.CATALOG.values())
		{
			presets.putIfAbsent(def.name, def.spotId);
		}
		ALL = Collections.unmodifiableMap(presets);
	}

	/** A picked graphic. */
	public static final class Pick
	{
		public final int id;
		/** the number typed after it (swirl rise or height), or null */
		public final Integer extra;
		/** what to call it in chat: the preset's name, or the id typed in developer mode */
		public final String label;

		Pick(int id, Integer extra, String label)
		{
			this.id = id;
			this.extra = extra;
			this.label = label;
		}
	}

	private FxPresets()
	{
	}

	/**
	 * Reads what was typed after the command (and after the part, for ::dayfx and ::naturefx): a preset name in any
	 * case (the start of a name is enough when only one matches), optionally followed by a number for the rise or
	 * height. With {@code rawIds} a spot anim id can be typed instead of a name.
	 * @return null when nothing matches, or an id was typed without {@code rawIds}
	 */
	public static Pick parse(List<String> args, boolean rawIds)
	{
		if (args.isEmpty())
		{
			return null;
		}
		Integer first = number(args.get(0));
		if (first != null)
		{
			return rawIds ? new Pick(first, args.size() > 1 ? number(args.get(1)) : null, String.valueOf(first)) : null;
		}
		List<String> words = new ArrayList<>(args);
		Integer extra = words.size() > 1 ? number(words.get(words.size() - 1)) : null;
		if (extra != null)
		{
			words.remove(words.size() - 1);
		}
		String name = find(key(String.join(" ", words)));
		return name == null ? null : new Pick(ALL.get(name), extra, name);
	}

	/** True when the first word typed is a number: a raw id, which only developer mode takes. */
	public static boolean typedAnId(List<String> args)
	{
		return !args.isEmpty() && number(args.get(0)) != null;
	}

	/** The preset names, for the chat. */
	public static String names()
	{
		return String.join(", ", ALL.keySet());
	}

	private static String find(String typed)
	{
		if (typed.isEmpty())
		{
			return null;
		}
		String startsWith = null;
		int matches = 0;
		for (String name : ALL.keySet())
		{
			String k = key(name);
			if (k.equals(typed))
			{
				return name;
			}
			if (k.startsWith(typed))
			{
				startsWith = name;
				matches++;
			}
		}
		return matches == 1 ? startsWith : null;
	}

	/** Lower case letters and digits only, so "beef tornado", "Beef-Tornado" and "beeftornado" are the same. */
	private static String key(String text)
	{
		return text.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]", "");
	}

	private static Integer number(String word)
	{
		try
		{
			return Integer.parseInt(word);
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}
}

package com.corclan.glow;

import com.corclan.CorClanConfig;
import com.corclan.clan.OrgChart;
import java.util.Collection;
import java.util.EnumSet;
import java.util.Map;
import java.util.Set;
import net.runelite.api.clan.ClanRank;

/**
 * The Gem League rank glows, highest gem first. Each is unlocked by its gem rank or any higher rank.
 * Gem ranks are matched by in-game title (clans renumber and rename ranks freely), so unlocking needs
 * the clan's rank titles. Picks travel through the clan server (clan sync) in the same list as {@link GlowEffect}'s.
 * A player shows at most one gem glow: the highest one they picked and unlocked. Looks: {@link GemStyle}.
 */
public enum GemGlow
{
	ZENYTE("gem_zenyte", "glowZenyte", "Zenyte"),
	ONYX("gem_onyx", "glowOnyx", "Onyx"),
	DRAGONSTONE("gem_dragonstone", "glowDragonstone", "Dragonstone"),
	DIAMOND("gem_diamond", "glowDiamond", "Diamond"),
	RUBY("gem_ruby", "glowRuby", "Ruby"),
	EMERALD("gem_emerald", "glowEmerald", "Emerald"),
	SAPPHIRE("gem_sapphire", "glowSapphire", "Sapphire"),
	OPAL("gem_opal", "glowOpal", "Opal");

	/** sent to the clan server and on to other plugin users; never change one once released */
	public final String id;
	/** the checkbox's key in {@link CorClanConfig} */
	public final String configKey;
	/** the in-game rank title that unlocks it */
	public final String title;

	GemGlow(String id, String configKey, String title)
	{
		this.id = id;
		this.configKey = configKey;
		this.title = title;
	}

	public static boolean picked(CorClanConfig config, GemGlow gem)
	{
		switch (gem)
		{
			case ZENYTE:
				return config.glowZenyte();
			case ONYX:
				return config.glowOnyx();
			case DRAGONSTONE:
				return config.glowDragonstone();
			case DIAMOND:
				return config.glowDiamond();
			case RUBY:
				return config.glowRuby();
			case EMERALD:
				return config.glowEmerald();
			case SAPPHIRE:
				return config.glowSapphire();
			case OPAL:
				return config.glowOpal();
			default:
				return false;
		}
	}

	/**
	 * The two halves of a gem glow, each switchable on its own (settings, ::outline, ::sparkles) and shared
	 * through the clan server with the gem picks.
	 */
	public enum Part
	{
		OUTLINE("gem_outline", "glowGemOutline", "outline"),
		SPARKLES("gem_sparkles", "glowGemSparkles", "sparkles");

		/** sent to the clan server and on to other plugin users; never change one once released */
		public final String id;
		/** the checkbox's key in {@link CorClanConfig} */
		public final String configKey;
		/** its chat command, e.g. ::sparkles off */
		public final String command;

		Part(String id, String configKey, String command)
		{
			this.id = id;
			this.configKey = configKey;
			this.command = command;
		}

		public static boolean picked(CorClanConfig config, Part part)
		{
			switch (part)
			{
				case OUTLINE:
					return config.glowGemOutline();
				case SPARKLES:
					return config.glowGemSparkles();
				default:
					return false;
			}
		}

		/** The part switched by ::{@code command} (any case), or null. */
		public static Part byCommand(String command)
		{
			for (Part part : values())
			{
				if (part.command.equalsIgnoreCase(command))
				{
					return part;
				}
			}
			return null;
		}

		/**
		 * The parts a wearer shows.
		 * @param picks the ids they shared, or null if they shared none: then both show
		 */
		public static Set<Part> shown(Collection<String> picks)
		{
			Set<Part> shown = EnumSet.noneOf(Part.class);
			for (Part part : values())
			{
				if (picks == null || picks.contains(part.id))
				{
					shown.add(part);
				}
			}
			return shown;
		}
	}

	/** True for the gem picks' settings and the {@link Part} switches. */
	public static boolean isConfigKey(String key)
	{
		for (GemGlow gem : values())
		{
			if (gem.configKey.equals(key))
			{
				return true;
			}
		}
		for (Part part : Part.values())
		{
			if (part.configKey.equals(key))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * True when {@code wearer} holds this gem's rank or a higher one.
	 * @param rankTitles the clan's rank number to title; no rank titled after this gem means locked
	 */
	public boolean unlockedBy(ClanRank wearer, Map<Integer, String> rankTitles)
	{
		if (wearer == null)
		{
			return false;
		}
		for (Map.Entry<Integer, String> rank : rankTitles.entrySet())
		{
			if (titled(rank.getValue()) && wearer.getRank() >= rank.getKey())
			{
				return true;
			}
		}
		return false;
	}

	private boolean titled(String rankTitle)
	{
		return OrgChart.normalize(title).equals(OrgChart.normalize(rankTitle));
	}

	/** The highest gem glow {@code wearer}'s rank unlocks, or null when it unlocks none. */
	public static GemGlow highestUnlocked(ClanRank wearer, Map<Integer, String> rankTitles)
	{
		for (GemGlow gem : values())
		{
			if (gem.unlockedBy(wearer, rankTitles))
			{
				return gem;
			}
		}
		return null;
	}

	/**
	 * The gem glow a player of rank {@code wearer} shows, or null.
	 * @param picks the ids they picked (other glow ids mixed in are ignored), or null if they never shared
	 *              any: then they show their own gem rank's glow, if they hold one
	 */
	public static GemGlow shown(ClanRank wearer, Map<Integer, String> rankTitles, Collection<String> picks)
	{
		if (wearer == null)
		{
			return null;
		}
		for (GemGlow gem : values())
		{
			if (picks == null ? gem.titled(rankTitles.get(wearer.getRank()))
				: picks.contains(gem.id) && gem.unlockedBy(wearer, rankTitles))
			{
				return gem;
			}
		}
		return null;
	}
}

package com.corclan.glow;

import java.awt.Color;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

/**
 * The Gem League looks, each in its gem's in-game colour: a soft haze, then (from Diamond up) a glow
 * inside it, then a crisp edge on the model. Each gem up the ladder glows much wider and brighter, and from
 * Diamond up stars twinkle on the wearer ({@link #sparkle}, {@link Twinkle}). Pure Java so the look
 * (including the animation) can be unit tested.
 */
public final class GemStyle
{
	/** Opal's sheen drifting through pastel hues */
	static final long OPAL_SHEEN_MILLIS = 6000L;
	/** the calm breath of most gems */
	static final long CALM_MILLIS = 3500L;
	/** Ruby's quicker pulse */
	static final long RUBY_PULSE_MILLIS = 1600L;
	/** Diamond's and Onyx's glint on the edge */
	static final long GLINT_MILLIS = 700L;
	static final long ZENYTE_PULSE_MILLIS = 2600L;
	static final long ZENYTE_SHIMMER_MILLIS = 900L;

	/**
	 * How a gem's stars look: how many twinkle at once, their colour, the colour of the bright point at
	 * their centre and their size in pixels at full bloom.
	 */
	public static final class Sparkle
	{
		public final int count;
		public final Color color;
		public final Color core;
		public final int radius;

		Sparkle(int count, Color color, Color core, int radius)
		{
			this.count = count;
			this.color = color;
			this.core = core;
			this.radius = radius;
		}
	}

	/** Clan staff's gold twinkle (see {@link GlowPicks#isStaff}): warm gold stars with a pale gold point. */
	public static final Sparkle STAFF_GOLD = new Sparkle(6, new Color(255, 196, 50), new Color(255, 246, 205), 12);

	private GemStyle()
	{
	}

	/** 0 for Opal up to 7 for Zenyte. */
	static int tier(GemGlow gem)
	{
		return GemGlow.values().length - 1 - gem.ordinal();
	}

	/** @param now current time in millis; drives the animation */
	public static List<GlowStyle.Layer> layers(GemGlow gem, long now)
	{
		int tier = tier(gem);
		double calm = GlowStyle.breath(now, CALM_MILLIS);
		double glint = GlowStyle.breath(now, GLINT_MILLIS);
		switch (gem)
		{
			case OPAL:
			{
				// a pale haze whose hue slowly drifts, like an opal's play of colour
				float hue = (now % OPAL_SHEEN_MILLIS) / (float) OPAL_SHEEN_MILLIS;
				return layers(
					haze(tier, Color.getHSBColor(hue, 0.3f, 1f), calm),
					edge(tier, new Color(245, 245, 255)));
			}
			case SAPPHIRE:
				return layers(
					haze(tier, new Color(20, 70, 220), calm),
					edge(tier, new Color(110, 165, 255)));
			case EMERALD:
				return layers(
					haze(tier, new Color(0, 165, 70), calm),
					edge(tier, new Color(120, 240, 150)));
			case RUBY:
				// pulses quicker than the calm gems
				return layers(
					haze(tier, new Color(190, 0, 30), GlowStyle.breath(now, RUBY_PULSE_MILLIS)),
					edge(tier, new Color(255, 80, 100)));
			case DIAMOND:
				// icy haze and an edge that glints white to pale cyan
				return layers(
					haze(tier, new Color(190, 230, 255), calm),
					inner(tier, new Color(225, 245, 255)),
					edge(tier, new Color(lerp(255, 170, glint), 255, 255)));
			case DRAGONSTONE:
				return layers(
					haze(tier, new Color(130, 30, 200), calm),
					inner(tier, new Color(200, 80, 235)),
					edge(tier, new Color(235, 185, 255)));
			case ONYX:
			{
				// black smoke would vanish against dark ground on its own, so the edge glints silver
				int silver = lerp(170, 255, glint);
				return layers(
					haze(tier, new Color(8, 8, 14), calm),
					inner(tier, new Color(45, 45, 58)),
					edge(tier, new Color(silver, silver, Math.min(255, silver + 15))));
			}
			case ZENYTE:
			{
				// a swelling orange aura, an amber glow and a shimmering pale gold edge
				double shimmer = GlowStyle.breath(now, ZENYTE_SHIMMER_MILLIS);
				return layers(
					haze(tier, new Color(255, 115, 0), GlowStyle.breath(now, ZENYTE_PULSE_MILLIS)),
					inner(tier, new Color(255, 165, 30)),
					edge(tier, new Color(255, lerp(225, 255, shimmer), lerp(130, 215, shimmer))));
			}
			default:
				return Collections.emptyList();
		}
	}

	/** The stars twinkling on a wearer of {@code gem}, or null below Diamond. */
	public static Sparkle sparkle(GemGlow gem)
	{
		switch (gem)
		{
			case DIAMOND:
				return new Sparkle(4, new Color(220, 245, 255), Color.WHITE, 10);
			case DRAGONSTONE:
				return new Sparkle(6, new Color(235, 175, 255), Color.WHITE, 12);
			case ONYX:
				// black stars; a dim silver point keeps them reading as twinkles, not holes
				return new Sparkle(8, new Color(5, 5, 10), new Color(110, 110, 125), 14);
			case ZENYTE:
				return new Sparkle(10, new Color(255, 75, 20), new Color(255, 215, 150), 16);
			default:
				return null;
		}
	}

	/**
	 * The soft outer haze, much wider and brighter each tier up: Opal 4-5 px at alpha 60-110, up to
	 * Zenyte 18-21 px at 228-250.
	 * @param breath 0..1, swells it; higher tiers swell further
	 */
	private static GlowStyle.Layer haze(int tier, Color color, double breath)
	{
		return new GlowStyle.Layer(4 + 2 * tier + lerp(0, 1 + tier / 3, breath),
			alpha(color, lerp(60 + 24 * tier, 110 + 20 * tier, breath)), 4);
	}

	/** The glow inside the haze, Diamond and up: 4 px at Diamond to 7 at Zenyte, brighter each tier. */
	private static GlowStyle.Layer inner(int tier, Color color)
	{
		return new GlowStyle.Layer(tier, alpha(color, 190 + 20 * (tier - 4)), 2);
	}

	/** The crisp edge on the model, thicker from Diamond up. */
	private static GlowStyle.Layer edge(int tier, Color color)
	{
		return new GlowStyle.Layer(tier >= 4 ? 3 : 2, alpha(color, 255), 0);
	}

	private static List<GlowStyle.Layer> layers(GlowStyle.Layer... layers)
	{
		return Collections.unmodifiableList(Arrays.asList(layers));
	}

	private static Color alpha(Color color, int alpha)
	{
		return new Color(color.getRed(), color.getGreen(), color.getBlue(), alpha);
	}

	private static int lerp(int from, int to, double t)
	{
		return (int) Math.round(from + (to - from) * t);
	}
}

package com.corclan.glow;

import java.util.Collection;
import java.util.Collections;
import java.util.EnumSet;
import java.util.Set;
import net.runelite.api.clan.ClanRank;

/**
 * Every glow effect a clan member can show on themselves. Each needs a clan rank: that rank or any
 * higher one unlocks it. The Owner's effects are hidden settings, switched in the side panel (shown only
 * to the Owner) or with ::myglow, so the rest of the clan never sees them. Picks are shared through the
 * clan server (clan sync) so other plugin users see them. The viewer always checks the wearer's real clan rank, so
 * picking a locked effect (or a forged pick) shows nothing.
 */
public enum GlowEffect
{
	GOLD_OUTLINE("gold_outline", "glowGoldOutline", "outline", "Gold outline", ClanRank.OWNER),
	STORM_CLOUD("storm_cloud", "glowStormCloud", "cloud", "Storm cloud", ClanRank.OWNER),
	LIGHTNING_STRIKES("lightning_strikes", "glowLightningStrikes", "strikes", "Lightning strikes", ClanRank.OWNER),
	SHOCKS("shocks", "glowShocks", "shocks", "Shocks", ClanRank.OWNER),
	BIG_STRIKE("big_strike", "glowBigStrike", "bigstrike", "Big strike", ClanRank.OWNER);

	/** sent to the clan server and on to other plugin users; never change one once released */
	public final String id;
	/** the checkbox's key in {@link com.corclan.CorClanConfig} */
	public final String configKey;
	/** its name in ::myglow, e.g. ::myglow cloud off */
	public final String shortName;
	/** shown next to its checkbox in the side panel */
	public final String label;
	/** lowest rank that unlocks it */
	public final ClanRank rank;

	GlowEffect(String id, String configKey, String shortName, String label, ClanRank rank)
	{
		this.id = id;
		this.configKey = configKey;
		this.shortName = shortName;
		this.label = label;
		this.rank = rank;
	}

	public boolean unlockedBy(ClanRank wearer)
	{
		return wearer != null && wearer.getRank() >= rank.getRank();
	}

	/** The effect with id {@code id}, or null (e.g. one added by a newer plugin version). */
	public static GlowEffect byId(String id)
	{
		for (GlowEffect effect : values())
		{
			if (effect.id.equals(id))
			{
				return effect;
			}
		}
		return null;
	}

	/** The effect called {@code name} in ::myglow (any case), or null. */
	public static GlowEffect byShortName(String name)
	{
		for (GlowEffect effect : values())
		{
			if (effect.shortName.equalsIgnoreCase(name))
			{
				return effect;
			}
		}
		return null;
	}

	/** True for any rank glow setting: these effects and the {@link GemGlow}s, which share the same picks. */
	public static boolean isConfigKey(String key)
	{
		for (GlowEffect effect : values())
		{
			if (effect.configKey.equals(key))
			{
				return true;
			}
		}
		return GemGlow.isConfigKey(key);
	}

	/**
	 * What a player of rank {@code wearer} shows.
	 * @param picks the effect ids they picked, or null if they never shared any picks (clan sync
	 *              off, older plugin, not received yet): then they show their own rank's effects
	 */
	public static Set<GlowEffect> active(ClanRank wearer, Collection<String> picks)
	{
		if (wearer == null)
		{
			return Collections.emptySet();
		}
		Set<GlowEffect> active = EnumSet.noneOf(GlowEffect.class);
		if (picks == null)
		{
			for (GlowEffect effect : values())
			{
				if (effect.rank.getRank() == wearer.getRank())
				{
					active.add(effect);
				}
			}
			return active;
		}
		for (String id : picks)
		{
			GlowEffect effect = byId(id);
			if (effect != null && effect.unlockedBy(wearer))
			{
				active.add(effect);
			}
		}
		return active;
	}
}

package com.corclan.glow;

import com.corclan.CorClanConfig;
import com.corclan.icons.MemberCosmetics;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.clan.ClanChannel;
import net.runelite.api.clan.ClanChannelMember;
import net.runelite.api.clan.ClanRank;
import net.runelite.api.clan.ClanSettings;
import net.runelite.api.clan.ClanTitle;
import net.runelite.client.config.ConfigManager;

/**
 * Which glow effects each player shows: your own from your glow settings, everyone else's from the clan
 * server while clan sync is on (players who never shared picks, and everyone while sync is off, show their
 * rank's defaults). Always limited to what the wearer's clan rank, as this client sees it, unlocks.
 * Client thread only.
 */
@Singleton
public class GlowPicks
{
	private final Client client;
	private final CorClanConfig config;
	private final ConfigManager configManager;
	/** member key -> picked effect ids, as the clan server last listed them; replaced whole */
	private Map<String, List<String>> sharedPicks = Collections.emptyMap();

	@Inject
	GlowPicks(Client client, CorClanConfig config, ConfigManager configManager)
	{
		this.client = client;
		this.config = config;
		this.configManager = configManager;
	}

	/** The effect and gem glow ids you switched on, locked ones included (the viewer filters by rank). */
	public List<String> localPicks()
	{
		List<String> ids = new ArrayList<>();
		for (GlowEffect effect : GlowEffect.values())
		{
			if (picked(config, effect))
			{
				ids.add(effect.id);
			}
		}
		for (GemGlow gem : GemGlow.values())
		{
			if (GemGlow.picked(config, gem))
			{
				ids.add(gem.id);
			}
		}
		for (GemGlow.Part part : GemGlow.Part.values())
		{
			if (GemGlow.Part.picked(config, part))
			{
				ids.add(part.id);
			}
		}
		if (config.glowStaffTwinkle())
		{
			ids.add(STAFF_TWINKLE_ID);
		}
		return ids;
	}

	/**
	 * ::outline and ::sparkles switch that half of your gem glow; on or off sets it, nothing toggles it.
	 * @return false when {@code command} isn't one of them
	 */
	public boolean gemPartCommand(String command, String[] args)
	{
		GemGlow.Part part = GemGlow.Part.byCommand(command);
		if (part == null)
		{
			return false;
		}
		String state = args.length > 0 ? args[0].toLowerCase() : "";
		if (!(state.isEmpty() || state.equals("on") || state.equals("off")))
		{
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Usage: ::" + part.command + " [on|off]", null);
			return true;
		}
		boolean on = state.isEmpty() ? !GemGlow.Part.picked(config, part) : state.equals("on");
		configManager.setConfiguration(CorClanConfig.GROUP, part.configKey, on);
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "CoR: gem " + part.command + (on ? " on" : " off"), null);
		return true;
	}

	public static boolean picked(CorClanConfig config, GlowEffect effect)
	{
		switch (effect)
		{
			case GOLD_OUTLINE:
				return config.glowGoldOutline();
			case STORM_CLOUD:
				return config.glowStormCloud();
			case LIGHTNING_STRIKES:
				return config.glowLightningStrikes();
			case SHOCKS:
				return config.glowShocks();
			case BIG_STRIKE:
				return config.glowBigStrike();
			default:
				return false;
		}
	}

	/**
	 * Everyone's picks arrived from the clan server (replacing the earlier ones).
	 * @param picks {@link MemberCosmetics#key} -> the glow ids that player shared
	 */
	public void setSharedPicks(Map<String, List<String>> picks)
	{
		sharedPicks = picks == null ? Collections.emptyMap() : picks;
	}

	/** Clan sync went off: everyone shows their rank's defaults again. */
	public void clearSharedPicks()
	{
		sharedPicks = Collections.emptyMap();
	}

	/** The lowest and highest clan rank numbers that are staff: administrators up to the deputy owner. */
	static final int STAFF_LOWEST = 100;
	static final int STAFF_HIGHEST = 125;
	/** The staff gold twinkle's glow id; sent to the clan server, never change it once released. */
	public static final String STAFF_TWINKLE_ID = "staff_twinkle";

	/**
	 * True for clan staff, who get a gold twinkle: administrators (rank 100) up to the deputy owner (125). The Owner
	 * has the storm instead, and J-Mods (127) nothing. By rank number, so every viewer decides it from the clan rank
	 * they see, with or without clan sync.
	 */
	public static boolean isStaff(ClanRank rank)
	{
		return rank != null && rank.getRank() >= STAFF_LOWEST && rank.getRank() <= STAFF_HIGHEST;
	}

	/**
	 * True when {@code player} shows the staff gold twinkle: staff by the rank this client sees, unless they switched it
	 * off ("Staff gold twinkle"). Someone who shared no picks (clan sync off) shows it.
	 */
	public boolean staffTwinkleFor(ClanChannel channel, Player player)
	{
		ClanChannelMember member = clanMember(channel, player);
		if (member == null || !isStaff(member.getRank()))
		{
			return false;
		}
		List<String> shared = picksOf(player);
		return shared == null || shared.contains(STAFF_TWINKLE_ID);
	}

	/** Your own clan rank, or null when not in a clan (or not loaded yet). */
	public ClanRank localRank()
	{
		Player me = client.getLocalPlayer();
		ClanChannel channel = client.getClanChannel();
		if (me == null || me.getName() == null || channel == null)
		{
			return null;
		}
		ClanChannelMember member = channel.findMember(me.getName());
		return member == null ? null : member.getRank();
	}

	/**
	 * Every rank the clan has set up (rank number to title), for unlocking {@link GemGlow}s. Empty when not
	 * in a clan.
	 */
	public Map<Integer, String> clanRankTitles()
	{
		ClanSettings settings = client.getClanSettings();
		Map<Integer, String> titles = new HashMap<>();
		if (settings == null)
		{
			return titles;
		}
		for (int rank = 0; rank <= ClanRank.OWNER.getRank(); rank++)
		{
			ClanTitle title = settings.titleForRank(new ClanRank(rank));
			if (title != null && title.getName() != null && !title.getName().isEmpty())
			{
				titles.put(rank, title.getName());
			}
		}
		return titles;
	}

	/** The effects {@code player} shows, empty if they aren't in the clan. */
	public Set<GlowEffect> effectsFor(ClanChannel channel, Player player)
	{
		ClanChannelMember member = clanMember(channel, player);
		return member == null ? Collections.emptySet() : GlowEffect.active(member.getRank(), picksOf(player));
	}

	/**
	 * The gem glow {@code player} shows, or null.
	 * @param rankTitles from {@link #clanRankTitles}
	 */
	public GemGlow gemFor(ClanChannel channel, Map<Integer, String> rankTitles, Player player)
	{
		ClanChannelMember member = clanMember(channel, player);
		return member == null ? null : GemGlow.shown(member.getRank(), rankTitles, picksOf(player));
	}

	/** Which halves of their gem glow {@code player} shows: both unless they switched one off. */
	public Set<GemGlow.Part> gemPartsFor(Player player)
	{
		return GemGlow.Part.shown(picksOf(player));
	}

	private ClanChannelMember clanMember(ClanChannel channel, Player player)
	{
		if (channel == null || player == null || !player.isClanMember() || player.getName() == null)
		{
			return null;
		}
		return channel.findMember(player.getName());
	}

	/** null if they never shared any picks */
	private List<String> picksOf(Player player)
	{
		return player == client.getLocalPlayer()
			? localPicks()
			: sharedPicks.get(MemberCosmetics.key(player.getName()));
	}
}

package com.corclan.glow;

import java.awt.Color;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

/**
 * How a rank's glow is drawn: stacked outlines, outermost first. Each layer is one
 * ModelOutlineRenderer pass. Pure Java so the look (including the animation) can be unit tested.
 */
public final class GlowStyle
{
	/** One outline pass. */
	public static final class Layer
	{
		public final int width;
		public final Color color;
		/** 0 (hard edge) to 4 (softest) */
		public final int feather;

		Layer(int width, Color color, int feather)
		{
			this.width = width;
			this.color = color;
			this.feather = feather;
		}
	}

	/** One slow breath of the Owner's aura: it swells and brightens, then settles. */
	static final long HOLY_PULSE_MILLIS = 3000L;
	/** The core edge's quicker white/gold shimmer. */
	static final long HOLY_SHIMMER_MILLIS = 900L;

	private GlowStyle()
	{
	}

	/**
	 * The Owner's holy glow: a wide gold aura that breathes (swelling and brightening), a bright
	 * golden-white glow inside it, and a crisp edge on the model that shimmers white to pale gold.
	 * @param now current time in millis; drives the animation
	 */
	public static List<Layer> holy(long now)
	{
		double breath = breath(now, HOLY_PULSE_MILLIS);
		double shimmer = breath(now, HOLY_SHIMMER_MILLIS);
		return Collections.unmodifiableList(Arrays.asList(
			new Layer(lerp(10, 15, breath), new Color(255, 190, 40, lerp(110, 200, breath)), 4),
			new Layer(6, new Color(255, 225, 120, lerp(210, 255, breath)), 2),
			new Layer(2, new Color(255, lerp(255, 240, shimmer), lerp(255, 170, shimmer), 255), 0)));
	}

	/** 0..1..0 over one period, eased (sine) so it breathes rather than blinks. */
	static double breath(long now, long periodMillis)
	{
		double phase = (now % periodMillis) / (double) periodMillis;
		return (1 - Math.cos(phase * 2 * Math.PI)) / 2;
	}

	private static int lerp(int from, int to, double t)
	{
		return (int) Math.round(from + (to - from) * t);
	}
}

package com.corclan.glow;

import com.corclan.CorClanConfig;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.clan.ClanChannel;
import net.runelite.api.gameval.SpotanimID;

/**
 * The Owner storm effects, on top of {@link RankGlowOverlay}'s outline: an upside-down cloud overhead
 * ({@link StormCloud}), frequent lightning strikes, electric shocks, and a rare big strike, each at
 * random moments, on every player whose picks ({@link GlowPicks}) include them. Graphics come from
 * the game cache. Drawn by this client only: players without the plugin never see them. All methods
 * must run on the client thread.
 */
@Singleton
public class HolyAura
{
	/** One graphic replayed at random intervals in its own spot-anim slot. */
	public static final class Effect
	{
		/** chat command that previews / swaps this effect, e.g. "glowzap" for ::glowzap */
		public final String command;
		public final String label;
		/** the glow setting that switches it on for a wearer */
		final GlowEffect glow;
		/** our own slot, so we never replace a graphic the game is playing on the player */
		final int slot;
		/** random gap between plays, in game ticks (0.6 s each), inclusive */
		final int minTicks;
		final int maxTicks;
		int spotAnimId;
		int nextTick;

		Effect(String command, String label, GlowEffect glow, int slot, int spotAnimId, int minTicks, int maxTicks)
		{
			this.command = command;
			this.label = label;
			this.glow = glow;
			this.slot = slot;
			this.spotAnimId = spotAnimId;
			this.minTicks = minTicks;
			this.maxTicks = maxTicks;
			this.nextTick = minTicks;
		}

		/** Ticks until the next play: uniformly minTicks..maxTicks, so it never falls into a rhythm. */
		int delay(Random random)
		{
			return minTicks + random.nextInt(maxTicks - minTicks + 1);
		}
	}

	/** Frequent: the Hallowed Sepulchre statue's lightning strike, every 1.2 - 3.6 s. */
	final Effect strikes = new Effect("glowzap", "strikes", GlowEffect.LIGHTNING_STRIKES, 3083, SpotanimID.HALLOWED_STATUE_LIGHTNING_STRIKE, 2, 6);
	/** The Killerwatts' electric shock crackling on the body, every 1.8 - 4.8 s. */
	final Effect shock = new Effect("glowshock", "shock", GlowEffect.SHOCKS, 3084, SpotanimID.SKELETON_KILLERWATT_ELECTRICSHOCK, 3, 8);
	/** Rare: Lucien's lightning, every 10 - 20 s. */
	final Effect bigStrike = new Effect("glowstrike", "big strike", GlowEffect.BIG_STRIKE, 3082, SpotanimID.LUC2_LUCIEN_LIGHTNING_SPOT, 17, 33);

	final List<Effect> effects = Collections.unmodifiableList(Arrays.asList(strikes, shock, bigStrike));

	private final Client client;
	private final CorClanConfig config;
	private final StormCloud cloud;
	private final GlowPicks picks;
	private final Random random = new Random();
	private int ticks;
	/** Players in view and the storm effects they show, as of the last game tick. */
	private final Map<Player, Set<GlowEffect>> wearers = new HashMap<>();

	@Inject
	HolyAura(Client client, CorClanConfig config, StormCloud cloud, GlowPicks picks)
	{
		this.client = client;
		this.config = config;
		this.cloud = cloud;
		this.picks = picks;
	}

	public void onGameTick()
	{
		if (!config.rankGlow())
		{
			return;
		}
		ticks++;
		findWearers();
		List<Player> cloudy = new ArrayList<>();
		wearers.forEach((player, shown) ->
		{
			if (shown.contains(GlowEffect.STORM_CLOUD))
			{
				cloudy.add(player);
			}
		});
		cloud.update(cloudy);

		for (Effect effect : effects)
		{
			if (ticks < effect.nextTick)
			{
				continue;
			}
			effect.nextTick = ticks + effect.delay(random);
			wearers.forEach((player, shown) ->
			{
				if (shown.contains(effect.glow))
				{
					player.createSpotAnim(effect.slot, effect.spotAnimId, 0, 0);
				}
			});
		}
	}

	/** Every client frame (20 ms): keeps the cloud over its Owner as they move. */
	public void onClientTick()
	{
		if (config.rankGlow())
		{
			cloud.follow();
		}
	}

	private void findWearers()
	{
		wearers.clear();
		ClanChannel channel = client.getClanChannel();
		for (Player player : client.getTopLevelWorldView().players())
		{
			Set<GlowEffect> shown = picks.effectsFor(channel, player);
			if (!shown.isEmpty())
			{
				wearers.put(player, shown);
			}
		}
	}

	/** The effect previewed by chat command {@code command} (without "::"), or null. */
	public Effect forCommand(String command)
	{
		for (Effect effect : effects)
		{
			if (effect.command.equals(command))
			{
				return effect;
			}
		}
		return null;
	}

	/** Plays {@code id} on your own character now and uses it for {@code effect} this session. */
	public void preview(Effect effect, int id)
	{
		effect.spotAnimId = id;
		Player me = client.getLocalPlayer();
		if (me != null)
		{
			me.createSpotAnim(effect.slot, id, 0, 0);
		}
	}

	/** Removes the cloud and our graphics from everyone (glow turned off or plugin stopped). */
	public void clear()
	{
		wearers.clear();
		cloud.clear();
		for (Player player : client.getTopLevelWorldView().players())
		{
			if (player != null)
			{
				for (Effect effect : effects)
				{
					player.removeSpotAnim(effect.slot);
				}
			}
		}
	}
}

package com.corclan.glow;

import com.corclan.CorClanConfig;
import com.corclan.icons.MemberCosmetics;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.gameval.SpotanimID;

/**
 * Lavasockz's aura, built in by name like his founder and dev icons: the Flames of Zamorak burning around him
 * nonstop, restarted the moment each play ends, so it keeps going while he walks, on top of the molten outline
 * drawn by {@link SignatureGlowOverlay}. Every plugin user sees it
 * (no clan sync needed) while "Show clan rank glows" is on. Lavasockz can switch it off ({@link DevGlow}); other
 * players see his choice once it arrives through the clan server (clan sync), and the flames until then.
 * Graphics come from the game cache; drawn on this client only. All methods must run on the client thread.
 */
@Singleton
public class LavaAura
{
	/** Players who wear the aura, as {@link MemberCosmetics#key} names. */
	public static final Set<String> WEARERS = Collections.singleton("lavasockz");

	/** Our own spot-anim slot (Ray's storm uses 3082-3084), so we never replace a graphic the game is playing. */
	static final int SLOT = 3090;
	static final int FLAMES = SpotanimID.ZAMORAK_FLAME;

	private final Client client;
	private final CorClanConfig config;
	/** wearer key -> the parts they shared through the clan server; replaced whole */
	private Map<String, List<String>> sharedPicks = Collections.emptyMap();

	@Inject
	LavaAura(Client client, CorClanConfig config)
	{
		this.client = client;
		this.config = config;
	}

	/** True for a clan member whose name wears the aura. */
	static boolean wears(Player player)
	{
		return player != null && player.isClanMember() && player.getName() != null
			&& WEARERS.contains(MemberCosmetics.key(player.getName()));
	}

	/** The parts of the aura {@code player} shows: empty unless they wear it. Client thread. */
	public Set<DevGlow> effectsFor(Player player)
	{
		if (!wears(player))
		{
			return Collections.emptySet();
		}
		if (player == client.getLocalPlayer())
		{
			Set<DevGlow> mine = EnumSet.noneOf(DevGlow.class);
			for (DevGlow glow : DevGlow.values())
			{
				if (DevGlow.picked(config, glow))
				{
					mine.add(glow);
				}
			}
			return mine;
		}
		return DevGlow.active(sharedPicks.get(MemberCosmetics.key(player.getName())));
	}

	/** The parts this client's player switched on, as ids for the clan server. */
	public List<String> localPicks()
	{
		List<String> ids = new ArrayList<>();
		for (DevGlow glow : DevGlow.values())
		{
			if (DevGlow.picked(config, glow))
			{
				ids.add(glow.id);
			}
		}
		return ids;
	}

	/**
	 * Everyone's glow picks arrived from the clan server; only wearers' are kept.
	 * @param picks {@link MemberCosmetics#key} -> the glow ids that player shared
	 */
	public void setSharedPicks(Map<String, List<String>> picks)
	{
		Map<String, List<String>> kept = new HashMap<>();
		for (String wearer : WEARERS)
		{
			List<String> glows = picks == null ? null : picks.get(wearer);
			if (glows != null)
			{
				kept.put(wearer, glows);
			}
		}
		sharedPicks = kept;
	}

	public void clearSharedPicks()
	{
		sharedPicks = Collections.emptyMap();
	}

	/**
	 * Every client frame (20 ms): the game drops a spot anim from its slot when it finishes, so an empty slot
	 * means the flames just ended and start again straight away. Spot anims ride on the player, so they follow
	 * him as he walks. Anyone who switched the flames off has them removed.
	 */
	public void onClientTick()
	{
		if (!config.rankGlow())
		{
			return;
		}
		for (Player player : client.getTopLevelWorldView().players())
		{
			if (!wears(player))
			{
				continue;
			}
			boolean on = effectsFor(player).contains(DevGlow.ZAMORAK_FLAMES);
			boolean playing = player.getSpotAnims().get(SLOT) != null;
			if (on && !playing)
			{
				player.createSpotAnim(SLOT, FLAMES, 0, 0);
			}
			else if (!on && playing)
			{
				player.removeSpotAnim(SLOT);
			}
		}
	}

	/** ::lavafx: plays the flames on your own character once, to show them off. */
	public void preview()
	{
		Player me = client.getLocalPlayer();
		if (me != null)
		{
			me.createSpotAnim(SLOT, FLAMES, 0, 0);
		}
	}

	/** Removes our flames from everyone (glows turned off or plugin stopped). */
	public void clear()
	{
		for (Player player : client.getTopLevelWorldView().players())
		{
			if (player != null)
			{
				player.removeSpotAnim(SLOT);
			}
		}
	}
}

package com.corclan.glow;

import java.awt.Color;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

/**
 * Lavasockz's molten outline: a dark red heat haze, an orange body of flame and a white-hot core, all
 * flickering like a fire rather than breathing like the Owner's gold glow. Pure Java so it can be tested.
 */
public final class MoltenStyle
{
	private MoltenStyle()
	{
	}

	/** @param now current time in millis; drives the flicker */
	public static List<GlowStyle.Layer> molten(long now)
	{
		double flicker = flicker(now);
		double fast = flicker(now * 3 + 1234);
		return Collections.unmodifiableList(Arrays.asList(
			new GlowStyle.Layer(lerp(9, 14, flicker), new Color(150, lerp(10, 30, fast), 0, lerp(120, 190, flicker)), 4),
			new GlowStyle.Layer(lerp(4, 6, fast), new Color(255, lerp(80, 130, flicker), 0, 235), 2),
			new GlowStyle.Layer(2, new Color(255, lerp(200, 245, fast), lerp(60, 170, fast), 255), 0)));
	}

	/**
	 * 0..1, irregular like flames: three sines at unrelated speeds added together, so it never settles
	 * into an obvious rhythm.
	 */
	static double flicker(long now)
	{
		double t = now / 1000.0;
		double v = Math.sin(t * 7.3) + 0.6 * Math.sin(t * 13.1 + 1.7) + 0.4 * Math.sin(t * 23.9 + 4.2);
		return (v / 2.0 + 1) / 2;
	}

	private static int lerp(int from, int to, double t)
	{
		double clamped = Math.max(0, Math.min(1, t));
		return (int) Math.round(from + (to - from) * clamped);
	}
}

package com.corclan.glow;

import com.corclan.CorClanConfig;
import com.corclan.icons.MemberCosmetics;
import java.awt.Color;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.gameval.SpotanimID;

/**
 * JoeBoob's nature aura, the green elemental twin of {@link DaylightAura}: a Zanaris fairy ring with leaves springing
 * up around him, the same swirl as DAYLlGHT's turned leaf green ({@link TintedFx.Tint#GREEN}), the Druidic spirit's
 * bloom (each graphic restarted the moment it ends) and emerald sparkles drawn by {@link SignatureGlowOverlay}. Every plugin user sees it (no clan sync needed) while "Show clan
 * rank glows" is on. JoeBoob can switch each part off ({@link NatureGlow}); others see that choice once it arrives
 * through the clan server. Drawn on this client only. All methods must run on the client thread.
 */
@Singleton
public class NatureAura
{
	/** Players who wear the aura, as {@link MemberCosmetics#key} names. */
	public static final Set<String> WEARERS = Collections.singleton("joeboob");

	/** Our own spot-anim slots (storm 3082-3084, Lavasockz 3090, DAYLlGHT 3092, shame 3094). */
	static final int BLOOM_SLOT = 3096;
	static final int LEAVES_SLOT = 3098;
	/** The fairy ring's mushrooms and flowers coming up around a player, as when you step through to Zanaris. */
	static final int DEFAULT_RING = SpotanimID.FAIRY_FLOWER_RING;
	/** Leaves sprouting from the ground (the Druidic spirit's bloom is built from these). */
	static final int DEFAULT_LEAVES = SpotanimID.LEAVES_GROWING;
	static final int DEFAULT_SWIRL = DaylightAura.DEFAULT_SWIRL;
	/** The fairy ring plays at this share of the game's speed, and at twice its size. */
	static final double RING_SPEED = 0.35;
	static final double RING_SCALE = 2.0;
	/** The green swirl turns at this share of the game's speed and climbs this many times slower than DAYLlGHT's. */
	static final double SWIRL_SPEED = 0.35;
	static final long SWIRL_RISE_MILLIS = DaylightAura.SWIRL_RISE_MILLIS * 3;
	/** The bloom the Druidic spirit (Blessed sickle) casts around a player: fungi and leaves springing up. */
	static final int DEFAULT_BLOOM = SpotanimID.DRUIDICSPIRIT_BLOOM_PLAYER_SPOTANIM;
	/** Green stars with a pale lime point, as many as DAYLlGHT's. */
	static final GemStyle.Sparkle SPARKLE = new GemStyle.Sparkle(8, new Color(30, 200, 70), new Color(200, 255, 170), 14);

	private final Client client;
	private final CorClanConfig config;
	/** wearer key -> the parts they shared through the clan server; replaced whole */
	private Map<String, List<String>> sharedPicks = Collections.emptyMap();

	private final TintedFx swirl;
	/** the fairy ring, slowed down and doubled in size, so drawn by us rather than played by the game */
	private final TintedFx ring;
	// the graphics in use this session; ::naturefx swaps them to try other ids
	private int bloomId = DEFAULT_BLOOM;
	private int bloomHeight;
	private int leavesId = DEFAULT_LEAVES;

	@Inject
	NatureAura(Client client, CorClanConfig config)
	{
		this.client = client;
		this.config = config;
		swirl = new TintedFx(client, TintedFx.Tint.GREEN, DEFAULT_SWIRL, DaylightAura.DEFAULT_SWIRL_RISE,
			SWIRL_RISE_MILLIS, SWIRL_SPEED, 1.0);
		ring = new TintedFx(client, TintedFx.Tint.NONE, DEFAULT_RING, 0, 1L, RING_SPEED, RING_SCALE);
	}

	/** True for a clan member whose name wears the aura. */
	static boolean wears(Player player)
	{
		return player != null && player.isClanMember() && player.getName() != null
			&& WEARERS.contains(MemberCosmetics.key(player.getName()));
	}

	/** The parts of the aura {@code player} shows: empty unless they wear it. */
	public Set<NatureGlow> effectsFor(Player player)
	{
		if (!wears(player))
		{
			return Collections.emptySet();
		}
		if (player == client.getLocalPlayer())
		{
			Set<NatureGlow> mine = EnumSet.noneOf(NatureGlow.class);
			for (NatureGlow glow : NatureGlow.values())
			{
				if (NatureGlow.picked(config, glow))
				{
					mine.add(glow);
				}
			}
			return mine;
		}
		return NatureGlow.active(sharedPicks.get(MemberCosmetics.key(player.getName())));
	}

	/** The parts this client's player switched on, as ids for the clan server. */
	public List<String> localPicks()
	{
		List<String> ids = new ArrayList<>();
		for (NatureGlow glow : NatureGlow.values())
		{
			if (NatureGlow.picked(config, glow))
			{
				ids.add(glow.id);
			}
		}
		return ids;
	}

	/** Everyone's glow picks arrived from the clan server; only wearers' are kept. */
	public void setSharedPicks(Map<String, List<String>> picks)
	{
		Map<String, List<String>> kept = new HashMap<>();
		for (String wearer : WEARERS)
		{
			List<String> glows = picks == null ? null : picks.get(wearer);
			if (glows != null)
			{
				kept.put(wearer, glows);
			}
		}
		sharedPicks = kept;
	}

	public void clearSharedPicks()
	{
		sharedPicks = Collections.emptyMap();
	}

	/** Every client frame: keeps the green swirl on whoever shows it, and the fairy ring, leaves and bloom going. */
	public void onClientTick()
	{
		if (!config.rankGlow())
		{
			return;
		}
		List<Player> withSwirl = new ArrayList<>();
		List<Player> withRing = new ArrayList<>();
		for (Player player : client.getTopLevelWorldView().players())
		{
			if (!wears(player))
			{
				continue;
			}
			Set<NatureGlow> on = effectsFor(player);
			if (on.contains(NatureGlow.LEAF_SWIRL))
			{
				withSwirl.add(player);
			}
			boolean fairy = on.contains(NatureGlow.FAIRY_RING);
			if (fairy)
			{
				withRing.add(player);
			}
			keepPlaying(player, LEAVES_SLOT, leavesId, 0, fairy);
			keepPlaying(player, BLOOM_SLOT, bloomId, bloomHeight, on.contains(NatureGlow.BLOOM));
		}
		swirl.update(withSwirl);
		ring.update(withRing);
	}

	/** Restarts a graphic the moment it ends (the game empties its slot), or takes it off. */
	private static void keepPlaying(Player player, int slot, int id, int height, boolean on)
	{
		boolean playing = player.getSpotAnims().get(slot) != null;
		if (on && !playing)
		{
			player.createSpotAnim(slot, id, height, 0);
		}
		else if (!on && playing)
		{
			player.removeSpotAnim(slot);
		}
	}

	/**
	 * ::naturefx: uses another game graphic for one part this session, like ::dayfx. Local only.
	 * swirl [rise] is turned green; ring is slowed and doubled like the fairy ring; leaves and bloom [height] are
	 * played as the game draws them.
	 * @param label what to call the graphic in chat
	 * @return the chat line to show, or null if the arguments are wrong
	 */
	public String preview(String part, int id, int extra, String label)
	{
		if (part.equalsIgnoreCase(NatureGlow.LEAF_SWIRL.shortName))
		{
			return swirl.use(id, extra)
				? "CoR: swirl set to " + label + " for this session"
				: "CoR: " + label + " couldn't be read from the game cache";
		}
		if (part.equalsIgnoreCase(NatureGlow.FAIRY_RING.shortName))
		{
			return ring.use(id, 0)
				? "CoR: ring set to " + label + " for this session (slowed and doubled)"
				: "CoR: " + label + " couldn't be read from the game cache";
		}
		int slot;
		if (part.equalsIgnoreCase("leaves"))
		{
			leavesId = id;
			slot = LEAVES_SLOT;
		}
		else if (part.equalsIgnoreCase(NatureGlow.BLOOM.shortName))
		{
			bloomId = id;
			bloomHeight = extra;
			slot = BLOOM_SLOT;
		}
		else
		{
			return null;
		}
		Player me = client.getLocalPlayer();
		if (me != null)
		{
			me.createSpotAnim(slot, id, slot == BLOOM_SLOT ? extra : 0, 0);
		}
		return "CoR: " + part.toLowerCase() + " set to " + label + " for this session";
	}

	/** Removes our graphics from everyone (glows turned off or plugin stopped). */
	public void clear()
	{
		swirl.clear();
		ring.clear();
		for (Player player : client.getTopLevelWorldView().players())
		{
			if (player != null)
			{
				player.removeSpotAnim(BLOOM_SLOT);
				player.removeSpotAnim(LEAVES_SLOT);
			}
		}
	}
}

package com.corclan.glow;

import com.corclan.CorClanConfig;
import java.util.Collection;
import java.util.EnumSet;
import java.util.Set;

/**
 * The parts of JoeBoob's nature aura ({@link NatureAura}), a green take on DAYLlGHT's {@link FounderGlow}. Each is
 * switchable by JoeBoob only: hidden settings, set from the "Nature glow" section of the CoR side panel (shown only
 * to JoeBoob), the rank card's Glow switch or ::natureglow. Picks travel through the clan server (clan sync) in the
 * same list as the rank glow picks.
 */
public enum NatureGlow
{
	FAIRY_RING("nature_fairy_ring", "natureGlowFairyRing", "ring", "Zanaris fairy ring and leaves"),
	LEAF_SWIRL("nature_leaf_swirl", "natureGlowSwirl", "swirl", "Leaf green swirl"),
	BLOOM("nature_bloom", "natureGlowBloom", "bloom", "Druid bloom"),
	EMERALD_SPARKLE("nature_emerald_sparkle", "natureGlowSparkle", "sparkle", "Emerald sparkle");

	/** sent to the clan server and on to other plugin users; never change one once released */
	public final String id;
	/** the hidden checkbox's key in {@link CorClanConfig} */
	public final String configKey;
	/** its name in ::natureglow, e.g. ::natureglow bloom off */
	public final String shortName;
	/** shown next to its checkbox in the side panel */
	public final String label;

	NatureGlow(String id, String configKey, String shortName, String label)
	{
		this.id = id;
		this.configKey = configKey;
		this.shortName = shortName;
		this.label = label;
	}

	public static boolean picked(CorClanConfig config, NatureGlow glow)
	{
		switch (glow)
		{
			case FAIRY_RING:
				return config.natureGlowFairyRing();
			case LEAF_SWIRL:
				return config.natureGlowSwirl();
			case BLOOM:
				return config.natureGlowBloom();
			case EMERALD_SPARKLE:
				return config.natureGlowSparkle();
			default:
				return false;
		}
	}

	/** The part called {@code name} in ::natureglow (any case), or null. */
	public static NatureGlow byShortName(String name)
	{
		for (NatureGlow glow : values())
		{
			if (glow.shortName.equalsIgnoreCase(name))
			{
				return glow;
			}
		}
		return null;
	}

	/**
	 * What the wearer shows.
	 * @param picks the ids they shared through the clan server (other glow ids mixed in are ignored), or null if they
	 *              shared none: then everything shows
	 */
	public static Set<NatureGlow> active(Collection<String> picks)
	{
		if (picks == null)
		{
			return EnumSet.allOf(NatureGlow.class);
		}
		Set<NatureGlow> active = EnumSet.noneOf(NatureGlow.class);
		for (NatureGlow glow : values())
		{
			if (picks.contains(glow.id))
			{
				active.add(glow);
			}
		}
		return active;
	}
}

package com.corclan.glow;

import com.corclan.CorClanConfig;
import com.corclan.icons.MemberCosmetics;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.clan.ClanChannel;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

/**
 * Outlines clan members in the game world by the glow they picked ({@link GlowPicks}). Drawn on this
 * client only; players without the plugin see nothing.
 * One outline per player: the Owner's {@link GlowStyle#holy}, else their {@link GemStyle} gem glow, with
 * twinkling stars from Diamond up. Players wearing a signature outline (drawn by
 * {@link SignatureGlowOverlay}) get no gem glow on top of it. Clan staff also twinkle gold ({@link GlowPicks#isStaff}).
 */
public class RankGlowOverlay extends Overlay
{
	/** how far a star's inner corners sit from its centre, as a share of its points' reach */
	private static final double STAR_WAIST = 0.22;
	/** how far past the body's bounds stars may appear, as a share of its width and height on each side */
	private static final double STAR_SPILL = 0.15;

	private final Client client;
	private final CorClanConfig config;
	private final ModelOutlineRenderer outlines;
	private final GlowPicks picks;
	private final LavaAura lavaAura;

	@Inject
	RankGlowOverlay(Client client, CorClanConfig config, ModelOutlineRenderer outlines, GlowPicks picks, LavaAura lavaAura)
	{
		this.client = client;
		this.config = config;
		this.outlines = outlines;
		this.picks = picks;
		this.lavaAura = lavaAura;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPriority(PRIORITY_HIGH);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.rankGlow())
		{
			return null;
		}
		ClanChannel channel = client.getClanChannel();
		if (channel == null)
		{
			return null;
		}
		long now = System.currentTimeMillis();
		Map<Integer, String> rankTitles = picks.clanRankTitles();
		for (Player player : client.getTopLevelWorldView().players())
		{
			if (picks.effectsFor(channel, player).contains(GlowEffect.GOLD_OUTLINE))
			{
				draw(player, GlowStyle.holy(now));
				continue;
			}
			if (picks.staffTwinkleFor(channel, player))
			{
				twinkle(graphics, player, GemStyle.STAFF_GOLD, now);
			}
			if (lavaAura.effectsFor(player).contains(DevGlow.MOLTEN_OUTLINE))
			{
				continue;
			}
			GemGlow gem = picks.gemFor(channel, rankTitles, player);
			if (gem != null)
			{
				Set<GemGlow.Part> parts = picks.gemPartsFor(player);
				if (parts.contains(GemGlow.Part.OUTLINE))
				{
					draw(player, GemStyle.layers(gem, now));
				}
				GemStyle.Sparkle sparkle = GemStyle.sparkle(gem);
				if (sparkle != null && parts.contains(GemGlow.Part.SPARKLES))
				{
					twinkle(graphics, player, sparkle, now);
				}
			}
		}
		return null;
	}

	private void draw(Player player, List<GlowStyle.Layer> layers)
	{
		for (GlowStyle.Layer layer : layers)
		{
			outlines.drawOutline(player, layer.width, layer.color, layer.feather);
		}
	}

	/** Stars blooming and fading over the player's body. */
	static void twinkle(Graphics2D graphics, Player player, GemStyle.Sparkle sparkle, long now)
	{
		Shape hull = player.getConvexHull();
		if (hull == null)
		{
			return;
		}
		// let the stars spill a little past the body
		Rectangle bounds = hull.getBounds();
		bounds.grow((int) (bounds.width * STAR_SPILL), (int) (bounds.height * STAR_SPILL));
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		long seed = MemberCosmetics.key(player.getName()).hashCode();
		for (Twinkle.Star star : Twinkle.stars(seed, sparkle.count, now))
		{
			double r = sparkle.radius * star.size;
			if (r < 1)
			{
				continue;
			}
			double x = bounds.x + star.x * bounds.width;
			double y = bounds.y + star.y * bounds.height;
			graphics.setColor(alpha(sparkle.color, 0.45 * star.size));
			graphics.fill(new Ellipse2D.Double(x - r * 0.8, y - r * 0.8, r * 1.6, r * 1.6));
			// a smaller diagonal star behind the main one makes it read as a sparkle
			graphics.setColor(alpha(sparkle.color, 0.8 * star.size));
			graphics.fill(star(x, y, r * 0.55, Math.PI / 4));
			graphics.setColor(alpha(sparkle.color, star.size));
			graphics.fill(star(x, y, r, 0));
			graphics.setColor(alpha(sparkle.core, star.size));
			graphics.fill(new Ellipse2D.Double(x - r * 0.2, y - r * 0.2, r * 0.4, r * 0.4));
		}
	}

	/** A four-pointed star centred on (x, y), points reaching {@code r}, turned {@code angle} radians. */
	private static Shape star(double x, double y, double r, double angle)
	{
		double w = r * STAR_WAIST;
		Path2D.Double path = new Path2D.Double();
		for (int i = 0; i < 8; i++)
		{
			double reach = i % 2 == 0 ? r : w * Math.sqrt(2);
			double a = angle - Math.PI / 2 + i * Math.PI / 4;
			double px = x + reach * Math.cos(a);
			double py = y + reach * Math.sin(a);
			if (i == 0)
			{
				path.moveTo(px, py);
			}
			else
			{
				path.lineTo(px, py);
			}
		}
		path.closePath();
		return path;
	}

	private static Color alpha(Color color, double opacity)
	{
		return new Color(color.getRed(), color.getGreen(), color.getBlue(), (int) Math.round(255 * opacity));
	}
}

package com.corclan.glow;

import com.corclan.CorClanConfig;
import com.corclan.clan.ClanLeaders;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.gameval.SpotanimID;

/**
 * The Kephri dung: ::shame &lt;name&gt; from one of the {@link ClanLeaders} drops Kephri's dung on that clanmate's head
 * over and over until a leader takes it off with ::unshame. Opt-in: only clanmates who turned on "Let leaders shame
 * me" can be shamed, and turning it off takes the dung off. Shames travel through the clan server (clan sync), so every
 * plugin user with sync on sees it, the shamed player included, while "Show clan rank glows" is on. Drawn on this
 * client only.
 * All methods must run on the client thread.
 */
@Singleton
public class ShameAura
{
	/** Our own spot-anim slot (Ray's storm uses 3082-3084, Lavasockz's flames 3090, DAYLlGHT's smoke 3092). */
	static final int SLOT = 3094;
	static final int DUNG = SpotanimID.KEPHRI_DUNG_DROP;
	/** a fresh dung drops this often, in game ticks (0.6 s each) */
	static final int DROP_TICKS = 5;

	private final Client client;
	private final CorClanConfig config;
	private Shames shames = Shames.NONE;
	private int ticks;

	@Inject
	ShameAura(Client client, CorClanConfig config)
	{
		this.client = client;
		this.config = config;
	}

	/** The clan server's list arrived (or our own ::shame / ::unshame went through). */
	public void setShames(Shames shames)
	{
		this.shames = shames == null ? Shames.NONE : shames;
	}

	public Shames getShames()
	{
		return shames;
	}

	/** Clan sync went off or the plugin stopped: nobody wears the dung any more. */
	public void clearShames()
	{
		shames = Shames.NONE;
		clear();
	}

	/** Every game tick: drops the dung on every shamed clanmate in view, yourself included. */
	public void onGameTick()
	{
		if (!config.rankGlow() || ++ticks % DROP_TICKS != 0)
		{
			return;
		}
		long now = System.currentTimeMillis();
		Player me = client.getLocalPlayer();
		boolean previewing = now < previewUntil;
		if (previewing && me != null)
		{
			me.createSpotAnim(SLOT, DUNG, 0, 0);
		}
		if (shames.isEmpty(now))
		{
			return;
		}
		for (Player player : client.getTopLevelWorldView().players())
		{
			if (player != null && player.getName() != null && (player == me || player.isClanMember())
				&& !(previewing && player == me) && shames.isShamed(player.getName(), now))
			{
				player.createSpotAnim(SLOT, DUNG, 0, 0);
			}
		}
	}

	/** How long ::dungfx keeps dropping the dung on you. */
	static final long PREVIEW_MILLIS = 30_000L;
	/** when the ::dungfx preview ends, epoch millis; 0 = not previewing */
	private long previewUntil;

	/**
	 * ::dungfx: drops the dung on your own character the way a real shame does, every {@link #DROP_TICKS} ticks, for
	 * 30 seconds; typed again it stops. Local only.
	 * @return true if the preview started, false if it was stopped
	 */
	public boolean preview()
	{
		long now = System.currentTimeMillis();
		if (now < previewUntil)
		{
			previewUntil = 0;
			Player me = client.getLocalPlayer();
			if (me != null)
			{
				me.removeSpotAnim(SLOT);
			}
			return false;
		}
		previewUntil = now + PREVIEW_MILLIS;
		ticks = 0;
		Player me = client.getLocalPlayer();
		if (me != null)
		{
			me.createSpotAnim(SLOT, DUNG, 0, 0);
		}
		return true;
	}

	/** Removes our dung from everyone (glows turned off or plugin stopped). */
	public void clear()
	{
		for (Player player : client.getTopLevelWorldView().players())
		{
			if (player != null)
			{
				player.removeSpotAnim(SLOT);
			}
		}
	}
}

package com.corclan.glow;

import com.corclan.icons.MemberCosmetics;
import com.corclan.sync.SyncModels;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

/**
 * Who wears the Kephri dung, from the clan server's list. A shame is a light switch on the server: it stays on until a
 * leader takes it off with ::unshame. The plugin asks for the list every 10 seconds, and a name it lists counts as
 * shamed for {@link #FRESH_MILLIS} after the list arrived. So the dung stays on while the server says so, and stops
 * soon after a leader unshames or the server can't be reached. Immutable, so it can be built on an OkHttp thread and
 * read on the client thread. Pure Java, unit tested.
 */
public final class Shames
{
	/** How long a listed name counts as shamed after the list arrived: a few missed refreshes, then it stops. */
	public static final long FRESH_MILLIS = 60_000L;
	/** Same cap as the server, so a broken answer cannot grow memory. */
	static final int MAX_SHAMES = 50;

	public static final Shames NONE = new Shames(Collections.emptyMap());

	/** {@link MemberCosmetics#key} -> epoch millis this client stops showing the dung unless a newer list says so */
	private final Map<String, Long> until;

	private Shames(Map<String, Long> until)
	{
		this.until = Collections.unmodifiableMap(until);
	}

	/**
	 * @param response   the clan server's {@code GET /v1/shames} answer
	 * @param receivedAt when it arrived, epoch millis
	 */
	public static Shames of(SyncModels.ShamesResponse response, long receivedAt)
	{
		Map<String, Long> until = new HashMap<>();
		for (SyncModels.ActiveShame shame : response.getShames())
		{
			if (shame == null || until.size() >= MAX_SHAMES)
			{
				continue;
			}
			String key = MemberCosmetics.key(shame.getRsn());
			if (!key.isEmpty())
			{
				until.put(key, receivedAt + FRESH_MILLIS);
			}
		}
		return new Shames(until);
	}

	/** True while {@code name} wears the dung. */
	public boolean isShamed(String name, long now)
	{
		Long end = until.get(MemberCosmetics.key(name));
		return end != null && now < end;
	}

	public boolean isEmpty(long now)
	{
		for (long end : until.values())
		{
			if (now < end)
			{
				return false;
			}
		}
		return true;
	}

	/** A copy with {@code name} shamed from {@code now}: our own ::shame, before the next refresh confirms it. */
	public Shames with(String name, long now)
	{
		Map<String, Long> next = new HashMap<>(until);
		next.put(MemberCosmetics.key(name), now + FRESH_MILLIS);
		return new Shames(next);
	}

	/** A copy without {@code name}: our own ::unshame, before the next refresh. */
	public Shames without(String name)
	{
		Map<String, Long> next = new HashMap<>(until);
		next.remove(MemberCosmetics.key(name));
		return new Shames(next);
	}
}

package com.corclan.glow;

import com.corclan.CorClanConfig;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

/**
 * Named members' signature auras drawn over the scene: Lavasockz's molten outline ({@link MoltenStyle}) and
 * DAYLlGHT's and JoeBoob's gem sparkles ({@link DaylightAura}, {@link NatureAura}). Drawn on this client only; players without the plugin see nothing.
 */
public class SignatureGlowOverlay extends Overlay
{
	private final Client client;
	private final CorClanConfig config;
	private final ModelOutlineRenderer outlines;
	private final LavaAura lavaAura;
	private final DaylightAura daylightAura;
	private final NatureAura natureAura;

	@Inject
	SignatureGlowOverlay(Client client, CorClanConfig config, ModelOutlineRenderer outlines, LavaAura lavaAura,
		DaylightAura daylightAura, NatureAura natureAura)
	{
		this.client = client;
		this.config = config;
		this.outlines = outlines;
		this.lavaAura = lavaAura;
		this.daylightAura = daylightAura;
		this.natureAura = natureAura;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPriority(PRIORITY_HIGH);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.rankGlow())
		{
			return null;
		}
		long now = System.currentTimeMillis();
		for (Player player : client.getTopLevelWorldView().players())
		{
			if (lavaAura.effectsFor(player).contains(DevGlow.MOLTEN_OUTLINE))
			{
				for (GlowStyle.Layer layer : MoltenStyle.molten(now))
				{
					outlines.drawOutline(player, layer.width, layer.color, layer.feather);
				}
			}
			if (daylightAura.effectsFor(player).contains(FounderGlow.GEM_SPARKLE))
			{
				RankGlowOverlay.twinkle(graphics, player, DaylightAura.SPARKLE, now);
			}
			if (natureAura.effectsFor(player).contains(NatureGlow.EMERALD_SPARKLE))
			{
				RankGlowOverlay.twinkle(graphics, player, NatureAura.SPARKLE, now);
			}
		}
		return null;
	}
}

package com.corclan.glow;

import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Animation;
import net.runelite.api.AnimationController;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.Player;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.gameval.AnimationID;

/**
 * An upside-down copy of Nex's smoke cloud hanging over each Owner. The game can't flip a spot
 * anim, so this rebuilds it as a client-side object from the same model and animation
 * ({@code nex_mushroom_cloud_spotanim}: model 43213, anim 9201, drawn at 2x) turned over.
 * Client-side only: other players never see it. All methods must run on the client thread.
 */
@Singleton
public class StormCloud
{
	static final int MODEL_ID = 43213;
	static final int ANIMATION_ID = AnimationID.NEX_MUSHROOM_CLOUD_SPOTANIM;
	/** The spot anim draws the model at 256/128 = 2x. */
	static final int SCALE = 256;
	/** Height of the cloud's underside above the ground, in local units (a character is ~200). */
	static final int HEIGHT = 320;
	/** 2 = half the game's animation speed. */
	static final int SLOWDOWN = 2;

	private final Client client;
	private final Map<Player, RuneLiteObject> clouds = new IdentityHashMap<>();
	/** Built once, when the model has loaded from the cache; null until then. */
	private Model model;
	private Animation animation;

	@Inject
	StormCloud(Client client)
	{
		this.client = client;
	}

	/** Keeps exactly one cloud per Owner in view. Call every game tick. */
	public void update(List<Player> owners)
	{
		clouds.entrySet().removeIf(e ->
		{
			if (owners.contains(e.getKey()))
			{
				return false;
			}
			e.getValue().setActive(false);
			return true;
		});
		if (owners.isEmpty() || !loaded())
		{
			return;
		}
		for (Player owner : owners)
		{
			clouds.computeIfAbsent(owner, this::spawn);
		}
	}

	/** Moves each cloud to its Owner. Call every client frame so it follows smoothly. */
	public void follow()
	{
		clouds.forEach((owner, cloud) -> place(cloud, owner));
	}

	public void clear()
	{
		clouds.values().forEach(cloud -> cloud.setActive(false));
		clouds.clear();
	}

	private boolean loaded()
	{
		if (model == null)
		{
			ModelData data = client.loadModelData(MODEL_ID);
			if (data == null)
			{
				// not in the cache yet; try again next tick
				return false;
			}
			model = flip(data.cloneVertices());
			animation = client.loadAnimation(ANIMATION_ID);
		}
		return true;
	}

	/**
	 * Scales to the spot anim's size and turns it upside down, then lights it as the game lights
	 * spot anims. Negating Y and Z is a 180 degree rotation (not a mirror), so faces keep their
	 * winding and stay visible. Afterwards the cloud's old top is its underside, at the origin.
	 */
	private static Model flip(ModelData data)
	{
		data.scale(SCALE, -SCALE, -SCALE);
		// in model space up is -Y; the flipped cloud now hangs below the origin, so lift it by its height
		float lowest = 0;
		for (float y : data.getVerticesY())
		{
			lowest = Math.max(lowest, y);
		}
		data.translate(0, -Math.round(lowest), 0);
		// spot anims are lit with ambient 64 + their own (64) and contrast 850
		return data.light(128, 850, -30, -50, -30);
	}

	private RuneLiteObject spawn(Player owner)
	{
		RuneLiteObject cloud = new SlowObject(client, SLOWDOWN);
		cloud.setModel(model);
		// each cloud has its own controller (its own frame), restarting itself whenever it finishes
		cloud.setAnimationController(new AnimationController(client, animation).setOnFinished(AnimationController::loop));
		place(cloud, owner);
		cloud.setActive(true);
		return cloud;
	}

	private void place(RuneLiteObject cloud, Player owner)
	{
		LocalPoint at = owner.getLocalLocation();
		if (at == null)
		{
			return;
		}
		cloud.setLocation(at, owner.getWorldView().getPlane());
		// setLocation puts it on the ground; Z grows downward, so subtract to raise it
		cloud.setZ(cloud.getZ() - HEIGHT);
	}

	/** A RuneLiteObject whose animation runs {@code slowdown} times slower than the game's. */
	static final class SlowObject extends RuneLiteObject
	{
		private final int slowdown;
		private int pending;

		SlowObject(Client client, int slowdown)
		{
			super(client);
			this.slowdown = slowdown;
		}

		@Override
		public void tick(int ticks)
		{
			pending += ticks;
			int pass = pending / slowdown;
			pending -= pass * slowdown;
			super.tick(pass);
		}
	}
}

package com.corclan.glow;

import java.nio.BufferUnderflowException;
import java.nio.ByteBuffer;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Animation;
import net.runelite.api.AnimationController;
import net.runelite.api.Client;
import net.runelite.api.IndexDataBase;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.Player;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.coords.LocalPoint;

/**
 * A game graphic recolored and kept on each wearer. Spot anims can't be recolored, so like {@link StormCloud}
 * this rebuilds one as a client-side object from the same model and animation (taken from the cache's spot
 * anim definitions, see {@link #CATALOG}, or read from the game cache for any other id), with every face turned to one
 * {@link Tint}. It can also drift upwards on a loop, play slower than the game would and be drawn bigger. Client-side only: other players never see it. All instance methods run on the client thread.
 */
public class TintedFx
{
	public enum Tint
	{
		/** deep red, keeping the graphic's light and shade */
		RED,
		/** near black, a hint of the shading left so it still has shape */
		BLACK,
		/** leaf green, keeping the light and shade (JoeBoob's nature aura) */
		GREEN,
		/** the graphic's own colours */
		NONE
	}

	/** A spot anim's model, animation, size and lighting, as the cache defines it. */
	static final class Def
	{
		final int spotId;
		final String name;
		final int model;
		final int animation;
		/** 128 = the model's own size */
		final int resizeH;
		final int resizeV;
		final int ambient;
		final int contrast;

		Def(int spotId, String name, int model, int animation, int resizeH, int resizeV, int ambient, int contrast)
		{
			this.spotId = spotId;
			this.name = name;
			this.model = model;
			this.animation = animation;
			this.resizeH = resizeH;
			this.resizeV = resizeV;
			this.ambient = ambient;
			this.contrast = contrast;
		}
	}

	/** Graphics ::dayfx can switch to, by spot anim id. Fires first, then swirls. */
	static final Map<Integer, Def> CATALOG;

	static
	{
		Map<Integer, Def> defs = new LinkedHashMap<>();
		// Tormented Demons (Lucien's undead demons in the cache)
		add(defs, new Def(2852, "Tormented Demon explosion fire", 53283, 11400, 128, 128, 15, 100));
		add(defs, new Def(2849, "Tormented Demon shield", 53283, 11399, 128, 128, 15, 100));
		add(defs, new Def(2850, "Tormented Demon shield restore", 53283, 11401, 128, 128, 15, 100));
		add(defs, new Def(2847, "Tormented Demon summon", 53283, 11402, 128, 128, 15, 100));
		add(defs, new Def(2848, "Tormented Demon death", 53282, 11403, 128, 128, 15, 100));
		add(defs, new Def(2855, "Tormented Demon large fireball", 54031, 11405, 160, 160, 15, 100));
		// other fires
		add(defs, new Def(78, "Flames of Zamorak", 2267, 901, 128, 128, 75, 75));
		add(defs, new Def(2582, "Forestry campfire", 40988, 10574, 128, 128, 10, 100));
		add(defs, new Def(3741, "Flames of Cerberus", 60214, 13756, 128, 128, 10, 60));
		add(defs, new Def(3280, "Yama fire immunity", 14824, 12176, 128, 128, 30, 100));
		// swirls
		add(defs, new Def(1394, "Wyvern cyclone", 33883, 7655, 128, 128, 0, 0));
		add(defs, new Def(56, "Vanguard swirl (short)", 39582, 8643, 126, 96, 20, 156));
		add(defs, new Def(57, "Vanguard swirl (tall)", 39582, 8643, 126, 150, 20, 156));
		add(defs, new Def(1177, "Pest Control spiral", 27160, 6888, 128, 128, 20, 0));
		add(defs, new Def(1296, "Arceuus teleport swirl", 31002, 7162, 128, 128, 20, 0));
		add(defs, new Def(2507, "Leviathan tornado", 35398, 8100, 128, 128, 50, 50));
		add(defs, new Def(3587, "Beef tornado", 59402, 13802, 128, 128, 0, 0));
		add(defs, new Def(642, "Smoke devil cloud", 28443, 3857, 128, 128, 0, 0));
		add(defs, new Def(1488, "Rune dragon electro-vortex", 14557, 3912, 128, 128, 0, 0));
		CATALOG = Collections.unmodifiableMap(defs);
	}

	private static void add(Map<Integer, Def> defs, Def def)
	{
		defs.put(def.spotId, def);
	}

	/** The config index archive that holds the spot anim definitions. */
	static final int SPOTANIM_ARCHIVE = 13;

	/**
	 * A spot anim definition from the game cache's bytes, or null if they hold something this reader doesn't know
	 * (a newer cache format), so a bad read never draws garbage. Opcodes as in RuneLite's cache SpotAnimLoader.
	 */
	static Def parseDef(int spotId, byte[] data)
	{
		if (data == null)
		{
			return null;
		}
		ByteBuffer in = ByteBuffer.wrap(data);
		int model = -1;
		int animation = -1;
		int resizeH = 128;
		int resizeV = 128;
		int ambient = 0;
		int contrast = 0;
		try
		{
			while (true)
			{
				int opcode = in.get() & 0xFF;
				switch (opcode)
				{
					case 0:
						return model < 0 ? null : new Def(spotId, "spot anim " + spotId, model, animation, resizeH, resizeV, ambient, contrast);
					case 1:
						model = in.getShort() & 0xFFFF;
						break;
					case 2:
						animation = in.getShort() & 0xFFFF;
						break;
					case 3:
						model = in.getInt();
						break;
					case 4:
						resizeH = in.getShort() & 0xFFFF;
						break;
					case 5:
						resizeV = in.getShort() & 0xFFFF;
						break;
					case 6:
						// rotation: not used here
						in.getShort();
						break;
					case 7:
						ambient = in.get() & 0xFF;
						break;
					case 8:
						contrast = in.get() & 0xFF;
						break;
					case 9:
						// debug name, a zero-terminated string
						while (in.get() != 0)
						{
						}
						break;
					case 10:
						break;
					case 40:
					case 41:
						// recolours / retextures: a count, then pairs of shorts
						int count = in.get() & 0xFF;
						in.position(in.position() + count * 4);
						break;
					case 42:
						in.getShort();
						break;
					default:
						return null;
				}
			}
		}
		catch (BufferUnderflowException | IllegalArgumentException e)
		{
			return null;
		}
	}

	/** {@link #CATALOG}'s entry, else the definition read from the game cache, else null. Client thread. */
	private Def lookUp(int spotId)
	{
		Def known = CATALOG.get(spotId);
		if (known != null)
		{
			return known;
		}
		IndexDataBase config = client.getIndexConfig();
		return config == null ? null : parseDef(spotId, config.loadData(SPOTANIM_ARCHIVE, spotId));
	}

	/**
	 * Plays an animation at a fraction of the game's speed: the client hands each object the time that passed, and
	 * this passes on only {@code speed} of it, carrying the remainder so nothing is lost.
	 */
	static final class PacedController extends AnimationController
	{
		private final double speed;
		private double owed;

		PacedController(Client client, Animation animation, double speed)
		{
			super(client, animation);
			this.speed = speed;
		}

		@Override
		public void tick(int ticks)
		{
			owed += ticks * speed;
			int whole = (int) owed;
			owed -= whole;
			if (whole > 0)
			{
				super.tick(whole);
			}
		}
	}

	/**
	 * One face color (the game's 16-bit HSL: 6 bits hue, 3 saturation, 7 lightness) turned to {@code tint}.
	 * Lightness is kept, so the graphic keeps its shading.
	 */
	static short tint(short hsl, Tint tint)
	{
		int lum = hsl & 127;
		switch (tint)
		{
			case RED:
				// hue 0 is red; capping the lightness stops the hot core washing out to pink
				return (short) (7 << 7 | Math.min(lum, 90));
			case BLACK:
				return (short) (lum / 6);
			case NONE:
				return hsl;
			case GREEN:
				// hue 21 of 64 is green; a little less than full saturation looks like leaves, not neon
				return (short) (21 << 10 | 6 << 7 | Math.min(lum, 100));
			default:
				return hsl;
		}
	}

	private final Client client;
	private final Tint tint;
	/** 1 = the game's own speed, 0.5 = half as fast */
	private final double speed;
	/** 1 = the graphic's own size, 2 = twice as big */
	private final double scale;
	/** the spot anim asked for before its definition was read */
	private int wantedSpotId;
	/** a spot anim whose definition could not be read, so it is not read again every frame */
	private int unreadableSpotId = -1;
	private final Map<Player, RuneLiteObject> objects = new IdentityHashMap<>();
	private Def def;
	/** how far it climbs each loop, in local units (a character is ~200); 0 stays put */
	private int rise;
	private long riseMillis;
	/** Built once the model has loaded from the cache; null until then. */
	private Model model;
	private Animation animation;

	/**
	 * @param rise       how far it climbs each loop, in local units; 0 stays at the feet
	 * @param riseMillis how long one climb takes
	 */
	TintedFx(Client client, Tint tint, int spotId, int rise, long riseMillis)
	{
		this(client, tint, spotId, rise, riseMillis, 1.0, 1.0);
	}

	/**
	 * @param speed 1 for the game's own speed, below 1 to play it slower
	 * @param scale 1 for the graphic's own size, 2 for twice as big
	 */
	TintedFx(Client client, Tint tint, int spotId, int rise, long riseMillis, double speed, double scale)
	{
		this.client = client;
		this.tint = tint;
		this.wantedSpotId = spotId;
		this.def = CATALOG.get(spotId);
		this.rise = rise;
		this.riseMillis = riseMillis;
		this.speed = speed;
		this.scale = scale;
	}

	/**
	 * Uses another graphic (and climb height) from now on: one in {@link #CATALOG} or any spot anim in the game
	 * cache. False if it can't be read. Client thread.
	 */
	boolean use(int spotId, int rise)
	{
		Def next = lookUp(spotId);
		if (next == null)
		{
			return false;
		}
		clear();
		def = next;
		wantedSpotId = spotId;
		this.rise = rise;
		model = null;
		animation = null;
		return true;
	}

	int spotId()
	{
		return def == null ? wantedSpotId : def.spotId;
	}

	/** Keeps exactly one object on each of {@code wearers}, following them. Call every client frame. */
	void update(List<Player> wearers)
	{
		objects.entrySet().removeIf(e ->
		{
			if (wearers.contains(e.getKey()))
			{
				return false;
			}
			e.getValue().setActive(false);
			return true;
		});
		if (wearers.isEmpty() || !loaded())
		{
			return;
		}
		long now = System.currentTimeMillis();
		for (Player wearer : wearers)
		{
			place(objects.computeIfAbsent(wearer, this::spawn), wearer, now);
		}
	}

	void clear()
	{
		objects.values().forEach(object -> object.setActive(false));
		objects.clear();
	}

	private boolean loaded()
	{
		if (def == null)
		{
			if (wantedSpotId == unreadableSpotId)
			{
				return false;
			}
			def = lookUp(wantedSpotId);
			if (def == null)
			{
				unreadableSpotId = wantedSpotId;
				return false;
			}
		}
		if (model == null)
		{
			ModelData data = client.loadModelData(def.model);
			if (data == null)
			{
				// not in the cache yet; try again next frame
				return false;
			}
			data = data.cloneVertices().cloneColors();
			int width = (int) Math.round(def.resizeH * scale);
			int height = (int) Math.round(def.resizeV * scale);
			if (width != 128 || height != 128)
			{
				data.scale(width, height, width);
			}
			// change every face in place; recolor() would merge faces whose new color matches an old one
			short[] colors = data.getFaceColors();
			for (int i = 0; i < colors.length; i++)
			{
				colors[i] = tint(colors[i], tint);
			}
			// spot anims are lit with ambient 64 + their own and contrast 850 + their own
			model = data.light(64 + def.ambient, 850 + def.contrast, -30, -50, -30);
			animation = def.animation < 0 ? null : client.loadAnimation(def.animation);
		}
		return true;
	}

	private RuneLiteObject spawn(Player wearer)
	{
		RuneLiteObject object = client.createRuneLiteObject();
		object.setModel(model);
		// each object has its own controller (its own frame), restarting itself whenever it finishes
		if (animation != null)
		{
			AnimationController controller = speed == 1.0
				? new AnimationController(client, animation)
				: new PacedController(client, animation, speed);
			object.setAnimationController(controller.setOnFinished(AnimationController::loop));
		}
		object.setActive(true);
		return object;
	}

	private void place(RuneLiteObject object, Player wearer, long now)
	{
		LocalPoint at = wearer.getLocalLocation();
		if (at == null)
		{
			return;
		}
		object.setLocation(at, wearer.getWorldView().getPlane());
		if (rise > 0)
		{
			// setLocation puts it on the ground; Z grows downward, so subtract to raise it
			double climb = Math.floorMod(now, riseMillis) / (double) riseMillis;
			object.setZ(object.getZ() - (int) (rise * climb));
		}
	}
}

package com.corclan.glow;

import java.util.ArrayList;
import java.util.List;

/**
 * Twinkling stars on a gem glow's wearer. Each star blooms and fades over one period, then reappears
 * somewhere else; the stars are staggered so some are always lit. Positions are fractions of the wearer's
 * on-screen bounds and depend only on the seed and the time, so every frame (and every viewer) agrees
 * without keeping state. Pure Java so it can be unit tested.
 */
public final class Twinkle
{
	/** one star's bloom and fade */
	static final long PERIOD_MILLIS = 1400L;

	/** One star this frame. */
	public static final class Star
	{
		/** 0..1 across the wearer's bounds, left to right */
		public final double x;
		/** 0..1 down the wearer's bounds, top to bottom */
		public final double y;
		/** 0 (unlit) .. 1 (full bloom) */
		public final double size;

		Star(double x, double y, double size)
		{
			this.x = x;
			this.y = y;
			this.size = size;
		}
	}

	private Twinkle()
	{
	}

	/**
	 * @param seed  keeps each wearer's stars in their own places, e.g. their name's hash
	 * @param count stars twinkling at once
	 * @param now   current time in millis
	 */
	public static List<Star> stars(long seed, int count, long now)
	{
		List<Star> stars = new ArrayList<>(count);
		for (int i = 0; i < count; i++)
		{
			// stagger the stars evenly through the period
			long t = now + i * PERIOD_MILLIS / count + Math.floorMod(seed, PERIOD_MILLIS);
			long cycle = Math.floorDiv(t, PERIOD_MILLIS);
			double phase = Math.floorMod(t, PERIOD_MILLIS) / (double) PERIOD_MILLIS;
			// a sharp bloom: quick to light, quick to fade
			double bloom = Math.sin(phase * Math.PI);
			long place = mix(seed * 31 + i * 0x9E3779B97F4A7C15L + cycle);
			stars.add(new Star(unit(place), unit(mix(place)), bloom * bloom));
		}
		return stars;
	}

	/** splitmix64: scrambles a number into well spread bits */
	private static long mix(long z)
	{
		z = (z ^ (z >>> 30)) * 0xBF58476D1CE4E5B9L;
		z = (z ^ (z >>> 27)) * 0x94D049BB133111EBL;
		return z ^ (z >>> 31);
	}

	/** 0..1 from the top 53 bits */
	private static double unit(long bits)
	{
		return (bits >>> 11) / (double) (1L << 53);
	}
}

package com.corclan.gz;

import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Pure text logic that turns a clan system broadcast ("Zezima has received a drop: ...") into the
 * name of the member being congratulated, or {@code null} when the broadcast is not gz-worthy
 * (coffer transactions, invites, kicks, deaths ...).
 */
public final class BroadcastParser
{
	/** Broadcasts containing any of these are never gz-worthy. */
	private static final List<String> IGNORE_FRAGMENTS = Arrays.asList(
		"coffer",
		"has been invited",
		"has invited",
		"has left the clan",
		"has been kicked",
		"has been removed",
		"has been promoted",
		"has been demoted",
		"has died",
		"has been defeated",
		"lost their hardcore",
		"welcome to",
		"has logged",
		"is now"
	);

	/** "&lt;name&gt; has ..." / "&lt;name&gt; received ..." / "&lt;name&gt; feels ..." */
	private static final Pattern SUBJECT = Pattern.compile(
		"^(.+?)\\s+(?:has|have|received|feels|just|got)\\b",
		Pattern.CASE_INSENSITIVE);

	private BroadcastParser()
	{
	}

	/**
	 * @return the member the broadcast is about, or {@code null} if the broadcast should be ignored
	 */
	public static String subjectOf(String broadcast)
	{
		if (broadcast == null)
		{
			return null;
		}
		String text = clean(broadcast);
		if (text.isEmpty())
		{
			return null;
		}
		String lower = text.toLowerCase(Locale.ROOT);
		for (String fragment : IGNORE_FRAGMENTS)
		{
			if (lower.contains(fragment))
			{
				return null;
			}
		}
		Matcher m = SUBJECT.matcher(text);
		if (!m.find())
		{
			return null;
		}
		String subject = m.group(1).trim();
		// player names are 1-12 chars; anything longer is not a name
		if (subject.isEmpty() || subject.length() > 12)
		{
			return null;
		}
		return subject;
	}

	/** Strips tags, replaces non-breaking spaces / underscores and collapses whitespace. */
	public static String clean(String text)
	{
		return text
			.replaceAll("<[^>]*>", "")
			.replace(' ', ' ')
			.replace('_', ' ')
			.replaceAll("\\s+", " ")
			.trim();
	}
}

