package com.corclan.gz;

import java.util.Locale;

/**
 * The clan's daily "gm": the first gm a member says in clan chat each day (UTC) earns a pack's worth of TCG points
 * from the clan server. Gm's are not counted or shown anywhere. Same rule as the server's isGm, so only a real gm is
 * ever sent. Pure logic.
 */
public final class DailyGm
{
	public static final int MAX_LENGTH = 80;
	private static final long DAY_MILLIS = 24L * 60 * 60 * 1000;

	private DailyGm()
	{
	}

	/** "gm", "GM!", "gmgm", "gmmm all", "good morning" ... but not "gmail" or "dogma". */
	public static boolean isGm(String message)
	{
		if (message == null)
		{
			return false;
		}
		String trimmed = message.trim();
		if (trimmed.isEmpty() || trimmed.length() > MAX_LENGTH)
		{
			return false;
		}
		String words = trimmed.toLowerCase(Locale.ROOT)
			.replaceAll("<[^>]*>", "")
			.replaceAll("[^a-z\\s]", " ")
			.trim()
			.replaceAll("\\s+", " ");
		if (words.isEmpty())
		{
			return false;
		}
		for (String word : words.split(" "))
		{
			if (word.matches("(gm)+m*"))
			{
				return true;
			}
		}
		return words.contains("good morning") || words.contains("goodmorning");
	}

	/** The UTC day {@code millis} falls in, as a day number; the gm bonus resets when it changes. */
	public static long utcDay(long millis)
	{
		return Math.floorDiv(millis, DAY_MILLIS);
	}
}

package com.corclan.gz;

import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

/**
 * Pure text logic that decides whether a clan chat line is a "gz" (congratulations).
 * No RuneLite dependencies so it can be unit tested directly.
 */
public final class GzDetector
{
	private static final Set<String> GZ_TOKENS = Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
		"gz", "gzs",
		"grats", "gratz", "grtz", "gratulations", "gratulation",
		"congrats", "congratz", "congratulations", "congratulation"
	)));

	/**
	 * Spam written as one word: gz words run together ("gzgzgz", "gratzgz"), optionally ending in a
	 * cut-off "g" ("gzgzgzg"). Longest alternatives first so "gzs" isn't read as "gz" + "s".
	 */
	private static final Pattern GZ_RUN = Pattern.compile("(?:" + GZ_TOKENS.stream()
		.sorted(Comparator.comparingInt(String::length).reversed())
		.collect(Collectors.joining("|")) + ")+g?");

	private GzDetector()
	{
	}

	/**
	 * @param message   raw chat message (may contain caps, punctuation, repeated letters)
	 * @param maxLength messages longer than this are never counted, so "gz" buried in a long
	 *                  unrelated sentence does not count
	 */
	public static boolean isGz(String message, int maxLength)
	{
		if (message == null)
		{
			return false;
		}
		String trimmed = message.trim();
		if (trimmed.isEmpty() || trimmed.length() > maxLength)
		{
			return false;
		}
		String normalized = normalize(trimmed);
		if (normalized.isEmpty())
		{
			return false;
		}
		for (String token : normalized.split(" "))
		{
			if (GZ_TOKENS.contains(token) || GZ_RUN.matcher(token).matches())
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Lower-cases, drops everything except letters and spaces, and collapses runs of the same
	 * letter ("gzzzz" -> "gz", "graaats" -> "grats").
	 */
	static String normalize(String message)
	{
		String lower = message.toLowerCase(Locale.ROOT);
		StringBuilder sb = new StringBuilder(lower.length());
		char prev = 0;
		for (int i = 0; i < lower.length(); i++)
		{
			char c = lower.charAt(i);
			boolean letter = c >= 'a' && c <= 'z';
			if (!letter && c != ' ')
			{
				// punctuation / digits / emoji act as separators
				c = ' ';
			}
			if (c == prev && c != ' ')
			{
				continue;
			}
			if (c == ' ' && prev == ' ')
			{
				continue;
			}
			sb.append(c);
			prev = c;
		}
		return sb.toString().trim();
	}
}

package com.corclan.gz;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

/** Counters for gz's given and received. Serialized to RuneLite config as JSON with Gson. */
public class GzStats
{
	public static final int MAX_RECENT = 10;

	private Map<String, Integer> given = new HashMap<>();
	private Map<String, Integer> received = new HashMap<>();
	private List<BroadcastRecord> recent = new ArrayList<>();

	public Map<String, Integer> getGiven()
	{
		if (given == null)
		{
			given = new HashMap<>();
		}
		return given;
	}

	public Map<String, Integer> getReceived()
	{
		if (received == null)
		{
			received = new HashMap<>();
		}
		return received;
	}

	public List<BroadcastRecord> getRecent()
	{
		if (recent == null)
		{
			recent = new ArrayList<>();
		}
		return recent;
	}

	void addGiven(String name)
	{
		getGiven().merge(name, 1, Integer::sum);
	}

	void addReceived(String name)
	{
		getReceived().merge(name, 1, Integer::sum);
	}

	void addRecent(BroadcastRecord record)
	{
		List<BroadcastRecord> list = getRecent();
		list.add(0, record);
		while (list.size() > MAX_RECENT)
		{
			list.remove(list.size() - 1);
		}
	}

	public int totalGiven()
	{
		return getGiven().values().stream().mapToInt(Integer::intValue).sum();
	}

	public int totalReceived()
	{
		return getReceived().values().stream().mapToInt(Integer::intValue).sum();
	}

	/** Top entries, highest first, ties broken by name. */
	public static List<Map.Entry<String, Integer>> top(Map<String, Integer> counts, int limit)
	{
		return counts.entrySet().stream()
			.sorted(Comparator.comparing((Map.Entry<String, Integer> e) -> e.getValue()).reversed()
				.thenComparing(Map.Entry::getKey))
			.limit(limit)
			.collect(Collectors.toList());
	}

	public String topGiver()
	{
		List<Map.Entry<String, Integer>> top = top(getGiven(), 1);
		return top.isEmpty() ? null : top.get(0).getKey();
	}
}

package com.corclan.gz;

import java.time.DayOfWeek;
import java.time.Instant;
import java.time.ZoneId;
import java.time.temporal.TemporalAdjusters;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * Attributes gz messages to the most recent clan broadcast while its window is open.
 * Pure Java: the plugin feeds it chat events and persists {@link #getAllTime()} when
 * {@link #onClanChat} reports a change.
 */
public class GzTracker
{
	private final ZoneId zone;
	private GzStats allTime = new GzStats();
	private GzStats session = new GzStats();
	// counts since the most recent Sunday 00:00 in {@link #zone}; rolled over by rollWeek
	private GzStats weekly = new GzStats();
	private long weekStart;
	// #1 giver(s) of each finished week, for streaks
	private List<WeekResult> weekResults = new ArrayList<>();
	private BroadcastRecord current;

	/** Anti-abuse: at most this many gz's per player are counted in any rolling hour. */
	public static final int MAX_GZ_PER_HOUR = 100;
	static final long HOUR_MILLIS = 3_600_000L;
	/** when each player's recently counted gz's happened, oldest first; only the last hour is kept */
	private final Map<String, ArrayDeque<Long>> recentGz = new HashMap<>();

	// last counted gz, for the on-screen indicator
	private long lastGzTime;
	private String lastGzGiver;
	private String lastGzSubject;

	/** Weeks start Sunday 00:00 UTC, so every CoR member's week lines up with the clan server's. */
	public static final ZoneId WEEK_ZONE = ZoneId.of("UTC");

	public GzTracker()
	{
		this(WEEK_ZONE);
	}

	/** @param zone time zone whose Sunday midnight starts a new week */
	public GzTracker(ZoneId zone)
	{
		this.zone = zone;
	}

	/** Epoch millis of the Sunday 00:00 (in {@code zone}) on or before {@code now}. */
	public static long weekStartOf(long now, ZoneId zone)
	{
		return Instant.ofEpochMilli(now).atZone(zone).toLocalDate()
			.with(TemporalAdjusters.previousOrSame(DayOfWeek.SUNDAY))
			.atStartOfDay(zone).toInstant().toEpochMilli();
	}

	/**
	 * Starts a fresh weekly count if {@code now} is in a later week than the current one,
	 * recording the finished week's #1 giver(s) first.
	 * @return true if the weekly stats were reset (caller should persist)
	 */
	public boolean rollWeek(long now)
	{
		long start = weekStartOf(now, zone);
		if (start > weekStart)
		{
			List<String> winners = topGivers(weekly);
			if (weekStart != 0 && !winners.isEmpty())
			{
				weekResults.add(new WeekResult(weekStart, winners));
			}
			weekly = new GzStats();
			weekStart = start;
			return true;
		}
		return false;
	}

	/** Everyone tied for the most gz's given, or empty if nobody gave any. */
	private static List<String> topGivers(GzStats stats)
	{
		List<String> out = new ArrayList<>();
		int max = stats.getGiven().values().stream().mapToInt(Integer::intValue).max().orElse(0);
		if (max > 0)
		{
			stats.getGiven().forEach((name, n) ->
			{
				if (n == max)
				{
					out.add(name);
				}
			});
			Collections.sort(out);
		}
		return out;
	}

	public void loadWeekResults(List<WeekResult> results)
	{
		weekResults = results != null ? new ArrayList<>(results) : new ArrayList<>();
	}

	public List<WeekResult> getWeekResults()
	{
		return weekResults;
	}

	/** Longest run of consecutive weekly #1s ever, or null. */
	public Streaks.Streak longestStreak()
	{
		return Streaks.longest(weekResults, zone);
	}

	/** Run of weekly #1s that includes last week, or null. */
	public Streaks.Streak currentStreak()
	{
		return Streaks.current(weekResults, weekStart, zone);
	}

	public void loadWeekly(GzStats stats, long weekStart)
	{
		weekly = stats != null ? stats : new GzStats();
		this.weekStart = weekStart;
	}

	public GzStats getWeekly()
	{
		return weekly;
	}

	public long getWeekStart()
	{
		return weekStart;
	}

	public long getLastGzTime()
	{
		return lastGzTime;
	}

	public String getLastGzGiver()
	{
		return lastGzGiver;
	}

	/** Who the last gz was credited to, or null if no broadcast window was open. */
	public String getLastGzSubject()
	{
		return lastGzSubject;
	}

	public void load(GzStats stats)
	{
		allTime = stats != null ? stats : new GzStats();
		session = new GzStats();
		current = null;
	}

	public GzStats getAllTime()
	{
		return allTime;
	}

	public GzStats getSession()
	{
		return session;
	}

	public void resetAllTime()
	{
		allTime = new GzStats();
		weekly = new GzStats();
		weekResults = new ArrayList<>();
		current = null;
	}

	public void resetSession()
	{
		session = new GzStats();
	}

	/**
	 * When each player's gz's in the last hour were counted, so the hourly cap survives a client restart
	 * (otherwise restarting RuneLite would hand everyone a fresh 100). Saved with the stats.
	 */
	public Map<String, List<Long>> getRecentGz(long now)
	{
		Map<String, List<Long>> out = new HashMap<>();
		recentGz.forEach((name, times) ->
		{
			List<Long> recent = new ArrayList<>();
			for (Long t : times)
			{
				if (now - t < HOUR_MILLIS)
				{
					recent.add(t);
				}
			}
			if (!recent.isEmpty())
			{
				out.put(name, recent);
			}
		});
		return out;
	}

	/** Restores {@link #getRecentGz}; anything older than an hour, or beyond the cap, is dropped. */
	public void loadRecentGz(Map<String, List<Long>> saved, long now)
	{
		recentGz.clear();
		if (saved == null)
		{
			return;
		}
		saved.forEach((name, times) ->
		{
			if (name == null || times == null)
			{
				return;
			}
			ArrayDeque<Long> kept = new ArrayDeque<>();
			times.stream()
				.filter(t -> t != null && now - t < HOUR_MILLIS && t <= now)
				.sorted()
				.forEach(kept::addLast);
			while (kept.size() > MAX_GZ_PER_HOUR)
			{
				kept.pollFirst();
			}
			if (!kept.isEmpty())
			{
				recentGz.put(name.toLowerCase(Locale.ROOT), kept);
			}
		});
	}

	/** @return the broadcast currently accepting gz's, or null if none / expired */
	public BroadcastRecord currentWindow(long now, long windowMillis)
	{
		if (current != null && current.isOpen(now, windowMillis))
		{
			return current;
		}
		return null;
	}

	/**
	 * @param subject the member being congratulated (from {@link BroadcastParser#subjectOf})
	 * @return the record that now accepts gz's
	 */
	public BroadcastRecord onBroadcast(String subject, String text, long now)
	{
		rollWeek(now);
		BroadcastRecord record = new BroadcastRecord(subject, text, now);
		current = record;
		allTime.addRecent(record);
		session.addRecent(record);
		return record;
	}

	/**
	 * Records a gz for {@code sender} if they've had fewer than {@link #MAX_GZ_PER_HOUR} counted in
	 * the last hour. Names are compared case-insensitively so "Bob" and "bob" share one allowance.
	 * @return false if the gz is over the cap and must not be counted
	 */
	private boolean underHourlyCap(String sender, long now)
	{
		String key = sender.toLowerCase(Locale.ROOT);
		ArrayDeque<Long> times = recentGz.computeIfAbsent(key, k -> new ArrayDeque<>());
		while (!times.isEmpty() && now - times.peekFirst() >= HOUR_MILLIS)
		{
			times.pollFirst();
		}
		if (times.size() >= MAX_GZ_PER_HOUR)
		{
			return false;
		}
		times.addLast(now);
		// drop players with nothing in the last hour so the map can't grow forever
		if (recentGz.size() > 500)
		{
			recentGz.values().removeIf(t -> t.isEmpty() || now - t.peekLast() >= HOUR_MILLIS);
		}
		return true;
	}

	public boolean onClanChat(String sender, String message, long now, Settings settings)
	{
		if (sender == null || sender.isEmpty() || !GzDetector.isGz(message, settings.maxMessageLength)
			|| !underHourlyCap(sender, now))
		{
			return false;
		}
		rollWeek(now);
		allTime.addGiven(sender);
		session.addGiven(sender);
		weekly.addGiven(sender);
		lastGzTime = now;
		lastGzGiver = sender;
		lastGzSubject = null;

		BroadcastRecord window = currentWindow(now, settings.windowMillis);
		if (window != null
			&& !sender.equalsIgnoreCase(window.getSubject())
			&& (!settings.oneGzPerPersonPerBroadcast || !window.getGivers().contains(sender)))
		{
			window.addGz(sender);
			allTime.addReceived(window.getSubject());
			session.addReceived(window.getSubject());
			weekly.addReceived(window.getSubject());
			lastGzSubject = window.getSubject();
		}
		return true;
	}

	/** Snapshot of the config values the tracker needs. */
	public static final class Settings
	{
		public final long windowMillis;
		public final boolean oneGzPerPersonPerBroadcast;
		public final int maxMessageLength;

		public Settings(long windowMillis, boolean oneGzPerPersonPerBroadcast, int maxMessageLength)
		{
			this.windowMillis = windowMillis;
			this.oneGzPerPersonPerBroadcast = oneGzPerPersonPerBroadcast;
			this.maxMessageLength = maxMessageLength;
		}
	}
}

package com.corclan.gz;

import java.time.ZoneId;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import java.util.concurrent.TimeUnit;

/**
 * Runs of consecutive weeks at #1 on the weekly gz podium. A week with no recorded winner
 * (nobody gz'd, or this client wasn't running) breaks every run.
 */
public final class Streaks
{
	/** One or more players (ties) holding a run of {@link #weeks} weeks. */
	public static final class Streak
	{
		public final Set<String> players;
		public final int weeks;

		Streak(Set<String> players, int weeks)
		{
			this.players = Collections.unmodifiableSet(players);
			this.weeks = weeks;
		}
	}

	private Streaks()
	{
	}

	/** Longest run in the whole history, or null if no week has a winner yet. */
	public static Streak longest(List<WeekResult> history, ZoneId zone)
	{
		int best = 0;
		Set<String> holders = new TreeSet<>();
		for (Map<String, Integer> runs : runsPerWeek(history, zone))
		{
			for (Map.Entry<String, Integer> e : runs.entrySet())
			{
				if (e.getValue() > best)
				{
					best = e.getValue();
					holders.clear();
				}
				if (e.getValue() == best)
				{
					holders.add(e.getKey());
				}
			}
		}
		return best == 0 ? null : new Streak(holders, best);
	}

	/**
	 * Longest run still alive: it must include the week right before {@code currentWeekStart}.
	 * @return null if last week had no winner
	 */
	public static Streak current(List<WeekResult> history, long currentWeekStart, ZoneId zone)
	{
		List<WeekResult> sorted = sorted(history);
		if (sorted.isEmpty() || nextWeek(sorted.get(sorted.size() - 1).getWeekStart(), zone) != currentWeekStart)
		{
			return null;
		}
		List<Map<String, Integer>> runs = runsPerWeek(sorted, zone);
		Map<String, Integer> last = runs.get(runs.size() - 1);
		if (last.isEmpty())
		{
			return null;
		}
		int best = Collections.max(last.values());
		Set<String> holders = new TreeSet<>();
		last.forEach((name, weeks) ->
		{
			if (weeks == best)
			{
				holders.add(name);
			}
		});
		return new Streak(holders, best);
	}

	/** For each week (oldest first), how many weeks in a row each of its winners has been #1. */
	private static List<Map<String, Integer>> runsPerWeek(List<WeekResult> history, ZoneId zone)
	{
		List<Map<String, Integer>> out = new ArrayList<>();
		Map<String, Integer> prevRuns = new HashMap<>();
		Long prevStart = null;
		for (WeekResult week : sorted(history))
		{
			boolean adjacent = prevStart != null && nextWeek(prevStart, zone) == week.getWeekStart();
			Map<String, Integer> runs = new HashMap<>();
			for (String winner : week.getWinners())
			{
				runs.put(winner, (adjacent ? prevRuns.getOrDefault(winner, 0) : 0) + 1);
			}
			out.add(runs);
			prevRuns = runs;
			prevStart = week.getWeekStart();
		}
		return out;
	}

	private static List<WeekResult> sorted(List<WeekResult> history)
	{
		List<WeekResult> sorted = new ArrayList<>(history);
		sorted.sort(Comparator.comparingLong(WeekResult::getWeekStart));
		return sorted;
	}

	/** Start of the week after the one starting at {@code weekStart}; DST-safe (weeks aren't always 7*24h). */
	static long nextWeek(long weekStart, ZoneId zone)
	{
		return GzTracker.weekStartOf(weekStart + TimeUnit.DAYS.toMillis(8), zone);
	}
}

package com.corclan.gz;

import java.util.ArrayList;
import java.util.List;

/** The #1 gz giver(s) of one finished week. Serialized with Gson. */
public class WeekResult
{
	private long weekStart;
	private List<String> winners = new ArrayList<>();

	public WeekResult()
	{
	}

	public WeekResult(long weekStart, List<String> winners)
	{
		this.weekStart = weekStart;
		this.winners = new ArrayList<>(winners);
	}

	/** Epoch millis of the Sunday 00:00 that began the week. */
	public long getWeekStart()
	{
		return weekStart;
	}

	/** Everyone tied for the most gz's given that week. */
	public List<String> getWinners()
	{
		if (winners == null)
		{
			winners = new ArrayList<>();
		}
		return winners;
	}
}

package com.corclan.icons;

import com.corclan.sync.SyncModels;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.clan.ClanRank;
import net.runelite.client.game.ChatIconManager;
import net.runelite.client.util.ImageUtil;

/**
 * Loads the CoR chat icons from resources, registers them with RuneLite's {@link ChatIconManager}
 * exactly once, and maps clan ranks / config keys to the {@code <img=N>} index used in chat.
 *
 * With clan sync on, icons set on the clan server's admin page replace the bundled images in place
 * (or add new icons), and turning sync off puts the bundled images back.
 */
@Slf4j
@Singleton
public class ClanIconService
{
	/** Chat icons are drawn at this size by the game. */
	private static final int ICON_SIZE = 11;

	/** Red rhino: owner, deputy owner and administrators. */
	public static final String KEY_STAFF = "staff";
	/** Blue rhino: every other member and guests. */
	public static final String KEY_MEMBER = "member";
	public static final String KEY_GZ_KING = "gzking";

	private static final List<String> RANK_KEYS = Arrays.asList(KEY_STAFF, KEY_MEMBER);

	public static final String KEY_FOUNDER = "founder";
	public static final String KEY_DEV = "dev";

	/** Built-in keys that can be given to players. Server icons with new names are added to these. */
	public static final List<String> MEMBER_KEYS = Collections.unmodifiableList(Arrays.asList(
		"crown", "trophy", "star", "skull", "gem", "fire", KEY_FOUNDER, KEY_DEV));

	/** Same rule the server enforces for icon names. */
	private static final Pattern ICON_KEY = Pattern.compile("[a-z0-9][a-z0-9_-]{0,23}");
	/** Caps how many extra icons the server can register on this client. */
	private static final int MAX_CUSTOM_ICONS = 64;

	/** Absolute path: this class sits in com.corclan.icons but the PNGs live in com/corclan/. */
	private static final String RESOURCE_DIR = "/com/corclan/";

	private final ChatIconManager chatIconManager;
	/** icon key -> ChatIconManager id; read on the client thread while the server icons are applied */
	private final Map<String, Integer> iconIds = new ConcurrentHashMap<>();
	private final Map<String, BufferedImage> bundled = new HashMap<>();
	/** icon key -> hash of the server image currently shown instead of the bundled one */
	private final Map<String, String> serverHashes = new HashMap<>();
	/** server icons with new names, which players can be given */
	private final Set<String> customKeys = ConcurrentHashMap.newKeySet();
	/** clan rank -> icon picked on the clan server; replaced whole, read on the client thread */
	private volatile Map<Integer, String> rankOverrides = Collections.emptyMap();

	@Inject
	public ClanIconService(ChatIconManager chatIconManager)
	{
		this.chatIconManager = chatIconManager;
	}

	/**
	 * Registers all bundled icons with the chat icon manager. Safe to call repeatedly; the ids are cached
	 * for the lifetime of the client so toggling the plugin never registers duplicates.
	 */
	public synchronized void ensureRegistered()
	{
		if (!bundled.isEmpty())
		{
			return;
		}
		for (String key : RANK_KEYS)
		{
			register(key, "rank_" + key + ".png");
		}
		for (String key : MEMBER_KEYS)
		{
			register(key, "member_" + key + ".png");
		}
		register(KEY_GZ_KING, "member_gzking.png");
		for (String key : WeeklyTrophies.KEYS)
		{
			register(key, key + ".png");
		}
		log.debug("Registered {} CoR chat icons", iconIds.size());
	}

	private void register(String key, String resource)
	{
		try
		{
			BufferedImage img = fit(ImageUtil.loadImageResource(ClanIconService.class, RESOURCE_DIR + resource));
			bundled.put(key, img);
			iconIds.put(key, chatIconManager.registerChatIcon(img));
		}
		catch (RuntimeException ex)
		{
			log.warn("Could not load CoR icon {}", resource, ex);
		}
	}

	/** Scales to the chat icon height, keeping the width proportional (wordmarks are wider). */
	private static BufferedImage fit(BufferedImage img)
	{
		if (img.getHeight() == ICON_SIZE)
		{
			return img;
		}
		int width = Math.max(1, Math.round(img.getWidth() * (float) ICON_SIZE / img.getHeight()));
		return ImageUtil.resizeImage(img, width, ICON_SIZE);
	}

	/**
	 * Applies the icon images from the clan server. Call on the client thread.
	 *
	 * @return true if any icon changed, so chat should be redrawn
	 */
	public synchronized boolean applyServerIcons(List<SyncModels.IconData> icons)
	{
		boolean changed = false;
		Set<String> seen = new HashSet<>();
		for (SyncModels.IconData icon : icons)
		{
			String key = icon.getKey();
			if (key == null || !ICON_KEY.matcher(key).matches() || !seen.add(key))
			{
				continue;
			}
			if (icon.getHash() != null && icon.getHash().equals(serverHashes.get(key)))
			{
				continue;
			}
			boolean isNew = !iconIds.containsKey(key);
			if (isNew && customKeys.size() >= MAX_CUSTOM_ICONS)
			{
				continue;
			}
			BufferedImage img = IconDecoder.decode(icon.getPng());
			if (img == null)
			{
				log.debug("CoR sync: skipped unreadable icon {}", key);
				continue;
			}
			img = fit(img);
			if (isNew)
			{
				iconIds.put(key, chatIconManager.registerChatIcon(img));
			}
			else
			{
				chatIconManager.updateChatIcon(iconIds.get(key), img);
			}
			if (!bundled.containsKey(key))
			{
				customKeys.add(key);
			}
			serverHashes.put(key, icon.getHash() == null ? "" : icon.getHash());
			changed = true;
		}

		// icons removed on the server: bundled ones get their image back, custom ones stop being usable
		for (String key : new HashSet<>(serverHashes.keySet()))
		{
			if (!seen.contains(key))
			{
				restore(key);
				changed = true;
			}
		}
		return changed;
	}

	/** Puts every bundled image back and forgets the server's icons. Call on the client thread. */
	public synchronized boolean clearServerIcons()
	{
		boolean changed = !serverHashes.isEmpty() || !rankOverrides.isEmpty();
		rankOverrides = Collections.emptyMap();
		for (String key : new HashSet<>(serverHashes.keySet()))
		{
			restore(key);
		}
		return changed;
	}

	private void restore(String key)
	{
		serverHashes.remove(key);
		BufferedImage original = bundled.get(key);
		Integer id = iconIds.get(key);
		if (original != null && id != null)
		{
			chatIconManager.updateChatIcon(id, original);
		}
		customKeys.remove(key);
	}

	/**
	 * @return the mod icon index for an icon key, or -1 if that icon is unknown or the client has
	 * not finished loading its chat icons yet
	 */
	public int indexFor(String key)
	{
		if (key == null)
		{
			return -1;
		}
		Integer id = iconIds.get(key);
		if (id == null || (!bundled.containsKey(key) && !customKeys.contains(key)))
		{
			return -1;
		}
		return chatIconManager.chatIconIndex(id);
	}

	/** @return the {@code <img=N>} tag for an icon key, or null when {@link #indexFor} is -1 */
	public String tagFor(String key)
	{
		int index = indexFor(key);
		return index < 0 ? null : "<img=" + index + ">";
	}

	/** Built-in member icons plus any new icons from the clan server. */
	public boolean isMemberKey(String key)
	{
		return key != null && (MEMBER_KEYS.contains(key) || customKeys.contains(key));
	}

	/**
	 * Applies the icon picked per clan rank on the clan server. Ranks not listed use the default rule.
	 *
	 * @return true if anything changed
	 */
	public boolean applyRankIcons(List<SyncModels.RankIcon> picks)
	{
		Map<Integer, String> next = new HashMap<>();
		for (SyncModels.RankIcon pick : picks)
		{
			String icon = pick.getIcon();
			if (icon != null && (RankIcons.NO_ICON.equals(icon) || ICON_KEY.matcher(icon).matches()))
			{
				next.put(pick.getRank(), icon);
			}
		}
		if (next.equals(rankOverrides))
		{
			return false;
		}
		rankOverrides = Collections.unmodifiableMap(next);
		return true;
	}

	/** Icon key to draw for a clan rank, or null for none. J-Mods keep their own icon unless the server says otherwise. */
	public String iconForRank(ClanRank rank)
	{
		if (rank == null)
		{
			return null;
		}
		return RankIcons.resolve(rank.getRank(), rankOverrides, k -> bundled.containsKey(k) || customKeys.contains(k));
	}
}

package com.corclan.icons;

import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.util.Base64;
import java.util.Iterator;
import javax.imageio.ImageIO;
import javax.imageio.ImageReader;
import javax.imageio.stream.ImageInputStream;

/**
 * Turns a chat icon downloaded from the clan server into an image, safely. The size is read from the
 * PNG header before any pixels are decoded, so an image that claims to be huge is refused without
 * allocating memory for it.
 */
public final class IconDecoder
{
	public static final int MAX_WIDTH = 32;
	public static final int MAX_HEIGHT = 16;
	/** base64 of the server's 16 KB PNG limit, with a little slack */
	static final int MAX_BASE64_LENGTH = 22_000;

	private IconDecoder()
	{
	}

	/** @return the decoded icon, or null if the data is not a small, valid PNG */
	public static BufferedImage decode(String base64)
	{
		if (base64 == null || base64.isEmpty() || base64.length() > MAX_BASE64_LENGTH)
		{
			return null;
		}
		byte[] bytes;
		try
		{
			bytes = Base64.getDecoder().decode(base64);
		}
		catch (IllegalArgumentException e)
		{
			return null;
		}

		Iterator<ImageReader> readers = ImageIO.getImageReadersByFormatName("png");
		if (!readers.hasNext())
		{
			return null;
		}
		ImageReader reader = readers.next();
		try (ImageInputStream in = ImageIO.createImageInputStream(new ByteArrayInputStream(bytes)))
		{
			if (in == null)
			{
				return null;
			}
			reader.setInput(in, true, true);
			int width = reader.getWidth(0);
			int height = reader.getHeight(0);
			if (width < 1 || height < 1 || width > MAX_WIDTH || height > MAX_HEIGHT)
			{
				return null;
			}
			return reader.read(0);
		}
		catch (IOException | RuntimeException e)
		{
			return null;
		}
		finally
		{
			reader.dispose();
		}
	}
}

package com.corclan.icons;

import com.corclan.sync.SyncModels;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.function.Predicate;

/**
 * Which member icons and title each player gets. Immutable, so chat rendering on the client thread can
 * read it while a new one is built on another thread.
 *
 * Layers, later ones win per player: built-in defaults, then the clan server (admin page), then the
 * config lines (the local "Clan member icons" list and the player's own "Member icons").
 */
public final class MemberCosmetics
{
	public static final int MAX_ICONS = 4;
	public static final int MAX_TITLE_LENGTH = 20;
	public static final MemberCosmetics EMPTY = new MemberCosmetics(Collections.emptyMap(), Collections.emptyMap());

	private final Map<String, List<String>> icons;
	private final Map<String, String> titles;

	private MemberCosmetics(Map<String, List<String>> icons, Map<String, String> titles)
	{
		this.icons = icons;
		this.titles = titles;
	}

	/** @return icon keys for a {@link #key} (empty if none) */
	public List<String> iconsFor(String key)
	{
		return icons.getOrDefault(key, Collections.emptyList());
	}

	/** @return the title for a {@link #key}, or null */
	public String titleFor(String key)
	{
		return titles.get(key);
	}

	/** Lookup key: tags removed, non-breaking spaces and underscores as spaces, trimmed, lower case. */
	public static String key(String name)
	{
		if (name == null)
		{
			return "";
		}
		return name.replaceAll("<[^>]*>", "")
			.replace(' ', ' ')
			.replace('_', ' ')
			.trim()
			.toLowerCase(Locale.ROOT);
	}

	public static MemberCosmetics build(
		Map<String, List<String>> builtinIcons,
		Map<String, String> builtinTitles,
		Collection<SyncModels.ClanPlayer> server,
		String configLines,
		Predicate<String> isIconKey)
	{
		Map<String, List<String>> icons = new HashMap<>(builtinIcons);
		Map<String, String> titles = new HashMap<>(builtinTitles);

		for (SyncModels.ClanPlayer c : server)
		{
			String key = key(c.getRsn());
			List<String> iconList = cleanIcons(c.getIcons(), isIconKey);
			String title = cleanTitle(c.getTitle());
			// the server lists everyone with a gz count too; only its icons and titles are a layer
			if (!key.isEmpty() && (!iconList.isEmpty() || title != null))
			{
				apply(icons, titles, key, iconList, title);
			}
		}

		if (configLines != null)
		{
			for (String line : configLines.split("\\r?\\n"))
			{
				int eq = line.indexOf('=');
				if (eq <= 0)
				{
					continue;
				}
				String key = key(line.substring(0, eq));
				if (key.isEmpty())
				{
					continue;
				}
				String rest = line.substring(eq + 1);
				String iconPart = rest;
				String title = null;
				int bar = rest.indexOf('|');
				if (bar >= 0)
				{
					iconPart = rest.substring(0, bar);
					title = rest.substring(bar + 1);
				}
				List<String> keys = new ArrayList<>();
				for (String icon : iconPart.split(","))
				{
					keys.add(icon.trim().toLowerCase(Locale.ROOT));
				}
				apply(icons, titles, key, cleanIcons(keys, isIconKey), cleanTitle(title));
			}
		}

		return new MemberCosmetics(Collections.unmodifiableMap(icons), Collections.unmodifiableMap(titles));
	}

	/** One layer replaces both icons and title for that player. */
	private static void apply(Map<String, List<String>> icons, Map<String, String> titles, String key, List<String> iconList, String title)
	{
		icons.remove(key);
		titles.remove(key);
		if (!iconList.isEmpty())
		{
			icons.put(key, iconList);
		}
		if (title != null)
		{
			titles.put(key, title);
		}
	}

	static List<String> cleanIcons(List<String> raw, Predicate<String> isIconKey)
	{
		List<String> out = new ArrayList<>();
		for (String icon : raw)
		{
			if (icon != null && isIconKey.test(icon) && !out.contains(icon) && out.size() < MAX_ICONS)
			{
				out.add(icon);
			}
		}
		return Collections.unmodifiableList(out);
	}

	/** Titles are drawn inside chat markup, so tags and angle brackets are never allowed through. */
	static String cleanTitle(String raw)
	{
		if (raw == null)
		{
			return null;
		}
		String t = raw.replaceAll("<[^>]*>", "").replace("<", "").replace(">", "").trim();
		return t.isEmpty() || t.length() > MAX_TITLE_LENGTH ? null : t;
	}
}

package com.corclan.icons;

import java.util.Map;
import java.util.function.Predicate;

/**
 * Which chat icon a clan rank gets. Clan ranks are ints: guests are -1, member ranks count up from 0,
 * administrators are 100+, deputy owner 125, owner 126, J-Mods 127.
 *
 * The clan server can pick an icon per rank on its admin page; ranks it hasn't picked use the default rule.
 */
public final class RankIcons
{
	/** Server value meaning "show no CoR icon for this rank". */
	public static final String NO_ICON = "none";
	static final int ADMIN_RANK = 100;
	static final int JMOD_RANK = 127;

	private RankIcons()
	{
	}

	/** The original rule: administrators and up get the red rhino, everyone else the blue one, J-Mods nothing. */
	public static String defaultIcon(int rank)
	{
		if (rank == JMOD_RANK)
		{
			return null;
		}
		return rank >= ADMIN_RANK ? ClanIconService.KEY_STAFF : ClanIconService.KEY_MEMBER;
	}

	/**
	 * @param overrides rank -> icon key picked on the clan server ({@link #NO_ICON} for none)
	 * @param isKnownIcon whether this client has an icon with that key
	 * @return the icon key to draw, or null for no icon
	 */
	public static String resolve(int rank, Map<Integer, String> overrides, Predicate<String> isKnownIcon)
	{
		String picked = overrides.get(rank);
		if (picked == null)
		{
			return defaultIcon(rank);
		}
		if (NO_ICON.equals(picked))
		{
			return null;
		}
		// an icon this client doesn't have (e.g. not downloaded yet) falls back to the default rule
		return isKnownIcon.test(picked) ? picked : defaultIcon(rank);
	}
}

