/**
 * Talks to the CoR clan server. Only used when the player turns on "Sync with clan server": every request goes
 * through {@link #enqueue}, which checks that setting first and sends nothing while it is off.
 * Every call is asynchronous on RuneLite's shared OkHttp client; callbacks run on OkHttp's threads.
 */
@Slf4j
@Singleton
public class ClanApi
{
	static final HttpUrl BASE_URL = HttpUrl.get("https://cor-clan-api-production.up.railway.app/");
	private static final MediaType JSON = MediaType.get("application/json; charset=utf-8");
	/** error bodies are a few bytes of JSON; never read more than this of one */
	private static final long MAX_ERROR_BYTES = 1024L;

	/** What became of something we sent. */
	public enum Outcome
	{
		/** stored */
		OK,
		/** network error, rate limit or server error: worth sending again later */
		RETRY,
		/** the server will never take this request as it is; sending it again would not help */
		REFUSED,
		/** another account owns this character name until CoR staff unlink it */
		NAME_TAKEN,
		/** this character is not in the CoR clan */
		WRONG_CLAN,
		/** a ::shame on a clanmate who hasn't turned on "Let leaders shame me" */
		NOT_SHAMEABLE;

		/** True when the server refuses everything from this player, so nothing more should be sent. */
		public boolean blocksReporter()
		{
			return this == NAME_TAKEN || this == WRONG_CLAN;
		}
	}

	private final OkHttpClient http;
	private final Gson gson;
	private final CorClanConfig config;

	@Inject
	ClanApi(OkHttpClient http, Gson gson, CorClanConfig config)
	{
		this.http = http;
		this.gson = gson;
		this.config = config;
	}

	/**
	 * The only place a request leaves the plugin. With "Sync with clan server" off nothing is sent; {@code whenOff}
	 * runs instead, so whoever waits for an answer is told the request failed.
	 */
	private void enqueue(Request request, Callback callback, Runnable whenOff)
	{
		if (!config.syncEnabled())
		{
			whenOff.run();
			return;
		}
		http.newCall(request).enqueue(callback);
	}

	/**
	 * @param status HTTP status of the answer to a POST
	 * @param error  the {@code error} code in its body, or null if there was none
	 */
	static Outcome classify(int status, String error)
	{
		if (status >= 200 && status < 300)
		{
			return Outcome.OK;
		}
		if ("name_taken".equals(error) || (error == null && status == 409))
		{
			return Outcome.NAME_TAKEN;
		}
		if ("wrong_clan".equals(error) || (error == null && status == 403))
		{
			return Outcome.WRONG_CLAN;
		}
		if ("not_shameable".equals(error))
		{
			return Outcome.NOT_SHAMEABLE;
		}
		// rate limited, timed out or a server fault
		if (status == 429 || status == 408 || status >= 500)
		{
			return Outcome.RETRY;
		}
		return Outcome.REFUSED;
	}

	/** Sends the reporter's own gz's and the clan broadcasts about them. */
	public void sendReport(SyncModels.ReportPayload payload, Consumer<Outcome> done)
	{
		post("v1/reports", payload, done);
	}

	/** Sends the reporter's own clan rank and glow picks. */
	public void sendProfile(SyncModels.ProfilePayload payload, Consumer<Outcome> done)
	{
		post("v1/profile", payload, done);
	}

	/** Sends the clan's rank names (rank number + title only) so admins can pick an icon per rank. */
	public void sendRanks(SyncModels.RanksPayload payload, Consumer<Outcome> done)
	{
		post("v1/ranks", payload, done);
	}

	/** Shames a clanmate with the Kephri dung, or takes it off. Only the shamers' own accounts are taken. */
	public void sendShame(SyncModels.ShamePayload payload, Consumer<Outcome> done)
	{
		post("v1/shame", payload, done);
	}

	/**
	 * Our own daily gm: the server pays the gm bonus for the first one each UTC day.
	 * @param done the outcome, and on OK the server's answer (null if it could not be read)
	 */
	public void sendGm(SyncModels.GmPayload payload, BiConsumer<Outcome, SyncModels.GmResult> done)
	{
		Request request = new Request.Builder()
			.url(BASE_URL.resolve("v1/gm"))
			.post(RequestBody.create(JSON, gson.toJson(payload)))
			.build();
		enqueue(request, new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("CoR sync: POST v1/gm failed", e);
				done.accept(Outcome.RETRY, null);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				Outcome outcome;
				SyncModels.GmResult result = null;
				try (Response r = response)
				{
					outcome = classify(r.code(), r.isSuccessful() ? null : errorCode(r));
					ResponseBody body = r.body();
					if (outcome == Outcome.OK && body != null)
					{
						result = gson.fromJson(body.charStream(), SyncModels.GmResult.class);
					}
				}
				catch (JsonParseException e)
				{
					log.debug("CoR sync: unreadable answer from v1/gm", e);
					outcome = Outcome.OK;
				}
				done.accept(outcome, result);
			}
		}, () -> done.accept(Outcome.RETRY, null));
	}

	/** Who wears the Kephri dung right now. */
	public void fetchShames(Consumer<SyncModels.ShamesResponse> onSuccess)
	{
		get("v1/shames", SyncModels.ShamesResponse.class, null, onSuccess);
	}

	/** Puts up or updates our own raid finder listing. */
	public void sendRaid(SyncModels.RaidPayload payload, Consumer<Outcome> done)
	{
		post("v1/raids", payload, done);
	}

	/** Takes our own raid finder listing down. */
	public void stopRaid(SyncModels.RaidStopPayload payload, Consumer<Outcome> done)
	{
		post("v1/raids/stop", payload, done);
	}

	/**
	 * Asks the clan server to post our open raid group in the clan Discord's looking-for-group channel.
	 * @param done on an OkHttp thread: null when Discord took it, else the line to tell the player
	 */
	public void pingRaid(SyncModels.RaidStopPayload payload, Consumer<String> done)
	{
		Request request = new Request.Builder()
			.url(BASE_URL.resolve("v1/raids/ping"))
			.post(RequestBody.create(JSON, gson.toJson(payload)))
			.build();
		enqueue(request, new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("CoR sync: POST v1/raids/ping failed", e);
				done.accept("couldn't reach the clan server, try again");
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response r = response)
				{
					if (r.isSuccessful())
					{
						done.accept(null);
						return;
					}
					SyncModels.ErrorBody body = null;
					try
					{
						body = gson.fromJson(r.peekBody(MAX_ERROR_BYTES).string(), SyncModels.ErrorBody.class);
					}
					catch (IOException | JsonParseException e)
					{
						log.debug("CoR sync: unreadable answer from v1/raids/ping", e);
					}
					done.accept(pingProblem(body == null ? null : body.getError(), body == null ? 0 : body.getRetryAfterSeconds()));
				}
			}
		}, () -> done.accept("turn on Sync with clan server first"));
	}

	/** What to tell the player when a Discord ping is refused. */
	static String pingProblem(String error, int retryAfterSeconds)
	{
		if ("ping_cooldown".equals(error))
		{
			int minutes = Math.max(1, (retryAfterSeconds + 59) / 60);
			return "you can ping Discord again in " + minutes + (minutes == 1 ? " minute" : " minutes");
		}
		if ("no_group".equals(error))
		{
			return "put your group up first";
		}
		if ("discord_off".equals(error))
		{
			return "Discord pings aren't set up on the clan server yet";
		}
		if ("discord_failed".equals(error))
		{
			return "Discord didn't take the ping, try again in a moment";
		}
		return "the clan server refused the ping";
	}

	/** Every open raid finder listing; skips RuneLite's HTTP cache, since the board changes by the minute. */
	public void fetchRaids(Consumer<SyncModels.RaidsResponse> onSuccess)
	{
		get("v1/raids", SyncModels.RaidsResponse.class, CacheControl.FORCE_NETWORK, onSuccess);
	}

	/** A clan leader sets the announcement banner (an empty text clears it). */
	public void sendAnnouncement(SyncModels.AnnouncementPayload payload, Consumer<Outcome> done)
	{
		post("v1/announcement", payload, done);
	}

	/** Everyone's gz counts, icons, titles and glow picks, the past weekly podiums and the announcement banner. */
	public void fetchClan(Consumer<SyncModels.ClanResponse> onSuccess)
	{
		get("v1/clan", SyncModels.ClanResponse.class, null, onSuccess);
	}

	/** {@link #fetchClan}, skipping RuneLite's HTTP cache: right after our own change, so it shows at once. */
	public void fetchClanNow(Consumer<SyncModels.ClanResponse> onSuccess)
	{
		get("v1/clan", SyncModels.ClanResponse.class, CacheControl.FORCE_NETWORK, onSuccess);
	}

	/** Chat icon images set on the admin page (small PNGs, base64) and the icon picked per clan rank. */
	public void fetchIcons(Consumer<SyncModels.IconsResponse> onSuccess)
	{
		get("v1/icons", SyncModels.IconsResponse.class, null, onSuccess);
	}

	private void post(String path, Object payload, Consumer<Outcome> done)
	{
		Request request = new Request.Builder()
			.url(BASE_URL.resolve(path))
			.post(RequestBody.create(JSON, gson.toJson(payload)))
			.build();

		enqueue(request, new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("CoR sync: POST {} failed", path, e);
				done.accept(Outcome.RETRY);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				Outcome outcome;
				try (Response r = response)
				{
					outcome = classify(r.code(), r.isSuccessful() ? null : errorCode(r));
					log.debug("CoR sync: POST {} returned {} ({})", path, r.code(), outcome);
				}
				done.accept(outcome);
			}
		}, () -> done.accept(Outcome.RETRY));
	}

	/** The {@code error} code of a refused request, or null if the body has none. */
	private String errorCode(Response r)
	{
		try
		{
			SyncModels.ErrorBody body = gson.fromJson(r.peekBody(MAX_ERROR_BYTES).string(), SyncModels.ErrorBody.class);
			return body == null ? null : body.getError();
		}
		catch (IOException | JsonParseException e)
		{
			return null;
		}
	}

	/** @param cache null for the usual caching */
	private <T> void get(String path, Class<T> type, CacheControl cache, Consumer<T> onSuccess)
	{
		Request.Builder builder = new Request.Builder().url(BASE_URL.resolve(path)).get();
		if (cache != null)
		{
			builder.cacheControl(cache);
		}
		Request request = builder.build();
		enqueue(request, new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("CoR sync: GET {} failed", path, e);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response r = response)
				{
					ResponseBody body = r.body();
					if (!r.isSuccessful() || body == null)
					{
						log.debug("CoR sync: GET {} returned {}", path, r.code());
						return;
					}
					T result = gson.fromJson(body.charStream(), type);
					if (result != null)
					{
						onSuccess.accept(result);
					}
				}
				catch (JsonParseException e)
				{
					log.debug("CoR sync: unreadable response from {}", path, e);
				}
			}
		}, () -> { });
	}
}

package com.corclan.sync;

import com.corclan.gz.GzTracker;
import com.corclan.gz.WeekResult;
import com.corclan.icons.MemberCosmetics;
import java.time.Instant;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * One {@code GET /v1/clan} answer, turned into what the plugin shows: gz counts per player, the past weeks'
 * winners, everyone's icons and titles, and their glow picks keyed by name. Immutable, so it can be built on
 * an OkHttp thread and read on the client thread.
 */
public final class ClanSnapshot
{
	/** Same limits the server puts on a player's glow picks. */
	static final int MAX_GLOWS = 32;
	static final int MAX_GLOW_ID_LENGTH = 32;

	/** start of the week the weekly counts belong to, epoch millis; 0 when the server's value is unreadable */
	private final long weekStart;
	private final Map<String, Integer> given;
	private final Map<String, Integer> received;
	private final Map<String, Integer> weekly;
	private final List<WeekResult> weekResults;
	private final List<SyncModels.ClanPlayer> players;
	private final Map<String, List<String>> glows;
	/** the banner clan leaders set, or null */
	private final Announcement announcement;
	/** the clan's latest promotions, newest first */
	private final List<RecentPromotion> recentPromotions;

	private ClanSnapshot(long weekStart, Map<String, Integer> given, Map<String, Integer> received,
		Map<String, Integer> weekly, List<WeekResult> weekResults, List<SyncModels.ClanPlayer> players,
		Map<String, List<String>> glows, Announcement announcement, List<RecentPromotion> recentPromotions)
	{
		this.recentPromotions = recentPromotions;
		this.announcement = announcement;
		this.weekStart = weekStart;
		this.given = Collections.unmodifiableMap(given);
		this.received = Collections.unmodifiableMap(received);
		this.weekly = Collections.unmodifiableMap(weekly);
		this.weekResults = Collections.unmodifiableList(weekResults);
		this.players = Collections.unmodifiableList(players);
		this.glows = Collections.unmodifiableMap(glows);
	}

	public static ClanSnapshot of(SyncModels.ClanResponse response)
	{
		Map<String, Integer> given = new HashMap<>();
		Map<String, Integer> received = new HashMap<>();
		Map<String, Integer> weekly = new HashMap<>();
		List<SyncModels.ClanPlayer> players = new ArrayList<>();
		Map<String, List<String>> glows = new HashMap<>();
		for (SyncModels.ClanPlayer p : response.getPlayers())
		{
			if (p == null || MemberCosmetics.key(p.getRsn()).isEmpty())
			{
				continue;
			}
			String name = p.getRsn().trim();
			count(given, name, p.getGiven());
			count(received, name, p.getReceived());
			count(weekly, name, p.getWeeklyGiven());
			players.add(p);
			List<String> picks = picksOf(p);
			if (picks != null)
			{
				glows.put(MemberCosmetics.key(name), picks);
			}
		}

		List<WeekResult> weekResults = new ArrayList<>();
		for (SyncModels.Week week : response.getWeeks())
		{
			long start = week == null ? 0L : parseWeekStart(week.getWeekStart());
			List<String> winners = week == null ? Collections.emptyList() : winners(week.getTop());
			if (start != 0L && !winners.isEmpty())
			{
				weekResults.add(new WeekResult(start, winners));
			}
		}
		return new ClanSnapshot(parseWeekStart(response.getWeekStart()), given, received, weekly, weekResults, players, glows,
			Announcement.of(response.getAnnouncement()), RecentPromotion.list(response.getPromotions()));
	}

	private static void count(Map<String, Integer> counts, String name, int value)
	{
		if (value > 0)
		{
			counts.merge(name, value, Math::max);
		}
	}

	/**
	 * The glow ids a player shared, or null if they never shared any (then viewers show their rank's defaults).
	 * A player's rank and glow picks are sent together, so an empty list only means "picked nothing" when
	 * their rank has been reported too.
	 */
	private static List<String> picksOf(SyncModels.ClanPlayer p)
	{
		List<String> raw = p.getGlows();
		if (raw == null || (raw.isEmpty() && p.getRank() == null))
		{
			return null;
		}
		List<String> picks = new ArrayList<>();
		for (String id : raw)
		{
			if (id != null && !id.isEmpty() && id.length() <= MAX_GLOW_ID_LENGTH && picks.size() < MAX_GLOWS)
			{
				picks.add(id);
			}
		}
		return Collections.unmodifiableList(picks);
	}

	/** Everyone tied for the most gz's in a week's top three, sorted by name. */
	private static List<String> winners(List<SyncModels.Entry> top)
	{
		int max = 0;
		for (SyncModels.Entry e : top)
		{
			if (e != null && e.getRsn() != null)
			{
				max = Math.max(max, e.getCount());
			}
		}
		List<String> out = new ArrayList<>();
		for (SyncModels.Entry e : top)
		{
			if (max > 0 && e != null && e.getRsn() != null && e.getCount() == max && !out.contains(e.getRsn()))
			{
				out.add(e.getRsn());
			}
		}
		Collections.sort(out);
		return out;
	}

	/** @return the Sunday 00:00 UTC on or before the server's ISO-8601 instant, or 0 if it is unreadable */
	static long parseWeekStart(String iso)
	{
		if (iso == null)
		{
			return 0L;
		}
		try
		{
			return GzTracker.weekStartOf(Instant.parse(iso).toEpochMilli(), GzTracker.WEEK_ZONE);
		}
		catch (DateTimeParseException | ArithmeticException e)
		{
			return 0L;
		}
	}

	/** gz's given per player name, all time */
	public Map<String, Integer> getGiven()
	{
		return given;
	}

	public Map<String, Integer> getReceived()
	{
		return received;
	}

	/**
	 * gz's given per player name in the week starting at {@code currentWeekStart}. Empty when the server's
	 * counts are still last week's (a new week just began and the next refresh has not arrived).
	 */
	public Map<String, Integer> weeklyGiven(long currentWeekStart)
	{
		return weekStart != 0L && weekStart < currentWeekStart ? Collections.emptyMap() : weekly;
	}

	/** The #1 giver(s) of each closed week the server sent (the last 12 with any gz's). */
	public List<WeekResult> getWeekResults()
	{
		return weekResults;
	}

	/** Every listed player, for their icons and titles. */
	public List<SyncModels.ClanPlayer> getPlayers()
	{
		return players;
	}

	/** The clan's latest promotions, newest first; empty on a server without them. */
	public List<RecentPromotion> getRecentPromotions()
	{
		return recentPromotions;
	}

	/** The announcement banner, or null when the leaders have not set one. */
	public Announcement getAnnouncement()
	{
		return announcement;
	}

	/** {@link MemberCosmetics#key} -> the glow ids that player shared. Players who shared none are absent. */
	public Map<String, List<String>> getGlows()
	{
		return glows;
	}
}

package com.corclan.sync;

import com.corclan.gz.GzStats;
import com.corclan.gz.WeekResult;
import com.corclan.icons.MemberCosmetics;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * The gz numbers shown everywhere (podiums, givers list, GZ King, weekly trophies, streaks, !rank): the clan
 * server's while clan sync is on and its answer is recent, otherwise the ones this client counted. The local
 * tracker keeps counting either way, so turning sync off loses nothing. Immutable.
 */
public final class GzView
{
	/** A server answer older than this (five missed refreshes) is no longer shown; local counts take over. */
	public static final long STALE_MILLIS = 600_000L;

	/** true when these are the clan server's numbers */
	public final boolean clanWide;
	public final Map<String, Integer> given;
	public final Map<String, Integer> received;
	/** gz's given this week */
	public final Map<String, Integer> weekly;
	/** #1 giver(s) of past weeks, for streaks */
	public final List<WeekResult> weekResults;
	/** {@link MemberCosmetics#key} -> count, for lookups by a name as chat spells it */
	private final Map<String, Integer> givenByKey = new HashMap<>();
	private final Map<String, Integer> receivedByKey = new HashMap<>();

	private GzView(boolean clanWide, Map<String, Integer> given, Map<String, Integer> received,
		Map<String, Integer> weekly, List<WeekResult> weekResults)
	{
		this.clanWide = clanWide;
		this.given = Collections.unmodifiableMap(given);
		this.received = Collections.unmodifiableMap(received);
		this.weekly = Collections.unmodifiableMap(weekly);
		this.weekResults = Collections.unmodifiableList(weekResults);
		given.forEach((name, n) -> givenByKey.merge(MemberCosmetics.key(name), n, Math::max));
		received.forEach((name, n) -> receivedByKey.merge(MemberCosmetics.key(name), n, Math::max));
	}

	/**
	 * @param server           the last answer from the clan server, or null when clan sync is off or nothing
	 *                         has loaded yet
	 * @param serverLoadedAt   when {@code server} arrived, epoch millis
	 * @param currentWeekStart start of the running week (Sunday 00:00 UTC), epoch millis
	 */
	public static GzView choose(ClanSnapshot server, long serverLoadedAt, long now,
		GzStats localAllTime, GzStats localWeekly, List<WeekResult> localWeekResults, long currentWeekStart)
	{
		if (server != null && now - serverLoadedAt < STALE_MILLIS)
		{
			return new GzView(true, server.getGiven(), server.getReceived(), server.weeklyGiven(currentWeekStart),
				server.getWeekResults());
		}
		return new GzView(false, new HashMap<>(localAllTime.getGiven()), new HashMap<>(localAllTime.getReceived()),
			new HashMap<>(localWeekly.getGiven()), new ArrayList<>(localWeekResults));
	}

	/** All-time gz's given by {@code name}, however its case and spaces are written. */
	public int givenOf(String name)
	{
		return givenByKey.getOrDefault(MemberCosmetics.key(name), 0);
	}

	public int receivedOf(String name)
	{
		return receivedByKey.getOrDefault(MemberCosmetics.key(name), 0);
	}
}

package com.corclan.sync;

import java.time.Instant;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Objects;

/**
 * One of the clan's latest promotions from the clan feed: a plugin user's own client reported a higher rank. Shown to
 * everyone in the Promotions card. Names and titles are cleaned, since they come from the server.
 */
public final class RecentPromotion
{
	/** the feed lists this many; anything more is ignored */
	public static final int MAX = 3;
	private static final int MAX_TEXT = 20;

	public final String name;
	public final String from;
	public final String to;
	/** epoch millis, 0 when unreadable */
	public final long at;

	RecentPromotion(String name, String from, String to, long at)
	{
		this.name = name;
		this.from = from;
		this.to = to;
		this.at = at;
	}

	/** @return the readable entries, newest first as the server sent them, at most {@link #MAX} */
	public static List<RecentPromotion> list(List<SyncModels.PromotionData> data)
	{
		List<RecentPromotion> list = new ArrayList<>();
		for (SyncModels.PromotionData p : data)
		{
			if (p == null || list.size() >= MAX)
			{
				continue;
			}
			String name = clean(p.getRsn());
			String from = clean(p.getFrom());
			String to = clean(p.getTo());
			if (!name.isEmpty() && !from.isEmpty() && !to.isEmpty())
			{
				list.add(new RecentPromotion(name, from, to, parse(p.getAt())));
			}
		}
		return Collections.unmodifiableList(list);
	}

	static String clean(String raw)
	{
		if (raw == null)
		{
			return "";
		}
		String text = raw.replaceAll("<[^>]*>", "").replace("<", "").replace(">", "")
			.replaceAll("[\\s\\u00A0]+", " ").trim();
		return text.length() > MAX_TEXT ? text.substring(0, MAX_TEXT).trim() : text;
	}

	private static long parse(String iso)
	{
		if (iso == null)
		{
			return 0L;
		}
		try
		{
			return Instant.parse(iso).toEpochMilli();
		}
		catch (DateTimeParseException | ArithmeticException e)
		{
			return 0L;
		}
	}

	@Override
	public boolean equals(Object o)
	{
		if (!(o instanceof RecentPromotion))
		{
			return false;
		}
		RecentPromotion p = (RecentPromotion) o;
		return at == p.at && name.equals(p.name) && from.equals(p.from) && to.equals(p.to);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(name, from, to, at);
	}
}

package com.corclan.sync;

import java.util.Collections;
import java.util.List;
import java.util.Objects;

/**
 * JSON shapes exchanged with the CoR clan server (see the cor-clan-api README, "API for the plugins").
 * Serialized with RuneLite's Gson (nulls are omitted). Everything a client sends is about its own player.
 */
public final class SyncModels
{
	private SyncModels()
	{
	}

	/** Who is reporting: RuneLite's account hash, the character's name and the clan it is in. */
	public static final class Reporter
	{
		private final String accountHash;
		private final String rsn;
		private final String clan;

		public Reporter(String accountHash, String rsn, String clan)
		{
