				return false;
			}
			Reporter other = (Reporter) o;
			return Objects.equals(accountHash, other.accountHash) && Objects.equals(rsn, other.rsn)
				&& Objects.equals(clan, other.clan);
		}

		@Override
		public int hashCode()
		{
			return Objects.hash(accountHash, rsn, clan);
		}
	}

