package com.corclan.sync;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;

/**
 * The player's own gz's and broadcasts waiting to be sent to the clan server. Bounded so a long outage
 * cannot grow memory; the oldest events are dropped first (the server refuses events older than 10 minutes
 * anyway). Thread-safe: filled on the client thread, drained on the scheduler, re-filled from OkHttp callbacks.
 */
public final class SyncQueue
{
	public static final int MAX_PENDING = 500;
	public static final int MAX_BATCH = 100;

	private final Deque<SyncModels.Event> pending = new ArrayDeque<>();

	public synchronized void add(SyncModels.Event event)
	{
		pending.addLast(event);
		trim();
	}

	/** Removes and returns up to {@code max} of the oldest events. */
	public synchronized List<SyncModels.Event> drain(int max)
	{
		List<SyncModels.Event> batch = new ArrayList<>(Math.min(max, pending.size()));
		while (batch.size() < max && !pending.isEmpty())
		{
			batch.add(pending.removeFirst());
		}
		return batch;
	}

	/** Puts a batch that failed to send back at the front, in its original order. */
	public synchronized void requeue(List<SyncModels.Event> batch)
	{
		for (int i = batch.size() - 1; i >= 0; i--)
		{
			pending.addFirst(batch.get(i));
		}
		trim();
	}

	/** Forgets events from before {@code cutoff} (epoch millis): the server would refuse them as too old. */
	public synchronized void dropOlderThan(long cutoff)
	{
		pending.removeIf(event -> event.getAt() < cutoff);
	}

	public synchronized void clear()
	{
		pending.clear();
	}

	public synchronized int size()
	{
		return pending.size();
	}

	private void trim()
	{
		while (pending.size() > MAX_PENDING)
		{
			pending.removeFirst();
		}
	}
}

package com.corclan.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.ButtonModel;
import javax.swing.JButton;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.FontManager;

/**
 * A button in the rhino logo's colours, for the side panel's art: an iron-grey face with a steel rim that turns
 * horn red, with a faint red glow, under the mouse.
 */
class ArtButton extends JButton
{
	private static final int ARC = 8;
	/** the label colour while enabled */
	private Color textColor = Color.WHITE;

	ArtButton(String text)
	{
		super(text);
		setFont(FontManager.getRunescapeBoldFont());
		setForeground(Color.WHITE);
		setContentAreaFilled(false);
		setBorderPainted(false);
		setFocusPainted(false);
		setFocusable(false);
		setOpaque(false);
		setRolloverEnabled(true);
		setBorder(new EmptyBorder(5, 10, 5, 10));
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
	}

	/** The label colour while enabled (white by default). */
	void setTextColor(Color color)
	{
		textColor = color;
		repaint();
	}

	@Override
	public Dimension getPreferredSize()
	{
		Dimension size = super.getPreferredSize();
		return new Dimension(size.width, Math.max(size.height, 26));
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		try
		{
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			ButtonModel model = getModel();
			boolean hot = isEnabled() && model.isRollover();
			boolean down = isEnabled() && model.isArmed() && model.isPressed();
			int w = getWidth() - 1;
			int h = getHeight() - 1;

			if (hot)
			{
				for (int i = 3; i >= 1; i--)
				{
					g2.setColor(PanelArt.alpha(PanelArt.HORN, 40 / i));
					g2.setStroke(new BasicStroke(i * 2f));
					g2.drawRoundRect(1, 1, w - 2, h - 2, ARC, ARC);
				}
			}
			Color top = down ? PanelArt.IRON_BOTTOM : hot ? new Color(62, 62, 62) : PanelArt.IRON_TOP;
			Color bottom = down ? PanelArt.IRON_TOP : PanelArt.IRON_BOTTOM;
			g2.setPaint(new GradientPaint(0, 0, top, 0, h, bottom));
			g2.fillRoundRect(1, 1, w - 2, h - 2, ARC, ARC);
			// a light line along the top edge, like the logo's face plates
			g2.setColor(PanelArt.alpha(Color.WHITE, down ? 10 : 28));
			g2.drawLine(ARC / 2 + 1, 2, w - ARC / 2 - 1, 2);
			g2.setStroke(new BasicStroke(1.5f));
			g2.setColor(!isEnabled() ? PanelArt.STEEL_DIM : hot ? PanelArt.HORN : PanelArt.STEEL);
			g2.drawRoundRect(1, 1, w - 2, h - 2, ARC, ARC);
		}
		finally
		{
			g2.dispose();
		}
		setForeground(isEnabled() ? textColor : PanelArt.STEEL_DIM);
		super.paintComponent(g);
	}
}

package com.corclan.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.LayoutManager;
import java.awt.LinearGradientPaint;
import java.awt.Polygon;
import java.awt.RenderingHints;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JPanel;
import javax.swing.Timer;
import javax.swing.border.EmptyBorder;

/**
 * The side panel's art frame (announcement banner, rank card), in the rhino logo's colours: a charcoal plaque with a
 * steel rim and rivets. While live it comes alive: the rim brightens and an outer glow in horn red pulses, a light sweep crosses it
 * now and then and sparkles twinkle in the corners. It only repaints while on screen, and stays still when not live.
 */
final class ArtPlaque extends JPanel
{
	private static final Color RIM = PanelArt.STEEL_DIM;
	private static final Color PLAQUE_TOP = new Color(46, 46, 46);
	private static final Color PLAQUE_BOTTOM = PanelArt.IRON_BOTTOM;
	private static final Color RIVET = new Color(130, 130, 130);

	/** room around the plaque for the glow */
	private static final int MARGIN = 4;
	private static final int ARC = 12;
	private static final int FRAME_MILLIS = 50;
	private static final double PULSE_MILLIS = 2400;
	private static final long SWEEP_MILLIS = 5000;
	/** share of each sweep cycle the light band is moving; the rest is a pause */
	private static final float SWEEP_SHARE = 0.35f;
	private static final double TWINKLE_MILLIS = 1800;
	/** sparkle spots: x and y as a share of the plaque, then the phase offset */
	private static final float[][] TWINKLES = {
		{0.05f, 0.10f, 0.00f},
		{0.95f, 0.12f, 0.35f},
		{0.93f, 0.90f, 0.70f},
		{0.07f, 0.88f, 0.50f},
		{0.62f, 0.05f, 0.20f},
	};

	private final Timer timer = new Timer(FRAME_MILLIS, e ->
	{
		if (isShowing())
		{
			repaint();
		}
	});
	private final long start = System.currentTimeMillis();
	private boolean live;
	private Color accent = PanelArt.HORN;
	private Color sparkle = PanelArt.mix(PanelArt.HORN, Color.WHITE, 0.45f);

	ArtPlaque(LayoutManager layout)
	{
		super(layout);
		setOpaque(false);
		setBorder(new EmptyBorder(MARGIN + 8, MARGIN + 10, MARGIN + 8, MARGIN + 10));
	}

	/** @param live true to animate; false for a still, dimmer plaque */
	void setLive(boolean live)
	{
		this.live = live;
		if (live && isDisplayable())
		{
			timer.start();
		}
		else
		{
			timer.stop();
		}
		repaint();
	}

	/** The colour of the outer glow; the sparkles get a lighter version of it. */
	void setAccent(Color accent)
	{
		this.accent = accent;
		this.sparkle = PanelArt.mix(accent, Color.WHITE, 0.45f);
		repaint();
	}

	@Override
	public void addNotify()
	{
		super.addNotify();
		if (live)
		{
			timer.start();
		}
	}

	@Override
	public void removeNotify()
	{
		timer.stop();
		super.removeNotify();
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		try
		{
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			long t = System.currentTimeMillis() - start;
			float pulse = live ? (float) (0.5 + 0.5 * Math.sin(t * 2 * Math.PI / PULSE_MILLIS)) : 0f;
			int x = MARGIN;
			int y = MARGIN;
			int w = getWidth() - 2 * MARGIN - 1;
			int h = getHeight() - 2 * MARGIN - 1;
			if (w <= 0 || h <= 0)
			{
				return;
			}

			// soft glow outside the rim
			if (live)
			{
				for (int i = MARGIN; i >= 1; i--)
				{
					g2.setColor(PanelArt.alpha(accent, (int) ((30 + 70 * pulse) / i)));
					g2.setStroke(new BasicStroke(i * 2f));
					g2.drawRoundRect(x, y, w, h, ARC, ARC);
				}
			}

			RoundRectangle2D plaque = new RoundRectangle2D.Float(x, y, w, h, ARC, ARC);
			g2.setPaint(new GradientPaint(0, y, PLAQUE_TOP, 0, y + h, PLAQUE_BOTTOM));
			g2.fill(plaque);

			if (live)
			{
				paintSweep(g2, plaque, t);
			}

			// steel rim, a darker inner line and a rivet in each corner
			g2.setStroke(new BasicStroke(2f));
			g2.setColor(live ? PanelArt.mix(RIM, PanelArt.STEEL_LIGHT, 0.3f + 0.7f * pulse) : RIM);
			g2.draw(plaque);
			g2.setStroke(new BasicStroke(1f));
			g2.setColor(PanelArt.alpha(Color.BLACK, 110));
			g2.drawRoundRect(x + 3, y + 3, w - 6, h - 6, ARC - 4, ARC - 4);
			int r = 3;
			g2.setColor(RIVET);
			g2.fillOval(x + 5, y + 5, r, r);
			g2.fillOval(x + w - 5 - r, y + 5, r, r);
			g2.fillOval(x + 5, y + h - 5 - r, r, r);
			g2.fillOval(x + w - 5 - r, y + h - 5 - r, r, r);

			if (live)
			{
				paintTwinkles(g2, x, y, w, h, t);
			}
		}
		finally
		{
			g2.dispose();
		}
	}

	/** A slanted band of light that crosses the plaque, then pauses. */
	private void paintSweep(Graphics2D g2, RoundRectangle2D plaque, long t)
	{
		float phase = (t % SWEEP_MILLIS) / (float) SWEEP_MILLIS / SWEEP_SHARE;
		if (phase >= 1f)
		{
			return;
		}
		float band = 46f;
		float width = (float) plaque.getWidth();
		float left = (float) plaque.getX() - band * 2 + phase * (width + band * 3);
		float top = (float) plaque.getY();
		LinearGradientPaint light = new LinearGradientPaint(left, top, left + band, top + band * 0.6f,
			new float[]{0f, 0.5f, 1f},
			new Color[]{PanelArt.alpha(Color.WHITE, 0), PanelArt.alpha(new Color(235, 235, 235), 50), PanelArt.alpha(Color.WHITE, 0)});
		g2.setPaint(light);
		g2.fill(plaque);
	}

	/** Small four-point stars that fade in and out, each on its own beat. */
	private void paintTwinkles(Graphics2D g2, int x, int y, int w, int h, long t)
	{
		for (float[] spot : TWINKLES)
		{
			double wave = Math.sin((t / TWINKLE_MILLIS + spot[2]) * 2 * Math.PI);
			if (wave <= 0)
			{
				continue;
			}
			float bright = (float) (wave * wave);
			int cx = x + Math.round(spot[0] * w);
			int cy = y + Math.round(spot[1] * h);
			int arm = 2 + Math.round(4 * bright);
			g2.setColor(PanelArt.alpha(sparkle, Math.round(255 * bright)));
			g2.fill(star(cx, cy, arm));
			g2.setColor(PanelArt.alpha(Color.WHITE, Math.round(220 * bright)));
			g2.fillRect(cx, cy, 1, 1);
		}
	}

	static Polygon star(int cx, int cy, int arm)
	{
		Polygon p = new Polygon();
		p.addPoint(cx, cy - arm);
		p.addPoint(cx + 1, cy - 1);
		p.addPoint(cx + arm, cy);
		p.addPoint(cx + 1, cy + 1);
		p.addPoint(cx, cy + arm);
		p.addPoint(cx - 1, cy + 1);
		p.addPoint(cx - arm, cy);
		p.addPoint(cx - 1, cy - 1);
		return p;
	}
}

package com.corclan.ui;

import com.corclan.CorClanConfig;
import com.corclan.CorClanPlugin;
import com.corclan.gz.BroadcastRecord;
import com.corclan.gz.GzStats;
import com.corclan.gz.GzTracker;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * Small on-screen box: your own gz counts, the broadcast currently accepting gz's with a countdown,
 * and a flash for a few seconds whenever a gz is counted.
 */
public class CorClanOverlay extends OverlayPanel
{
	/** How long the "+1 gz" flash stays on screen. */
	static final long FLASH_MILLIS = 4000L;

	private static final Color GREEN = new Color(0x4CAF50);
	private static final Color GOLD = new Color(0xFFC107);

	private final CorClanPlugin plugin;
	private final CorClanConfig config;

	@Inject
	CorClanOverlay(CorClanPlugin plugin, CorClanConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		panelComponent.setPreferredSize(new Dimension(150, 0));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showOverlay())
		{
			return null;
		}
		GzTracker tracker = plugin.getTracker();
		long now = System.currentTimeMillis();
		String me = plugin.localPlayerName();

		panelComponent.getChildren().add(TitleComponent.builder()
			.text("CoR gz")
			.color(ColorScheme.BRAND_ORANGE)
			.build());

		if (me != null)
		{
			GzStats session = tracker.getSession();
			GzStats allTime = tracker.getAllTime();
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Gave")
				.right(session.getGiven().getOrDefault(me, 0) + " / " + allTime.getGiven().getOrDefault(me, 0))
				.build());
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Got")
				.right(session.getReceived().getOrDefault(me, 0) + " / " + allTime.getReceived().getOrDefault(me, 0))
				.build());
		}

		long windowMillis = config.gzWindowSeconds() * 1000L;
		BroadcastRecord window = tracker.currentWindow(now, windowMillis);
		if (window != null)
		{
			long left = Math.max(0, (window.getTimestamp() + windowMillis - now) / 1000L);
			panelComponent.getChildren().add(LineComponent.builder()
				.left("gz " + window.getSubject())
				.leftColor(GOLD)
				.right(window.getGzCount() + " (" + left + "s)")
				.rightColor(GOLD)
				.build());
		}

		if (tracker.getLastGzGiver() != null && now - tracker.getLastGzTime() < FLASH_MILLIS)
		{
			String subject = tracker.getLastGzSubject();
			panelComponent.getChildren().add(LineComponent.builder()
				.left("+1 " + tracker.getLastGzGiver())
				.leftColor(GREEN)
				.right(subject != null ? "> " + subject : "")
				.rightColor(GREEN)
				.build());
		}

		return super.render(graphics);
	}
}

