		this.owner = owner;
		this.dev = dev;
		this.founder = founder;
		this.inCorParty = inCorParty;
		this.announcement = announcement;
		this.announcementHint = announcementHint;
		this.canEditAnnouncement = canEditAnnouncement;
		this.clanRoster = clanRoster;
