import net.runelite.client.ui.FontManager;

/**
 * The raid group finder, under the rank card: clanmates looking for a party for CoX, ToB or ToA, with how many slots
 * are filled, on the same art plaque as the banner. Anyone with clan sync on can put up one group of their own and
 * update or take it down. Click the title to open or close it.
 */
public final class RaidFinderCard extends JPanel
{
	/** What the card asks the plugin to do (on the Swing thread). */
	public interface Actions
	{
		void post(RaidAd ad);

		void stop();

		/** posts our group in the clan Discord's looking-for-group channel */
		void ping();
	}

	private final ArtPlaque plaque = new ArtPlaque(new BorderLayout(0, 6));
	private final JLabel badge = new JLabel();
	private final JLabel marker = new JLabel();
	private final WrapText summary = new WrapText(FontManager.getRunescapeSmallFont(), ColorScheme.LIGHT_GRAY_COLOR);
	private final JPanel body = new JPanel();
	private final JPanel listings = new JPanel();
	private final WrapText hint = new WrapText(FontManager.getRunescapeSmallFont(), ColorScheme.LIGHT_GRAY_COLOR);
	private final JLabel mine = new JLabel();

	private final JComboBox<Raid> raidBox = new JComboBox<>(Raid.values());
	private final SpinnerNumberModel filledModel = new SpinnerNumberModel(1, 1, Raid.COX.defaultSize, 1);
	private final SpinnerNumberModel sizeModel = new SpinnerNumberModel(Raid.COX.defaultSize, 2, Raid.COX.maxSize, 1);
	private final JTextField note = new JTextField();
	private final JButton postButton = new ArtButton("Post group");
	private final JButton stopButton = new ArtButton("Take down");
	private final JButton pingButton = new ArtButton("Ping Discord");

	private List<RaidListing> shown = Collections.emptyList();
	private String shownMe;
	private RaidAd shownAd;
	private long shownMinute = -1;

	RaidFinderCard(Actions actions)
	{
		super(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		add(Box.createVerticalStrut(8), BorderLayout.NORTH);
		add(plaque, BorderLayout.CENTER);

		JPanel header = new JPanel(new BorderLayout(0, 2));
		header.setOpaque(false);
		JPanel titleRow = new JPanel(new BorderLayout(6, 0));
		titleRow.setOpaque(false);
		JLabel title = new JLabel("Raid finder", new ImageIcon(PanelArt.skull()), SwingConstants.LEFT);
		title.setIconTextGap(6);
		title.setFont(FontManager.getRunescapeBoldFont().deriveFont(18f));
		title.setForeground(PanelArt.HORN);
		titleRow.add(title, BorderLayout.CENTER);
		JPanel right = new JPanel();
		right.setLayout(new BoxLayout(right, BoxLayout.X_AXIS));
		right.setOpaque(false);
		badge.setFont(FontManager.getRunescapeSmallFont());
		badge.setForeground(Color.WHITE);
		badge.setBackground(PanelArt.HORN);
		badge.setOpaque(true);
		badge.setBorder(new EmptyBorder(1, 4, 1, 4));
		right.add(badge);
		right.add(Box.createHorizontalStrut(6));
		marker.setFont(FontManager.getRunescapeSmallFont());
		marker.setForeground(PanelArt.STEEL_LIGHT);
		right.add(marker);
		JPanel rightHolder = new JPanel(new GridBagLayout());
		rightHolder.setOpaque(false);
		rightHolder.add(right);
		titleRow.add(rightHolder, BorderLayout.EAST);
		header.add(titleRow, BorderLayout.NORTH);
		header.add(summary, BorderLayout.SOUTH);
		plaque.add(header, BorderLayout.NORTH);

		body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
		body.setOpaque(false);
		body.setVisible(false);
		plaque.add(body, BorderLayout.CENTER);

		listings.setLayout(new BoxLayout(listings, BoxLayout.Y_AXIS));
		listings.setOpaque(false);
		listings.setAlignmentX(LEFT_ALIGNMENT);
		body.add(listings);
		body.add(Box.createVerticalStrut(8));
		JLabel yours = RankCard.heading("Your group");
		yours.setAlignmentX(LEFT_ALIGNMENT);
		body.add(yours);
		mine.setFont(FontManager.getRunescapeSmallFont());
		mine.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		mine.setAlignmentX(LEFT_ALIGNMENT);
		body.add(mine);
		body.add(Box.createVerticalStrut(4));
		JPanel form = buildForm(actions);
		form.setAlignmentX(LEFT_ALIGNMENT);
		body.add(form);
		hint.setAlignmentX(LEFT_ALIGNMENT);
		body.add(hint);

		header.setToolTipText("Click to show or hide");
		hookClicks(header, new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				body.setVisible(!body.isVisible());
				updateMarker();
				revalidate();
				repaint();
			}
		});
		updateMarker();
	}

	/** Raid, filled of size, a note, then Post / Take down. */
	private JPanel buildForm(Actions actions)
	{
		InsetPanel form = new InsetPanel(new BorderLayout(0, 4));
		form.setBorder(BorderFactory.createEmptyBorder(6, 6, 6, 6));

		JPanel grid = new JPanel(new GridLayout(0, 2, 4, 4));
		grid.setOpaque(false);
		grid.add(caption("Raid"));
		raidBox.setFocusable(false);
		raidBox.setSelectedItem(Raid.COX);
		grid.add(raidBox);
		grid.add(caption("Slots filled"));
		grid.add(new JSpinner(filledModel));
		grid.add(caption("Party size"));
		grid.add(new JSpinner(sizeModel));
		form.add(grid, BorderLayout.NORTH);

		JPanel noteRow = new JPanel(new BorderLayout(0, 2));
		noteRow.setOpaque(false);
		noteRow.add(caption("Note (optional, e.g. \"need a tank, 300+ kc\")"), BorderLayout.NORTH);
		note.setToolTipText("Up to " + RaidAd.MAX_NOTE + " characters");
		noteRow.add(note, BorderLayout.CENTER);
		form.add(noteRow, BorderLayout.CENTER);

		JPanel buttons = new JPanel(new GridLayout(1, 2, 6, 0));
		buttons.setOpaque(false);
		buttons.add(postButton);
		buttons.add(stopButton);
		JPanel actionsPanel = new JPanel(new BorderLayout(0, 4));
		actionsPanel.setOpaque(false);
		actionsPanel.add(buttons, BorderLayout.NORTH);
		pingButton.setToolTipText("Post your group in the looking-for-group channel of the clan Discord (once every 10 minutes)");
		actionsPanel.add(pingButton, BorderLayout.SOUTH);
		form.add(actionsPanel, BorderLayout.SOUTH);

		// party size follows the raid; filled can never pass the size
		raidBox.addActionListener(e ->
		{
			Raid raid = (Raid) raidBox.getSelectedItem();
			if (raid != null)
			{
				sizeModel.setMaximum(raid.maxSize);
				sizeModel.setValue(raid.defaultSize);
			}
		});
		sizeModel.addChangeListener(e ->
		{
			int size = sizeModel.getNumber().intValue();
			filledModel.setMaximum(size);
			if (filledModel.getNumber().intValue() > size)
			{
				filledModel.setValue(size);
			}
		});
		postButton.addActionListener(e ->
		{
			Raid raid = (Raid) raidBox.getSelectedItem();
			if (raid != null)
			{
				actions.post(new RaidAd(raid, filledModel.getNumber().intValue(), sizeModel.getNumber().intValue(), note.getText()));
			}
		});
		stopButton.addActionListener(e -> actions.stop());
		pingButton.addActionListener(e -> actions.ping());
		return form;
	}

	/**
	 * @param board every open group, newest first
	 * @param me our character name, or null when logged out
	 * @param myAd our own group as last posted, or null
	 * @param problem why we can't post (clan sync off, logged out), or null
	 */
	void fill(List<RaidListing> board, String me, RaidAd myAd, String problem)
	{
		badge.setText(board.size() + (board.stream().allMatch(l -> l.raiding) ? " raiding" : " open"));
		badge.setVisible(!board.isEmpty());
		summary.setText(summary(board));
		plaque.setLive(!board.isEmpty());

		boolean canPost = problem == null;
		hint.setText(canPost ? "Your group shows as raiding while you're in the raid, and comes down 30 minutes after you"
			+ " log out." : problem);
		postButton.setEnabled(canPost);
		postButton.setText(myAd == null ? "Post group" : "Update");
		stopButton.setEnabled(canPost && myAd != null);
		pingButton.setEnabled(canPost && myAd != null);
		mine.setText(myAd == null ? "Not looking right now." : "Looking for " + myAd.raid.fullName + ", " + myAd.slots() + " filled.");
		if (myAd != null && !myAd.equals(shownAd))
		{
			// show what is posted (after a login the form starts fresh)
			raidBox.setSelectedItem(myAd.raid);
			sizeModel.setValue(myAd.size);
			filledModel.setValue(myAd.filled);
			note.setText(myAd.note);
		}
		shownAd = myAd;

		long minute = System.currentTimeMillis() / 60_000L;
		if (board.equals(shown) && Objects.equals(me, shownMe) && minute == shownMinute && listings.getComponentCount() > 0)
		{
			return;
		}
		shown = board;
		shownMe = me;
		shownMinute = minute;
		listings.removeAll();
		JLabel open = RankCard.heading("Looking for a party");
		open.setAlignmentX(LEFT_ALIGNMENT);
		listings.add(open);
		if (board.isEmpty())
		{
			WrapText none = new WrapText(FontManager.getRunescapeSmallFont(), ColorScheme.LIGHT_GRAY_COLOR);
			none.setText("No groups looking right now. Put yours up below.");
			none.setAlignmentX(LEFT_ALIGNMENT);
			listings.add(none);
		}
		long now = System.currentTimeMillis();
		for (RaidListing listing : board)
		{
			listings.add(Box.createVerticalStrut(4));
			JPanel row = row(listing, listing.isHost(me), now);
			row.setAlignmentX(LEFT_ALIGNMENT);
			listings.add(row);
		}
		listings.revalidate();
		listings.repaint();
	}

	/** "ToB 3/5, CoX 2/5 and 1 more" or a nudge when the board is empty */
	static String summary(List<RaidListing> board)
	{
		if (board.isEmpty())
		{
			return "Nobody is looking for a raid party right now.";
		}
		StringBuilder text = new StringBuilder("Looking: ");
		int listed = Math.min(2, board.size());
		for (int i = 0; i < listed; i++)
		{
			RaidListing l = board.get(i);
			text.append(i > 0 ? ", " : "").append(l.raid.shortName).append(' ').append(l.slots())
				.append(l.raiding ? " raiding" : "");
		}
		if (board.size() > listed)
		{
			text.append(" and ").append(board.size() - listed).append(" more");
		}
		return text.append('.').toString();
	}

	/** raid tag | host (you) and world, slots pips and age, the note */
	private static JPanel row(RaidListing l, boolean mine, long now)
	{
		InsetPanel row = new InsetPanel(new BorderLayout(6, 0));
		row.setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 6));

		JLabel tag = new JLabel(l.raid.shortName, SwingConstants.CENTER);
		tag.setFont(FontManager.getRunescapeBoldFont());
		tag.setForeground(Color.WHITE);
		tag.setBackground(PanelArt.mix(l.raid.color, Color.BLACK, 0.25f));
		tag.setOpaque(true);
		tag.setBorder(new EmptyBorder(2, 4, 2, 4));
		tag.setToolTipText(l.raid.fullName);
		JPanel tagHolder = new JPanel(new BorderLayout());
		tagHolder.setOpaque(false);
		tagHolder.add(tag, BorderLayout.NORTH);
		row.add(tagHolder, BorderLayout.WEST);

		JPanel text = new JPanel();
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		text.setOpaque(false);

		JPanel top = new JPanel(new BorderLayout(4, 0));
		top.setOpaque(false);
		top.setAlignmentX(LEFT_ALIGNMENT);
		boolean away = l.isAway(now);
		JLabel name = new JLabel(mine ? l.name + " (you)" : away ? l.name + " (away)" : l.name);
		if (away)
		{
			name.setToolTipText("Logged out; the group stays up for an hour");
		}
		name.setFont(FontManager.getRunescapeBoldFont());
		name.setForeground(mine ? PanelArt.mix(l.raid.color, Color.WHITE, 0.4f) : away ? ColorScheme.LIGHT_GRAY_COLOR : Color.WHITE);
		top.add(name, BorderLayout.CENTER);
		if (l.world > 0)
		{
			JLabel world = small("W" + l.world, PanelArt.STEEL_LIGHT);
			world.setToolTipText("World " + l.world);
			top.add(world, BorderLayout.EAST);
		}
		text.add(top);

		JPanel slots = new JPanel(new BorderLayout(4, 0));
		slots.setOpaque(false);
		slots.setAlignmentX(LEFT_ALIGNMENT);
		JLabel filled = small(l.raiding ? l.slots() + " raiding now" : l.slots() + " filled", l.raid.color);
		if (l.size <= PanelArt.MAX_PIPS)
		{
			filled.setIcon(new ImageIcon(PanelArt.pips(l.filled, l.size, l.raid.color)));
			filled.setIconTextGap(5);
		}
		slots.add(filled, BorderLayout.CENTER);
		if (l.postedAt > 0)
		{
			slots.add(small(PromotionsCard.ago(now - l.postedAt), ColorScheme.LIGHT_GRAY_COLOR), BorderLayout.EAST);
		}
		text.add(slots);

		if (!l.note.isEmpty())
		{
			WrapText note = new WrapText(FontManager.getRunescapeSmallFont(), ColorScheme.LIGHT_GRAY_COLOR);
			note.setText(l.note);
			note.setAlignmentX(LEFT_ALIGNMENT);
			text.add(note);
		}
		row.add(text, BorderLayout.CENTER);
		return row;
	}

	private static JLabel caption(String text)
	{
		return small(text, ColorScheme.LIGHT_GRAY_COLOR);
	}

	private static JLabel small(String text, Color color)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(color);
		return label;
	}

	/** plain ASCII: the RuneScape font has no arrow glyphs */
	private void updateMarker()
	{
		marker.setText(body.isVisible() ? "[-]" : "[+]");
	}

	private static void hookClicks(Component component, MouseAdapter click)
	{
		component.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		component.addMouseListener(click);
		if (component instanceof Container)
		{
			for (Component child : ((Container) component).getComponents())
			{
				hookClicks(child, click);
			}
		}
	}
}

package com.corclan.ui;

import com.corclan.CorClanConfig;
import com.corclan.glow.DevGlow;
import com.corclan.glow.FounderGlow;
import com.corclan.glow.GemGlow;
import com.corclan.glow.GlowEffect;
import com.corclan.glow.GlowPicks;
import com.corclan.glow.NatureGlow;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.GridLayout;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.BiConsumer;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JCheckBox;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * The player's own clan rank on a plaque, with their rank's emblem and one big glow switch. The switch flips the same
 * settings as the per-effect checkboxes further down (Owner, Dev, Founder, Nature glow, staff gold twinkle, gem outline + sparkles), so it is a
 * shortcut, not a new setting. The plaque animates (in the logo's horn red) while the glow is on.
 */
final class RankCard extends JPanel
{
	private static final Color STEEL = new Color(140, 160, 190);
	private static final Color OWNER = new Color(255, 190, 40);
	private static final Color MOLTEN = new Color(235, 70, 20);
	private static final Color FOUNDER = new Color(220, 40, 60);
	private static final Color NATURE = new Color(50, 205, 80);

	private final CorClanConfig config;
	/** config key, new value: the same setter the per-effect checkboxes use */
	private final BiConsumer<String, Boolean> setGlow;

	private final ArtPlaque plaque = new ArtPlaque(new BorderLayout(10, 8));
	private final JLabel emblem = new JLabel();
	private final JLabel caption = new JLabel("YOUR RANK");
	private final JLabel title = new JLabel();
	private final JLabel name = new JLabel();
	private final JCheckBox glow = new JCheckBox("Glow");
	private final WrapText glowNote = new WrapText(FontManager.getRunescapeSmallFont(), ColorScheme.LIGHT_GRAY_COLOR);
	private final StatTile given = new StatTile("GZ GIVEN");
	private final StatTile received = new StatTile("GZ'D");
	/** this client's totals, then clan sync, the CoR party and the clan map, one line each */
	private final WrapText status = new WrapText(FontManager.getRunescapeSmallFont(), ColorScheme.LIGHT_GRAY_COLOR);
	/** what the side panel puts under the glow switch: trophies, links, the party button */
	private final JPanel extras = new JPanel();

	/** config key to its current value, for every glow setting this player's switch controls */
	private Map<String, Boolean> controlled = new LinkedHashMap<>();
	/** which of them were on when the switch last turned the glow off, so turning it on again restores them */
	private Set<String> remembered = new HashSet<>();
	private PanelArt.Emblem shownEmblem;
	private Color accent = STEEL;

	RankCard(CorClanConfig config, BiConsumer<String, Boolean> setGlow)
	{
		super(new BorderLayout());
		this.config = config;
		this.setGlow = setGlow;
		setOpaque(false);

		JPanel words = new JPanel();
		words.setLayout(new BoxLayout(words, BoxLayout.Y_AXIS));
		words.setOpaque(false);
		caption.setFont(FontManager.getRunescapeSmallFont());
		caption.setForeground(PanelArt.STEEL);
		title.setFont(FontManager.getRunescapeBoldFont().deriveFont(22f));
		name.setFont(FontManager.getRunescapeSmallFont());
		name.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		words.add(caption);
		words.add(title);
		words.add(name);

		glow.setFont(FontManager.getRunescapeBoldFont().deriveFont(18f));
		glow.setOpaque(false);
		glow.setFocusable(false);
		glow.setIconTextGap(8);
		glow.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		glow.addActionListener(e -> flip(glow.isSelected()));
		JPanel switchRow = new JPanel(new BorderLayout(0, 2));
		switchRow.setOpaque(false);
		switchRow.add(glow, BorderLayout.NORTH);
		switchRow.add(glowNote, BorderLayout.CENTER);

		// the GZ tracker, built into the card: two counters, then the status lines
		JPanel tiles = new JPanel(new GridLayout(1, 2, 6, 0));
		tiles.setOpaque(false);
		tiles.add(given);
		tiles.add(received);
		JPanel gz = new JPanel(new BorderLayout(0, 6));
		gz.setOpaque(false);
		gz.add(tiles, BorderLayout.NORTH);
		gz.add(status, BorderLayout.CENTER);

		extras.setLayout(new BoxLayout(extras, BoxLayout.Y_AXIS));
		extras.setOpaque(false);

		JPanel lower = new JPanel(new BorderLayout(0, 8));
		lower.setOpaque(false);
		lower.add(gz, BorderLayout.NORTH);
		lower.add(switchRow, BorderLayout.CENTER);
		lower.add(extras, BorderLayout.SOUTH);

		plaque.add(emblem, BorderLayout.WEST);
		plaque.add(words, BorderLayout.CENTER);
		plaque.add(lower, BorderLayout.SOUTH);
		add(plaque, BorderLayout.CENTER);
		setBorder(new EmptyBorder(8, 0, 0, 0));
	}

	/** Adds something under the glow switch, inside the art. */
	void addExtra(JComponent component)
	{
		if (extras.getComponentCount() > 0)
		{
			extras.add(Box.createVerticalStrut(8));
		}
		component.setAlignmentX(LEFT_ALIGNMENT);
		extras.add(component);
	}

	/** A horn-red heading inside the art, for a group of extras. */
	static JLabel heading(String text)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeBoldFont());
		label.setForeground(PanelArt.HORN);
		return label;
	}

	void fill(PanelData data)
	{
		PanelArt.Emblem kind;
		if (data.myName == null)
		{
			kind = PanelArt.Emblem.NONE;
			title.setText("Log in");
			name.setText("to see your clan rank");
		}
		else if (data.myRankTitle == null)
		{
			kind = PanelArt.Emblem.NONE;
			title.setText("No clan");
			name.setText(data.myName + " is not in a clan");
		}
		else
		{
			kind = data.dev ? PanelArt.Emblem.FLAME
				: data.founder ? PanelArt.Emblem.SUN
				: data.nature ? PanelArt.Emblem.LEAF
				: data.owner ? PanelArt.Emblem.CROWN
				: data.myGem != null ? PanelArt.Emblem.GEM
				: PanelArt.Emblem.STAR;
			title.setText(data.myRankTitle);
			name.setText(data.myName);
		}
		boolean in = data.myName != null;
		given.set(in ? String.valueOf(data.myGiven) : "-", in ? "+" + data.myGivenToday + " today" : "log in");
		received.set(in ? String.valueOf(data.myReceived) : "-", in ? "+" + data.myReceivedToday + " today" : "log in");
		status.setText(data.summary + "\n" + data.syncStatus + "\n" + data.partyStatus + "\n" + data.mapStatus);

		Color newAccent = accentOf(kind, data.myGem);
		if (kind != shownEmblem || !newAccent.equals(accent))
		{
			shownEmblem = kind;
			accent = newAccent;
			emblem.setIcon(new ImageIcon(PanelArt.emblem(kind, accent)));
		}
		title.setForeground(kind == PanelArt.Emblem.NONE ? ColorScheme.LIGHT_GRAY_COLOR : PanelArt.mix(accent, Color.WHITE, 0.35f));

		controlled = controlledSettings(data);
		boolean any = controlled.containsValue(true);
		boolean shown = any && config.rankGlow();
		glow.setVisible(kind != PanelArt.Emblem.NONE);
		glowNote.setVisible(kind != PanelArt.Emblem.NONE);
		glow.setEnabled(!controlled.isEmpty());
		glow.setSelected(shown);
		glow.setText(controlled.isEmpty() ? "Glow" : shown ? "Glow ON" : "Glow OFF");
		glow.setForeground(shown ? PanelArt.HORN : ColorScheme.LIGHT_GRAY_COLOR);
		glow.setIcon(new ImageIcon(PanelArt.glowSwitch(false, !controlled.isEmpty())));
		glow.setSelectedIcon(new ImageIcon(PanelArt.glowSwitch(true, true)));
		glow.setDisabledIcon(new ImageIcon(PanelArt.glowSwitch(false, false)));
		glow.setToolTipText(controlled.isEmpty() ? null
			: "Switches your " + String.join(", ", labels(data)).toLowerCase() + ". Fine-tune each part further down");
		glowNote.setText(controlled.isEmpty() ? "No glow at your rank yet"
			: !config.rankGlow() ? "Glows are hidden in the CoR Clan settings"
			: any ? "Other CoR plugin users see it on you" : "Tick to show your rank's glow");
		plaque.setLive(shown);
	}

	/** Turns every glow setting this switch controls on or off. Turning on also unhides glows if they were hidden. */
	private void flip(boolean on)
	{
		if (controlled.isEmpty())
		{
			return;
		}
		if (on)
		{
			if (!config.rankGlow())
			{
				setGlow.accept("rankGlow", true);
			}
			boolean restore = !remembered.isEmpty();
			for (String key : controlled.keySet())
			{
				setGlow.accept(key, !restore || remembered.contains(key));
			}
		}
		else
		{
			remembered = new HashSet<>();
			for (Map.Entry<String, Boolean> e : controlled.entrySet())
			{
				if (e.getValue())
				{
					remembered.add(e.getKey());
				}
				setGlow.accept(e.getKey(), false);
			}
		}
	}

	/** Every glow setting that is this player's own, with its current value. Empty when their rank has no glow. */
	private Map<String, Boolean> controlledSettings(PanelData data)
	{
		Map<String, Boolean> keys = new LinkedHashMap<>();
		if (data.myRankTitle == null)
		{
			return keys;
		}
		if (data.owner)
		{
			for (GlowEffect e : GlowEffect.values())
			{
				keys.put(e.configKey, GlowPicks.picked(config, e));
			}
		}
		if (data.dev)
		{
			for (DevGlow e : DevGlow.values())
			{
				keys.put(e.configKey, DevGlow.picked(config, e));
			}
		}
		if (data.founder)
		{
			for (FounderGlow e : FounderGlow.values())
			{
				keys.put(e.configKey, FounderGlow.picked(config, e));
			}
		}
		if (data.nature)
		{
			for (NatureGlow e : NatureGlow.values())
			{
				keys.put(e.configKey, NatureGlow.picked(config, e));
			}
		}
		if (data.staff)
		{
			keys.put("glowStaffTwinkle", config.glowStaffTwinkle());
		}
		// a molten-outline wearer shows no gem glow on top, so the gem parts are not theirs to switch
		if (data.myGem != null && !data.dev)
		{
			for (GemGlow.Part p : GemGlow.Part.values())
			{
				keys.put(p.configKey, GemGlow.Part.picked(config, p));
			}
		}
		return keys;
	}

	private static List<String> labels(PanelData data)
	{
		List<String> out = new ArrayList<>();
		if (data.owner)
		{
			out.add("Owner glow");
		}
		if (data.dev)
		{
			out.add("Dev glow");
		}
		if (data.founder)
		{
			out.add("Founder glow");
		}
		if (data.nature)
		{
			out.add("Nature glow");
		}
		if (data.staff)
		{
			out.add("Staff gold twinkle");
		}
		if (data.myGem != null && !data.dev)
		{
			out.add(data.myGem.title + " glow");
		}
		return out;
	}

	private static Color accentOf(PanelArt.Emblem kind, GemGlow gem)
	{
		switch (kind)
		{
			case CROWN:
				return OWNER;
			case FLAME:
				return MOLTEN;
			case SUN:
				return FOUNDER;
			case LEAF:
				return NATURE;
			case GEM:
				return gemColor(gem);
			case NONE:
				return new Color(110, 110, 110);
			default:
				return STEEL;
		}
	}

	/** A gz counter: a dark inset with a thin steel rim, a big white number, a caption and today's gain. */
	private static final class StatTile extends InsetPanel
	{
		private final JLabel number = new JLabel("-", SwingConstants.CENTER);
		private final JLabel today = new JLabel(" ", SwingConstants.CENTER);

		StatTile(String caption)
		{
			super(new BorderLayout());
			setBorder(new EmptyBorder(4, 4, 4, 4));
			JLabel top = new JLabel(caption, SwingConstants.CENTER);
			top.setFont(FontManager.getRunescapeSmallFont());
			top.setForeground(PanelArt.STEEL);
			number.setFont(FontManager.getRunescapeBoldFont().deriveFont(20f));
			number.setForeground(Color.WHITE);
			today.setFont(FontManager.getRunescapeSmallFont());
			today.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			add(top, BorderLayout.NORTH);
			add(number, BorderLayout.CENTER);
			add(today, BorderLayout.SOUTH);
		}

		void set(String value, String gain)
		{
			number.setText(value);
			today.setText(gain);
		}

	}

	static Color gemColor(GemGlow gem)
	{
		switch (gem)
		{
			case ZENYTE:
				return new Color(255, 150, 40);
			case ONYX:
				return new Color(120, 110, 130);
			case DRAGONSTONE:
				return new Color(175, 80, 225);
			case DIAMOND:
				return new Color(215, 240, 255);
			case RUBY:
				return new Color(225, 35, 55);
			case EMERALD:
				return new Color(40, 195, 95);
			case SAPPHIRE:
				return new Color(55, 100, 235);
			default:
				return new Color(235, 215, 235);
		}
	}
}

package com.corclan.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Rectangle;
import javax.swing.JTextArea;
import javax.swing.text.DefaultCaret;

/**
 * Read-only text that wraps at word breaks to whatever width its container gives it, so nothing is ever cut off.
 * (An HTML label with a fixed width does not fit reliably: Swing scales its CSS pixels with the screen.) Plain text,
 * so nothing in it is ever read as markup; new lines start new lines. It never scrolls the panel: a text area's caret
 * normally asks the scroll pane to show it whenever the text changes, which jumped the side panel to the top on every
 * refresh.
 */
final class WrapText extends JTextArea
{
	WrapText(Font font, Color color)
	{
		setLineWrap(true);
		setWrapStyleWord(true);
		setEditable(false);
		setFocusable(false);
		setOpaque(false);
		setBorder(null);
		setHighlighter(null);
		setFont(font);
		setForeground(color);
		setAlignmentX(LEFT_ALIGNMENT);
		((DefaultCaret) getCaret()).setUpdatePolicy(DefaultCaret.NEVER_UPDATE);
	}

	/** Only touches the text when it changed, so a refresh with the same text does nothing at all. */
	@Override
	public void setText(String text)
	{
		if (!java.util.Objects.equals(text, getText()))
		{
			super.setText(text);
		}
	}

	/** Read-only text never needs to be scrolled to. */
	@Override
	public void scrollRectToVisible(Rectangle rect)
	{
	}

	/** As tall as the wrapped text, never stretched by a box layout. */
	@Override
	public Dimension getMaximumSize()
	{
		return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
	}
}

