import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.stream.Collectors;
import org.junit.Test;

public class ClanRosterTest
{
	private static List<String> names(RankGroup g)
	{
		return g.members.stream().map(m -> m.name).collect(Collectors.toList());
	}

	@Test
	public void groupsByRankHighestFirst()
	{
		List<RankGroup> groups = ClanRoster.group(Arrays.asList(
			new Member("Recruit1", 0, "Recruit", false),
			new Member("Boss", 126, "Owner", true),
			new Member("Cap", 5, "Captain", false),
			new Member("Deputy", 125, "Deputy Owner", false),
			new Member("Recruit2", 0, "Recruit", true)));

		assertEquals(Arrays.asList(126, 125, 5, 0), groups.stream().map(g -> g.rank).collect(Collectors.toList()));
		assertEquals("Owner", groups.get(0).title);
		assertEquals("Captain", groups.get(2).title);
		assertEquals(5, ClanRoster.total(groups));
		assertEquals(2, ClanRoster.online(groups));
	}

	@Test
	public void onlineFirstThenNameIgnoringCase()
	{
		List<RankGroup> groups = ClanRoster.group(Arrays.asList(
			new Member("zed", 0, "Recruit", false),
			new Member("Bob", 0, "Recruit", true),
			new Member("alice", 0, "Recruit", false),
			new Member("Carl", 0, "Recruit", true)));
		assertEquals(Arrays.asList("Bob", "Carl", "alice", "zed"), names(groups.get(0)));
		assertEquals(2, groups.get(0).onlineCount());
	}

	@Test
	public void missingTitleFallsBackToRankNumber()
	{
		List<RankGroup> groups = ClanRoster.group(Collections.singletonList(new Member("Someone", 7, null, false)));
		assertEquals("Rank 7", groups.get(0).title);
	}

	@Test
	public void skipsBlankNamesAndHandlesEmpty()
	{
		assertTrue(ClanRoster.group(Collections.emptyList()).isEmpty());
		List<RankGroup> groups = ClanRoster.group(Arrays.asList(new Member("", 0, "Recruit", false), null,
			new Member("Real", 0, "Recruit", false)));
		assertEquals(1, ClanRoster.total(groups));
	}

	@Test
	public void sameMembersGiveEqualGroups()
	{
		List<Member> a = Arrays.asList(new Member("Bob", 0, "Recruit", true), new Member("Ann", 5, "Captain", false));
		List<Member> b = Arrays.asList(new Member("Ann", 5, "Captain", false), new Member("Bob", 0, "Recruit", true));
		assertEquals(ClanRoster.group(a), ClanRoster.group(b));
	}
}

package com.corclan.clan;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.time.LocalDate;
import org.junit.Test;

public class InfernoReminderTest
{
	private static final LocalDate MON = LocalDate.of(2026, 10, 12);

	@Test
	public void onlyJoeBoobIsRemindedAndOnlyRayWatches()
	{
		assertTrue(InfernoReminder.isTarget("JoeBoob"));
		assertFalse(InfernoReminder.isTarget("Lavasockz"));
		assertTrue(InfernoReminder.isWatcher("UimFartQueef"));
		assertFalse(InfernoReminder.isWatcher("JoeBoob"));
	}

	@Test
	public void countsOncePerDay()
	{
		assertEquals(1, InfernoReminder.countAfter(null, MON));
		String stored = InfernoReminder.store(MON, 1);
		// logging in again the same day keeps the number
		assertEquals(1, InfernoReminder.countAfter(stored, MON));
		assertEquals(2, InfernoReminder.countAfter(stored, MON.plusDays(1)));
		// days he doesn't log in don't count
		assertEquals(2, InfernoReminder.countAfter(stored, MON.plusDays(9)));
	}

	@Test
	public void aBrokenStoredValueStartsAgain()
	{
		assertEquals(1, InfernoReminder.countAfter("garbage", MON));
		assertEquals(1, InfernoReminder.countAfter("2026-10-12|x", MON));
		assertEquals(1, InfernoReminder.countAfter("2026-10-12|0", MON));
	}

	@Test
	public void linesCarryTheDay()
	{
		assertTrue(InfernoReminder.targetLine(null, 7).contains("Daily reminder #7: go and get your Infernal cape."));
		assertTrue(InfernoReminder.watcherLine("<img=3>", "JoeBoob", 7).startsWith("<img=3> "));
		assertTrue(InfernoReminder.watcherLine(null, "JoeBoob", 7).contains("(day 7)"));
	}
}

package com.corclan.clan;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class LegionTest
{
	@Test
	public void theFourLeadersAreTheLegionAndRayIsTheSpartan()
	{
		for (String name : new String[]{"UimFartQueef", "JoeBoob", "Lavasockz", "DAYLlGHT"})
		{
			assertTrue(name, Legion.isLegionnaire(name));
		}
		assertFalse(Legion.isLegionnaire("Zezima"));
		assertTrue(Legion.isSpartan("uimfartqueef"));
		assertFalse(Legion.isSpartan("JoeBoob"));
	}

	@Test
	public void aFirstJoinIsALogin()
	{
		assertTrue(new Legion().isLogin("JoeBoob", 1_000L));
	}

	@Test
	public void aQuickRejoinIsAWorldHop()
	{
		Legion legion = new Legion();
		legion.left("JoeBoob", 10_000L);
		assertFalse(legion.isLogin("JoeBoob", 18_000L));
		// the hop is used up: the next join without leaving again is not mistaken for another hop
		assertTrue(legion.isLogin("JoeBoob", 19_000L));
	}

	@Test
	public void rejoiningLongAfterLeavingIsALogin()
	{
		Legion legion = new Legion();
		legion.left("Lavasockz", 0L);
		assertTrue(legion.isLogin("Lavasockz", Legion.HOP_MILLIS + 1));
	}

	@Test
	public void othersAreNeverAnnounced()
	{
		Legion legion = new Legion();
		legion.left("Zezima", 0L);
		assertFalse(legion.isLogin("Zezima", 999_999L));
	}

	@Test
	public void theSpartanGetsGoldAndIconsBothSides()
	{
		String line = Legion.line("UimFartQueef", "<img=7>");
		assertTrue(line.startsWith("<img=7> "));
		assertTrue(line.endsWith(" <img=7>"));
		assertTrue(line.contains("<col=" + Legion.SPARTAN_COLOR + ">A Spartan has landed!"));
	}

	@Test
	public void legionnairesAreNamedAndMarkupCannotSneakIn()
	{
		String line = Legion.line("Joe<b>Boob", null);
		assertTrue(line.contains("One of the legionnaires has logged in: JoebBoob"));
		assertFalse(line.contains("<b>"));
	}
}

package com.corclan.clan;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.corclan.clan.ClanRoster.Member;
import com.corclan.clan.OrgChart.Chart;
import com.corclan.clan.OrgChart.Slot;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import org.junit.Test;

public class OrgChartTest
{
	/** A clan set up like CoR: staff on top, letter tiers, then the gem league. */
	private static Map<Integer, String> corRanks()
	{
		Map<Integer, String> r = new HashMap<>();
		r.put(126, "Owner");
		r.put(125, "Deputy Owner");
		r.put(100, "Administrator");
		r.put(95, "Marshal");
		r.put(90, "General");
		r.put(85, "Brigadier");
		r.put(80, "Colonel");
		r.put(75, "Major");
		r.put(70, "Goon");
		r.put(65, "Executive");
		r.put(60, "Short green guy");
		r.put(55, "Hero");
		r.put(50, "Soul");
		r.put(45, "Achiever");
		r.put(40, "Beast");
		r.put(35, "Competitor");
		r.put(30, "Dragon");
		r.put(25, "Elite");
		r.put(20, "Gnome child");
		r.put(17, "Zenyte");
		r.put(16, "Onyx");
		r.put(15, "Dragonstone");
		r.put(14, "Diamond");
		r.put(13, "Ruby");
		r.put(12, "Emerald");
		r.put(11, "Sapphire");
		r.put(10, "Opal");
		return r;
	}

	private static Chart chart(Map<Integer, String> ranks, Member... members)
	{
		return OrgChart.build(ClanRoster.group(Arrays.asList(members)), ranks);
	}

	private static List<String> titles(OrgChart.Tier tier)
	{
		return tier.slots.stream().map(s -> s.title).collect(Collectors.toList());
	}

	private static Slot slot(OrgChart.Tier tier, String title)
	{
		return tier.slots.stream().filter(s -> s.title.equalsIgnoreCase(title)).findFirst().orElseThrow(AssertionError::new);
	}

	@Test
	public void staffTiersInTheCorOrder()
	{
		Chart c = chart(corRanks());
		assertEquals(3, c.staff.size());
		assertEquals(Arrays.asList("Owner", "Deputy Owner"), titles(c.staff.get(0)));
		assertEquals(Arrays.asList("Marshal", "General", "Brigadier", "Colonel", "Administrator"), titles(c.staff.get(1)));
		assertEquals(Arrays.asList("Major", "Goon", "Executive", "Short green guy", "Hero"), titles(c.staff.get(2)));
	}

	@Test
	public void letterTiersAreTheCompetitiveBracketSToF()
	{
		OrgChart.Tier letters = chart(corRanks()).competitive.get(1);
		assertEquals("Challenger League", letters.name);
		assertEquals(Arrays.asList("Soul", "Achiever", "Beast", "Competitor", "Dragon", "Elite", "Gnome child"), titles(letters));
		assertEquals(Arrays.asList("S", "A", "B", "C", "D", "E", "F"),
			letters.slots.stream().map(s -> s.grade).collect(Collectors.toList()));
	}

	@Test
	public void gemLeagueComesFirstHighestFirstAndIsOpen()
	{
		Chart c = chart(corRanks());
		assertEquals(2, c.competitive.size());
		OrgChart.Tier gems = c.competitive.get(0);
		assertEquals("Gem League", gems.name);
		assertNull(gems.lockedNote);
		assertEquals(Arrays.asList("Zenyte", "Onyx", "Dragonstone", "Diamond", "Ruby", "Emerald", "Sapphire", "Opal"), titles(gems));
	}

	@Test
	public void membersLandInTheirSlotAndEmptyRanksStayVacant()
	{
		Chart c = chart(corRanks(),
			new Member("Boss", 126, "Owner", true),
			new Member("Ace", 45, "Achiever", true),
			new Member("Newbie", 10, "Opal", false),
			new Member("Newbie2", 10, "Opal", true));

		assertEquals(1, slot(c.staff.get(0), "Owner").members.size());
		assertEquals(1, slot(c.competitive.get(1), "Achiever").members.size());
		assertEquals(2, slot(c.competitive.get(0), "Opal").members.size());
		assertEquals(1, slot(c.competitive.get(0), "Opal").onlineCount());
		assertTrue(slot(c.competitive.get(1), "Soul").members.isEmpty());
		assertTrue(slot(c.staff.get(1), "General").members.isEmpty());
		assertTrue(c.others.isEmpty());
	}

	@Test
	public void allSevenLetterTiersShowBeforeTheyExistInGame()
	{
		// a clan that hasn't set up the competitive ranks yet
		Chart c = chart(Collections.singletonMap(126, "Owner"));
		OrgChart.Tier letters = c.competitive.get(1);
		assertEquals(7, letters.slots.size());
		assertTrue(letters.slots.stream().allMatch(s -> s.members.isEmpty()));
		assertEquals("Gem League", c.competitive.get(0).name);
	}

	@Test
	public void challengerLeagueSitsUnderTheGemsLockedUntilAnnounced()
	{
		OrgChart.Tier letters = chart(corRanks()).competitive.get(1);
		assertEquals("Challenger League", letters.name);
		assertNotNull(letters.lockedNote);
		assertTrue(letters.lockedNote.contains("announced soon"));
	}

	@Test
	public void gradeFollowsTheListNotTheInGameRankOrder()
	{
		// Dragon set up above Soul in-game: still graded D, and Soul still S
		Map<Integer, String> r = new HashMap<>();
		r.put(60, "Dragon");
		r.put(50, "Soul");
		Chart c = chart(r, new Member("Dee", 60, "Dragon", false));
		assertEquals("D", slot(c.competitive.get(1), "Dragon").grade);
		assertEquals(1, slot(c.competitive.get(1), "Dragon").members.size());
		assertEquals("S", slot(c.competitive.get(1), "Soul").grade);
	}

	@Test
	public void staffAndGemTiersHaveNoGrades()
	{
		Chart c = chart(corRanks());
		assertTrue(c.staff.stream().flatMap(t -> t.slots.stream()).allMatch(s -> s.grade == null));
		assertTrue(c.competitive.get(0).slots.stream().allMatch(s -> s.grade == null));
	}

	@Test
	public void titleMatchingIgnoresCaseSpacingAndMarshallSpelling()
	{
		Map<Integer, String> r = new HashMap<>();
		r.put(95, "Marshall");
		r.put(60, "  short   GREEN guy ");
		Chart c = chart(r, new Member("M", 95, "Marshall", false));
		assertEquals(1, slot(c.staff.get(1), "Marshall").members.size());
		assertEquals("  short   GREEN guy ", c.staff.get(2).slots.get(3).title);
		assertTrue(c.others.isEmpty());
	}

	@Test
	public void unchartedRanksGoToOthers()
	{
		Chart c = chart(Collections.singletonMap(30, "Sniper"), new Member("Pvp", 30, "Sniper", false),
			new Member("Boss", 126, "Owner", false));
		assertEquals(Collections.singletonList("Sniper"), c.others.stream().map(g -> g.title).collect(Collectors.toList()));
	}
}

package com.corclan.clan;

import java.time.LocalDate;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class PromotionsTest
{
	private static final LocalDate TODAY = LocalDate.of(2026, 10, 12);

	private static Promotions.Member member(String name, String title, int daysAgo)
	{
		return new Promotions.Member(name, title, TODAY.minusDays(daysAgo), false);
	}

	@Test
	public void firstStepNeedsAWeekAndAHundredGz()
	{
		assertTrue(Promotions.check(Collections.singletonList(member("Bob", "Opal", 400)), TODAY,
			Collections.singletonMap("bob", 99)).due.isEmpty());
		assertTrue(Promotions.check(Collections.singletonList(member("Bob", "Opal", 6)), TODAY,
			Collections.singletonMap("bob", 200)).due.isEmpty());
		Promotions.Result result = Promotions.check(Collections.singletonList(member("Bob", "Opal", 7)), TODAY,
			Collections.singletonMap("bob", 100));
		assertEquals(1, result.due.size());
		assertEquals("Opal", result.due.get(0).from);
		assertEquals("Sapphire", result.due.get(0).to);
	}

	@Test
	public void gzShortHoldsThePromotionBack()
	{
		Promotions.Result result = Promotions.check(Collections.singletonList(member("Bob", "Sapphire", 100)), TODAY,
			Collections.singletonMap("bob", 249));
		assertTrue(result.due.isEmpty());
		assertEquals(1, result.soon.size());
		assertEquals("1 gz", result.soon.get(0).still());
	}

	@Test
	public void uncountedGzAreNeverDue()
	{
		Promotions.Result result = Promotions.check(Arrays.asList(member("No Plugin", "Opal", 400),
			member("Old Sapphire", "Sapphire", 400)), TODAY, Collections.emptyMap());
		assertTrue(result.due.isEmpty());
		assertTrue(result.soon.isEmpty());
