	public void namesWithSpacesNbspAndTags()
	{
		assertEquals("Iron Nick", BroadcastParser.subjectOf("Iron Nick has reached level 99 in Slayer."));
		assertEquals("Iron Nick", BroadcastParser.subjectOf("<col=ff0000>Iron Nick</col> has reached level 99 in Slayer."));
		assertEquals("Iron Nick", BroadcastParser.subjectOf("Iron_Nick has reached level 99 in Slayer."));
	}

	@Test
	public void ignoredBroadcasts()
	{
		assertNull(BroadcastParser.subjectOf("Zezima has deposited 1,000,000 coins into the coffer."));
		assertNull(BroadcastParser.subjectOf("Zezima has withdrawn 1,000,000 coins from the coffer."));
		assertNull(BroadcastParser.subjectOf("Zezima has been invited into the clan by Nick."));
		assertNull(BroadcastParser.subjectOf("Zezima has left the clan."));
		assertNull(BroadcastParser.subjectOf("Zezima has been kicked from the clan by Nick."));
		assertNull(BroadcastParser.subjectOf("Zezima has died and lost their Hardcore Ironman status."));
		assertNull(BroadcastParser.subjectOf("Zezima has been defeated by Nick in The Wilderness."));
		assertNull(BroadcastParser.subjectOf(""));
		assertNull(BroadcastParser.subjectOf(null));
		assertNull(BroadcastParser.subjectOf("Welcome to The Core!"));
		assertNull(BroadcastParser.subjectOf("A very long sentence that does not start with a name has something"));
	}
}

package com.corclan.gz;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.time.Instant;
import org.junit.Test;

public class DailyGmTest
{
	@Test
	public void generousAboutHowPeopleSayIt()
	{
		for (String t : new String[]{"gm", "GM", "gm!", "gmgm", "gmmm", "gm all", "Gm fam <3", "good morning", "Good Morning!!"})
		{
			assertTrue(t, DailyGm.isGm(t));
		}
	}

	@Test
	public void notFooledByWordsThatContainGm()
	{
		StringBuilder longLine = new StringBuilder();
		for (int i = 0; i < 100; i++)
		{
			longLine.append('x');
		}
		for (String t : new String[]{"", "gz", "dogma", "gmail", "egm", "good night", longLine + " gm"})
		{
			assertFalse(t, DailyGm.isGm(t));
		}
		assertFalse(DailyGm.isGm(null));
	}

	@Test
	public void theDayTurnsAtMidnightUtc()
	{
		long beforeMidnight = Instant.parse("2026-10-12T23:59:59Z").toEpochMilli();
		long afterMidnight = Instant.parse("2026-10-13T00:00:00Z").toEpochMilli();
		assertEquals(DailyGm.utcDay(beforeMidnight) + 1, DailyGm.utcDay(afterMidnight));
	}
}

package com.corclan.gz;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class GzDetectorTest
{
	private static final int MAX = 40;

	@Test
	public void plainForms()
	{
		assertTrue(GzDetector.isGz("gz", MAX));
		assertTrue(GzDetector.isGz("GZ", MAX));
		assertTrue(GzDetector.isGz("Gz!", MAX));
		assertTrue(GzDetector.isGz("grats", MAX));
		assertTrue(GzDetector.isGz("gratz", MAX));
		assertTrue(GzDetector.isGz("congrats", MAX));
		assertTrue(GzDetector.isGz("Congratulations", MAX));
	}

	@Test
	public void repeatedLettersAndPunctuation()
	{
		assertTrue(GzDetector.isGz("GZZZZZ!!!", MAX));
		assertTrue(GzDetector.isGz("gzzzzzzzzzz", MAX));
		assertTrue(GzDetector.isGz("graaaats", MAX));
		assertTrue(GzDetector.isGz("gz gz gz", MAX));
		assertTrue(GzDetector.isGz("ggzz", MAX));
	}

	@Test
	public void runTogetherSpam()
	{
		assertTrue(GzDetector.isGz("gzgzgzg", MAX));
		assertTrue(GzDetector.isGz("gzgz", MAX));
		assertTrue(GzDetector.isGz("GZGZGZGZ!!", MAX));
		assertTrue(GzDetector.isGz("gzzgzzgzz", MAX));
		assertTrue(GzDetector.isGz("gzgzgzg mate", MAX));
		assertTrue(GzDetector.isGz("gratzgz", MAX));
		assertTrue(GzDetector.isGz("gzgrats", MAX));
		assertTrue(GzDetector.isGz("gzsgzs", MAX));
	}

	@Test
	public void runTogetherLookalikesDoNotCount()
	{
		assertFalse(GzDetector.isGz("gzgzu", MAX));
		assertFalse(GzDetector.isGz("gzgzeg", MAX));
		assertFalse(GzDetector.isGz("gg", MAX));
		assertFalse(GzDetector.isGz("ggwp", MAX));
		assertFalse(GzDetector.isGz("zgzg", MAX));
	}

	@Test
	public void withinShortSentences()
	{
		assertTrue(GzDetector.isGz("big gz mate", MAX));
		assertTrue(GzDetector.isGz("gz on the pet", MAX));
		assertTrue(GzDetector.isGz("huge grats!!", MAX));
		assertTrue(GzDetector.isGz("wow gz :)", MAX));
	}

	@Test
	public void notGz()
	{
		assertFalse(GzDetector.isGz("", MAX));
		assertFalse(GzDetector.isGz("   ", MAX));
		assertFalse(GzDetector.isGz(null, MAX));
		assertFalse(GzDetector.isGz("anyone doing cox?", MAX));
		assertFalse(GzDetector.isGz("lol", MAX));
		assertFalse(GzDetector.isGz("gzu", MAX));
		assertFalse(GzDetector.isGz("gzeg is my friend", MAX));
	}

	@Test
	public void longMessagesAreIgnored()
	{
		assertFalse(GzDetector.isGz("did anyone see the gz that guy got earlier in the raid lol", MAX));
		assertTrue(GzDetector.isGz("did anyone see the gz that guy got earlier in the raid lol", 200));
	}

	@Test
	public void normalizeCollapsesRepeats()
	{
		assertEquals("gz", GzDetector.normalize("GZZZZ!!!"));
		assertEquals("big gz mate", GzDetector.normalize("  Big   GZZ,  mate "));
		assertEquals("grats", GzDetector.normalize("graaaatsss"));
	}
}

package com.corclan.gz;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.time.Instant;
import java.time.ZoneId;
import java.time.ZoneOffset;
import org.junit.Test;

public class GzTrackerTest
{
	private static final GzTracker.Settings SETTINGS = new GzTracker.Settings(90_000L, true, 40);

	@Test
	public void attributesGzToOpenBroadcast()
	{
		GzTracker t = new GzTracker();
		t.onBroadcast("Zezima", "Zezima has received a drop: Twisted bow", 1_000L);

		assertTrue(t.onClanChat("Nick", "gz", 2_000L, SETTINGS));
		assertTrue(t.onClanChat("Bob", "GZZZ", 3_000L, SETTINGS));

		assertEquals(1, (int) t.getAllTime().getGiven().get("Nick"));
		assertEquals(1, (int) t.getAllTime().getGiven().get("Bob"));
		assertEquals(2, (int) t.getAllTime().getReceived().get("Zezima"));
		assertEquals(2, t.getAllTime().getRecent().get(0).getGzCount());
		assertEquals(2, t.getSession().totalGiven());
	}

	@Test
	public void windowExpires()
	{
		GzTracker t = new GzTracker();
		t.onBroadcast("Zezima", "drop", 1_000L);
		assertTrue(t.onClanChat("Nick", "gz", 1_000L + 90_000L + 1, SETTINGS));

		// given still counts, received does not
		assertEquals(1, (int) t.getAllTime().getGiven().get("Nick"));
		assertNull(t.getAllTime().getReceived().get("Zezima"));
		assertNull(t.currentWindow(200_000L, 90_000L));
	}

	@Test
	public void oneGzPerPersonPerBroadcast()
	{
		GzTracker t = new GzTracker();
		t.onBroadcast("Zezima", "drop", 1_000L);
		t.onClanChat("Nick", "gz", 2_000L, SETTINGS);
		t.onClanChat("Nick", "gz again", 3_000L, SETTINGS);

		assertEquals(2, (int) t.getAllTime().getGiven().get("Nick"));
		assertEquals(1, (int) t.getAllTime().getReceived().get("Zezima"));

		GzTracker.Settings noDedupe = new GzTracker.Settings(90_000L, false, 40);
		t.onClanChat("Nick", "gz", 4_000L, noDedupe);
		assertEquals(2, (int) t.getAllTime().getReceived().get("Zezima"));
	}

	@Test
	public void selfGzDoesNotCountAsReceived()
	{
		GzTracker t = new GzTracker();
		t.onBroadcast("Zezima", "drop", 1_000L);
		t.onClanChat("Zezima", "gz me", 2_000L, SETTINGS);
		assertNull(t.getAllTime().getReceived().get("Zezima"));
		assertEquals(1, (int) t.getAllTime().getGiven().get("Zezima"));
	}

	@Test
	public void newBroadcastReplacesWindow()
	{
		GzTracker t = new GzTracker();
		t.onBroadcast("A", "a", 1_000L);
		t.onBroadcast("B", "b", 2_000L);
		t.onClanChat("Nick", "gz", 3_000L, SETTINGS);
		assertNull(t.getAllTime().getReceived().get("A"));
		assertEquals(1, (int) t.getAllTime().getReceived().get("B"));
	}

	@Test
	public void nonGzIsIgnoredAndRecentIsCapped()
	{
		GzTracker t = new GzTracker();
		assertFalse(t.onClanChat("Nick", "anyone for tob?", 1_000L, SETTINGS));
		for (int i = 0; i < 20; i++)
		{
			t.onBroadcast("P" + i, "x", i);
		}
		assertEquals(GzStats.MAX_RECENT, t.getAllTime().getRecent().size());
		assertEquals("P19", t.getAllTime().getRecent().get(0).getSubject());
		assertNull(t.getAllTime().topGiver());
	}

	@Test
	public void lastGzIsRecordedForIndicator()
	{
		GzTracker t = new GzTracker();
		t.onClanChat("Nick", "gz", 5L, SETTINGS);
		assertEquals(5L, t.getLastGzTime());
		assertEquals("Nick", t.getLastGzGiver());
		assertNull(t.getLastGzSubject());

		t.onBroadcast("Zezima", "drop", 10L);
		t.onClanChat("Bob", "grats", 11L, SETTINGS);
		assertEquals("Bob", t.getLastGzGiver());
		assertEquals("Zezima", t.getLastGzSubject());
	}

	@Test
	public void topGiverAndReset()
	{
		GzTracker t = new GzTracker();
		t.onClanChat("Nick", "gz", 1L, SETTINGS);
		t.onClanChat("Nick", "gz", 2L, SETTINGS);
		t.onClanChat("Bob", "gz", 3L, SETTINGS);
		assertEquals("Nick", t.getAllTime().topGiver());
		t.resetAllTime();
		assertEquals(0, t.getAllTime().totalGiven());
	}

	private static long utc(String iso)
	{
		return Instant.parse(iso).toEpochMilli();
	}

	@Test
	public void weekStartsOnSundayMidnight()
	{
		long sunday = utc("2026-09-27T00:00:00Z");
		assertEquals(sunday, GzTracker.weekStartOf(sunday, ZoneOffset.UTC));
		assertEquals(sunday, GzTracker.weekStartOf(utc("2026-09-29T15:00:00Z"), ZoneOffset.UTC));
		assertEquals(sunday, GzTracker.weekStartOf(utc("2026-10-03T23:59:59Z"), ZoneOffset.UTC));
		assertEquals(utc("2026-10-04T00:00:00Z"), GzTracker.weekStartOf(utc("2026-10-04T00:00:00Z"), ZoneOffset.UTC));
		// local zone decides: Sunday 01:00 in New York is still the week that started the previous Sunday there
		assertEquals(utc("2026-09-27T04:00:00Z"),
			GzTracker.weekStartOf(utc("2026-10-04T03:00:00Z"), ZoneId.of("America/New_York")));
	}

	@Test
	public void weeklyCountsResetOnSunday()
	{
		GzTracker t = new GzTracker(ZoneOffset.UTC);
		t.onBroadcast("Zezima", "drop", utc("2026-10-03T23:58:00Z"));
		t.onClanChat("Nick", "gz", utc("2026-10-03T23:59:00Z"), SETTINGS);
		assertEquals(1, t.getWeekly().totalGiven());
		assertEquals(1, t.getWeekly().totalReceived());
		assertEquals(utc("2026-09-27T00:00:00Z"), t.getWeekStart());

		// first gz after Sunday midnight starts a fresh week; all-time keeps everything
		t.onClanChat("Bob", "gz", utc("2026-10-04T00:00:30Z"), SETTINGS);
		assertEquals(utc("2026-10-04T00:00:00Z"), t.getWeekStart());
		assertEquals(1, t.getWeekly().totalGiven());
		assertEquals(Integer.valueOf(1), t.getWeekly().getGiven().get("Bob"));
		assertNull(t.getWeekly().getGiven().get("Nick"));
		assertEquals(2, t.getAllTime().totalGiven());
	}

	@Test
	public void savedWeekSurvivesRestartUntilItEnds()
	{
		GzTracker t = new GzTracker(ZoneOffset.UTC);
		GzStats saved = new GzStats();
		saved.addGiven("Nick");
		t.loadWeekly(saved, utc("2026-09-27T00:00:00Z"));

		assertFalse(t.rollWeek(utc("2026-09-30T12:00:00Z")));
		assertEquals(1, t.getWeekly().totalGiven());

		assertTrue(t.rollWeek(utc("2026-10-05T12:00:00Z")));
		assertEquals(0, t.getWeekly().totalGiven());
	}

	@Test
	public void resetAllTimeClearsWeekly()
	{
		GzTracker t = new GzTracker(ZoneOffset.UTC);
		t.onClanChat("Nick", "gz", utc("2026-09-29T12:00:00Z"), SETTINGS);
		t.resetAllTime();
		assertEquals(0, t.getWeekly().totalGiven());
	}

	// counts every gz (no one-per-broadcast rule) so only the hourly cap limits them
	private static final GzTracker.Settings UNLIMITED = new GzTracker.Settings(90_000L, false, 40);

	@Test
	public void hourlyCapStopsCountingAt100()
	{
		GzTracker t = new GzTracker(ZoneOffset.UTC);
		long start = utc("2026-09-29T12:00:00Z");
		for (int i = 0; i < GzTracker.MAX_GZ_PER_HOUR; i++)
		{
			assertTrue(t.onClanChat("Spammer", "gz", start + i * 1_000L, UNLIMITED));
		}
		assertFalse(t.onClanChat("Spammer", "gz", start + 200_000L, UNLIMITED));
		assertEquals(100, (int) t.getAllTime().getGiven().get("Spammer"));
		assertEquals(100, (int) t.getWeekly().getGiven().get("Spammer"));
		assertEquals(100, (int) t.getSession().getGiven().get("Spammer"));
	}

	@Test
	public void hourlyCapIsRollingNotPerClockHour()
	{
		GzTracker t = new GzTracker(ZoneOffset.UTC);
		long start = utc("2026-09-29T12:59:00Z");
		for (int i = 0; i < GzTracker.MAX_GZ_PER_HOUR; i++)
		{
			t.onClanChat("Spammer", "gz", start + i * 100L, UNLIMITED);
		}
		// a new clock hour doesn't reset it...
		assertFalse(t.onClanChat("Spammer", "gz", utc("2026-09-29T13:00:30Z"), UNLIMITED));
		// ...but an hour after the first counted gz, one slot frees up
		assertTrue(t.onClanChat("Spammer", "gz", start + GzTracker.HOUR_MILLIS, UNLIMITED));
		assertFalse(t.onClanChat("Spammer", "gz", start + GzTracker.HOUR_MILLIS + 50L, UNLIMITED));
		assertEquals(101, (int) t.getAllTime().getGiven().get("Spammer"));
	}

	@Test
	public void hourlyCapSurvivesARestart()
	{
		GzTracker before = new GzTracker(ZoneOffset.UTC);
		long start = utc("2026-09-29T12:00:00Z");
		for (int i = 0; i < GzTracker.MAX_GZ_PER_HOUR; i++)
		{
			before.onClanChat("Spammer", "gz", start + i * 1_000L, UNLIMITED);
		}
		long restart = start + 10 * 60_000L;

		GzTracker after = new GzTracker(ZoneOffset.UTC);
		after.loadRecentGz(before.getRecentGz(restart), restart);
		assertFalse(after.onClanChat("Spammer", "gz", restart, UNLIMITED));
		// the saved times still expire an hour after they were counted
		assertTrue(after.onClanChat("Spammer", "gz", start + GzTracker.HOUR_MILLIS, UNLIMITED));
	}

	@Test
	public void savedCapTimesOlderThanAnHourAreDropped()
	{
		GzTracker t = new GzTracker(ZoneOffset.UTC);
		long start = utc("2026-09-29T12:00:00Z");
		t.onClanChat("Bob", "gz", start, UNLIMITED);
		assertTrue(t.getRecentGz(start + GzTracker.HOUR_MILLIS).isEmpty());
		assertEquals(1, t.getRecentGz(start + 1_000L).get("bob").size());
	}

	@Test
	public void hourlyCapIsPerPlayerAndIgnoresNameCase()
	{
		GzTracker t = new GzTracker(ZoneOffset.UTC);
		long start = utc("2026-09-29T12:00:00Z");
		for (int i = 0; i < GzTracker.MAX_GZ_PER_HOUR; i++)
		{
			t.onClanChat(i % 2 == 0 ? "Spammer" : "spammer", "gz", start + i, UNLIMITED);
		}
		assertFalse(t.onClanChat("SPAMMER", "gz", start + 500L, UNLIMITED));
		// someone else is unaffected
		assertTrue(t.onClanChat("Honest", "gz", start + 500L, UNLIMITED));
	}

	@Test
	public void cappedGzIsNotCreditedToTheBroadcast()
	{
		GzTracker t = new GzTracker(ZoneOffset.UTC);
		long start = utc("2026-09-29T12:00:00Z");
		for (int i = 0; i < GzTracker.MAX_GZ_PER_HOUR; i++)
		{
			t.onClanChat("Spammer", "gz", start + i, UNLIMITED);
		}
		t.onBroadcast("Zezima", "Zezima has reached 99 Slayer.", start + 1_000L);
		assertFalse(t.onClanChat("Spammer", "gz", start + 2_000L, UNLIMITED));
		assertNull(t.getAllTime().getReceived().get("Zezima"));
	}
}

package com.corclan.gz;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import java.time.LocalDate;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Set;
import java.util.TreeSet;
import org.junit.Test;

public class StreaksTest
{
	private static final ZoneId UTC = ZoneOffset.UTC;
	// Sundays
	private static final LocalDate W1 = LocalDate.of(2026, 9, 6);

	private static long week(int n)
	{
		return W1.plusWeeks(n).atStartOfDay(UTC).toInstant().toEpochMilli();
	}

	private static WeekResult won(int n, String... winners)
	{
		return new WeekResult(week(n), Arrays.asList(winners));
	}

	private static Set<String> names(String... n)
	{
		return new TreeSet<>(Arrays.asList(n));
	}

	@Test
	public void noHistoryNoStreak()
	{
		assertNull(Streaks.longest(new ArrayList<>(), UTC));
		assertNull(Streaks.current(new ArrayList<>(), week(0), UTC));
	}

	@Test
	public void longestRunOfConsecutiveWeeks()
	{
		List<WeekResult> h = Arrays.asList(won(0, "Alice"), won(1, "Alice"), won(2, "Bob"), won(3, "Alice"));
		Streaks.Streak s = Streaks.longest(h, UTC);
		assertEquals(names("Alice"), s.players);
		assertEquals(2, s.weeks);
	}

	@Test
	public void missingWeekBreaksTheRun()
	{
		// week 2 has no result (nobody gz'd / client not running)
		List<WeekResult> h = Arrays.asList(won(0, "Alice"), won(1, "Alice"), won(3, "Alice"), won(4, "Alice"), won(5, "Alice"));
		assertEquals(3, Streaks.longest(h, UTC).weeks);
	}

	@Test
	public void tiesShareTheWeekAndTheRecord()
	{
		List<WeekResult> h = Arrays.asList(won(0, "Alice", "Bob"), won(1, "Alice", "Bob"), won(2, "Carol"));
		Streaks.Streak s = Streaks.longest(h, UTC);
		assertEquals(names("Alice", "Bob"), s.players);
		assertEquals(2, s.weeks);
	}

	@Test
	public void currentStreakMustIncludeLastWeek()
	{
		List<WeekResult> h = Arrays.asList(won(0, "Bob"), won(1, "Alice"), won(2, "Alice"));
		Streaks.Streak now = Streaks.current(h, week(3), UTC);
		assertEquals(names("Alice"), now.players);
		assertEquals(2, now.weeks);

		// a week later with no new winner recorded, the run is over
		assertNull(Streaks.current(h, week(4), UTC));
		// but the record stands
		assertEquals(2, Streaks.longest(h, UTC).weeks);
	}

	@Test
	public void orderOfHistoryDoesNotMatter()
	{
		List<WeekResult> h = Arrays.asList(won(2, "Alice"), won(0, "Alice"), won(1, "Alice"));
		assertEquals(3, Streaks.longest(h, UTC).weeks);
	}

	@Test
	public void weeksAcrossDaylightSavingAreStillConsecutive()
	{
		// US clocks go back on Sun 1 Nov 2026, so that week isn't exactly 7*24h long
		ZoneId ny = ZoneId.of("America/New_York");
		long oct25 = LocalDate.of(2026, 10, 25).atStartOfDay(ny).toInstant().toEpochMilli();
		long nov1 = LocalDate.of(2026, 11, 1).atStartOfDay(ny).toInstant().toEpochMilli();
		long nov8 = LocalDate.of(2026, 11, 8).atStartOfDay(ny).toInstant().toEpochMilli();
		List<WeekResult> h = Arrays.asList(
			new WeekResult(oct25, Arrays.asList("Alice")),
			new WeekResult(nov1, Arrays.asList("Alice")),
			new WeekResult(nov8, Arrays.asList("Alice")));
		assertEquals(3, Streaks.longest(h, ny).weeks);
	}

	@Test
	public void trackerRecordsWinnerWhenWeekEnds()
	{
		GzTracker.Settings settings = new GzTracker.Settings(90_000L, true, 40);
		GzTracker t = new GzTracker(UTC);
		long day = 24 * 3600_000L;
		t.onClanChat("Alice", "gz", week(0) + day, settings);
		t.onClanChat("Alice", "gz", week(0) + 2 * day, settings);
		t.onClanChat("Bob", "gz", week(0) + 3 * day, settings);
		assertEquals(0, t.getWeekResults().size());

		t.onClanChat("Bob", "gz", week(1) + day, settings);
		assertEquals(1, t.getWeekResults().size());
		assertEquals(Arrays.asList("Alice"), t.getWeekResults().get(0).getWinners());
		assertEquals(1, t.currentStreak().weeks);

		t.rollWeek(week(2) + day);
		assertEquals(Arrays.asList("Bob"), t.getWeekResults().get(1).getWinners());
		assertEquals(names("Bob"), t.currentStreak().players);

		t.resetAllTime();
		assertNull(t.longestStreak());
	}
}

package com.corclan.icons;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.util.Base64;
import javax.imageio.ImageIO;
import org.junit.Test;

public class IconDecoderTest
{
	private static byte[] png(int w, int h) throws Exception
	{
		BufferedImage img = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		img.setRGB(0, 0, 0xFFD32F2F);
		ByteArrayOutputStream out = new ByteArrayOutputStream();
		ImageIO.write(img, "png", out);
		return out.toByteArray();
	}

	private static String b64(byte[] bytes)
	{
		return Base64.getEncoder().encodeToString(bytes);
	}

	@Test
	public void decodesChatSizedPngs() throws Exception
	{
		BufferedImage img = IconDecoder.decode(b64(png(13, 11)));
		assertNotNull(img);
		assertEquals(13, img.getWidth());
		assertEquals(11, img.getHeight());
		assertNotNull(IconDecoder.decode(b64(png(32, 16))));
	}

	@Test
	public void refusesOversizedImages() throws Exception
	{
		assertNull(IconDecoder.decode(b64(png(33, 11))));
		assertNull(IconDecoder.decode(b64(png(64, 64))));
	}

	@Test
	public void refusesAHeaderThatClaimsAHugeImage() throws Exception
	{
		byte[] bytes = png(1, 1);
		// IHDR width and height live at bytes 16-23
		bytes[16] = 0; bytes[17] = 0; bytes[18] = (byte) 0xC3; bytes[19] = 0x50;
		bytes[20] = 0; bytes[21] = 0; bytes[22] = (byte) 0xC3; bytes[23] = 0x50;
		assertNull(IconDecoder.decode(b64(bytes)));
	}

	@Test
	public void refusesJunk()
	{
		assertNull(IconDecoder.decode(null));
		assertNull(IconDecoder.decode(""));
		assertNull(IconDecoder.decode("not base64 !!!"));
		assertNull(IconDecoder.decode(b64("GIF89a not a png".getBytes())));
		StringBuilder big = new StringBuilder();
		for (int i = 0; i < IconDecoder.MAX_BASE64_LENGTH + 10; i++)
		{
			big.append('A');
		}
		assertNull(IconDecoder.decode(big.toString()));
	}
}

package com.corclan.icons;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.corclan.sync.SyncModels;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.function.Predicate;
import org.junit.Test;

public class MemberCosmeticsTest
{
	private static final Predicate<String> ICONS = k -> ClanIconService.MEMBER_KEYS.contains(k);
	private static final Map<String, List<String>> BUILTIN_ICONS =
		Collections.singletonMap("lavasockz", Arrays.asList("founder", "dev"));
	private static final Map<String, String> BUILTIN_TITLES = Collections.singletonMap("lavasockz", "Developer");

	private static MemberCosmetics build(String config)
	{
		return build(Collections.emptyList(), config);
	}

	private static MemberCosmetics build(List<SyncModels.ClanPlayer> server, String config)
	{
		return MemberCosmetics.build(BUILTIN_ICONS, BUILTIN_TITLES, server, config, ICONS);
	}

	@Test
	public void builtInsApplyWithNothingElse()
	{
		MemberCosmetics c = build("");
		assertEquals(Arrays.asList("founder", "dev"), c.iconsFor("lavasockz"));
		assertEquals("Developer", c.titleFor("lavasockz"));
		assertTrue(c.iconsFor("nobody").isEmpty());
	}

	@Test
	public void configOverridesBuiltIns()
	{
		MemberCosmetics c = build("Lavasockz=crown|Clan Dev\nZezima=star,gem");
		assertEquals(Collections.singletonList("crown"), c.iconsFor("lavasockz"));
		assertEquals("Clan Dev", c.titleFor("lavasockz"));
		assertEquals(Arrays.asList("star", "gem"), c.iconsFor("zezima"));
		assertNull(c.titleFor("zezima"));
	}

	@Test
	public void serverOverridesBuiltInsAndConfigOverridesServer()
	{
		List<SyncModels.ClanPlayer> server = Arrays.asList(
			new SyncModels.ClanPlayer("Lavasockz", Collections.singletonList("crown"), "Clan Dev"),
			new SyncModels.ClanPlayer("Zezima", Arrays.asList("star", "gem"), null));

		MemberCosmetics fromServer = build(server, null);
		assertEquals(Collections.singletonList("crown"), fromServer.iconsFor("lavasockz"));
		assertEquals("Clan Dev", fromServer.titleFor("lavasockz"));
		assertEquals(Arrays.asList("star", "gem"), fromServer.iconsFor("zezima"));

		MemberCosmetics withConfig = build(server, "Zezima=fire|Event Host");
		assertEquals(Collections.singletonList("fire"), withConfig.iconsFor("zezima"));
		assertEquals("Event Host", withConfig.titleFor("zezima"));
	}

	@Test
	public void serverPlayersWithoutIconsOrTitleChangeNothing()
	{
		// GET /v1/clan lists everyone with a gz count too
		MemberCosmetics c = build(Collections.singletonList(new SyncModels.ClanPlayer("Lavasockz", null, null)), "");
		assertEquals(Arrays.asList("founder", "dev"), c.iconsFor("lavasockz"));
		assertEquals("Developer", c.titleFor("lavasockz"));
	}

	@Test
	public void serverIconsAndTitlesAreCleanedToo()
	{
		MemberCosmetics c = build(Collections.singletonList(
			new SyncModels.ClanPlayer("Bob", Arrays.asList("rainbow", "crown", "crown", "star", "gem", "fire", "skull"), "<col=ff0000>Boss")), "");
		assertEquals(Arrays.asList("crown", "star", "gem", "fire"), c.iconsFor("bob"));
		assertEquals("Boss", c.titleFor("bob"));
	}

	@Test
	public void unknownIconsAndUnsafeTitlesAreDropped()
	{
		MemberCosmetics c = build("Bob=rainbow,crown,crown,star,gem,fire,skull|<col=ff0000>Boss\n"
			+ "Carl=crown|this title is far too long to fit\nDave=star|<>");
		assertEquals(Arrays.asList("crown", "star", "gem", "fire"), c.iconsFor("bob"));
		assertEquals("Boss", c.titleFor("bob"));
		assertEquals(Collections.singletonList("crown"), c.iconsFor("carl"));
		assertNull(c.titleFor("carl"));
		assertNull(c.titleFor("dave"));
	}

	@Test
	public void rankTitleLinesWorkLikeNames()
	{
		MemberCosmetics ranks = MemberCosmetics.build(Collections.emptyMap(), Collections.emptyMap(),
			Collections.emptyList(), "Gnome child=gem|Gnome\nOwner=crown,star", ICONS);
		assertEquals(Collections.singletonList("gem"), ranks.iconsFor(MemberCosmetics.key("Gnome child")));
		assertEquals("Gnome", ranks.titleFor("gnome child"));
		assertEquals(Arrays.asList("crown", "star"), ranks.iconsFor("owner"));
	}

	@Test
	public void keysIgnoreCaseTagsAndSpacing()
	{
		assertEquals("iron nick", MemberCosmetics.key("<img=12>Iron NICK "));
		assertEquals("iron nick", MemberCosmetics.key("Iron_Nick"));
		MemberCosmetics c = build("Iron_Nick=gem");
		assertEquals(Collections.singletonList("gem"), c.iconsFor(MemberCosmetics.key("iron nick")));
	}
}

