package com.corclan.raid;

import com.corclan.sync.SyncModels;
import com.google.gson.Gson;
import java.util.Collections;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class RaidListingTest
{
	private static List<RaidListing> board(String raids)
	{
		return RaidListing.board(new Gson().fromJson("{\"raids\":[" + raids + "]}", SyncModels.RaidsResponse.class));
	}

	@Test
	public void readsAndCleansTheBoard()
	{
		List<RaidListing> board = board(
			"{\"rsn\":\"<col=ff0000>Bob</col>\",\"raid\":\"tob\",\"filled\":3,\"size\":5,\"world\":330,"
				+ "\"note\":\"need <b>tank</b>\",\"postedAt\":\"2026-10-12T20:00:00.000Z\"},"
				+ "{\"rsn\":\"Al\",\"raid\":\"cox\",\"filled\":2,\"size\":40,\"world\":null},"
				+ "{\"rsn\":\"Bad\",\"raid\":\"tob\",\"filled\":3,\"size\":6},"
				+ "{\"rsn\":\"Bad\",\"raid\":\"nightmare\",\"filled\":1,\"size\":5},"
				+ "{\"rsn\":\"Bad\",\"raid\":\"toa\",\"filled\":5,\"size\":4}");
		assertEquals(2, board.size());
		RaidListing bob = board.get(0);
		assertEquals("Bob", bob.name);
		assertEquals(Raid.TOB, bob.raid);
		assertEquals("3/5", bob.slots());
		assertEquals(330, bob.world);
		assertEquals("need tank", bob.note);
		assertEquals(1791835200000L, bob.postedAt);
		assertEquals(0, board.get(1).world);
		assertEquals("", board.get(1).note);
	}

	@Test
	public void keyTellsANewGroupFromAnUpdate()
	{
		RaidListing first = board("{\"rsn\":\"Bob\",\"raid\":\"tob\",\"filled\":2,\"size\":5,\"postedAt\":\"2026-10-12T20:00:00.000Z\"}").get(0);
		RaidListing update = board("{\"rsn\":\"bob\",\"raid\":\"tob\",\"filled\":4,\"size\":5,\"postedAt\":\"2026-10-12T20:00:00.000Z\"}").get(0);
		RaidListing other = board("{\"rsn\":\"Bob\",\"raid\":\"toa\",\"filled\":2,\"size\":5,\"postedAt\":\"2026-10-12T20:05:00.000Z\"}").get(0);
		assertEquals(first.key(), update.key());
		assertNotEquals(first.key(), other.key());
		assertTrue(first.isHost("BOB"));
		assertFalse(first.isHost(null));
	}

	@Test
	public void adKeepsSizesInRangeAndCleansTheNote()
	{
		RaidAd ad = new RaidAd(Raid.TOB, 9, 9, "  <col=ff0000>need</col> a   tank ");
		assertEquals(5, ad.size);
		assertEquals(5, ad.filled);
		assertEquals("need a tank", ad.note);
		RaidAd low = new RaidAd(Raid.COX, 0, 1, null);
		assertEquals(2, low.size);
		assertEquals(1, low.filled);
		assertEquals("", low.note);
		assertEquals(RaidAd.MAX_NOTE, new RaidAd(Raid.TOA, 1, 4, String.join("", Collections.nCopies(100, "x"))).note.length());
	}

	@Test
	public void hostIsAwayAfterSevenQuietMinutes()
	{
		RaidListing l = board("{\"rsn\":\"Bob\",\"raid\":\"tob\",\"filled\":2,\"size\":5,\"postedAt\":\"2026-10-12T20:00:00.000Z\",\"updatedAt\":\"2026-10-12T20:10:00.000Z\"}").get(0);
		long updated = 1791835800000L;
		assertFalse(l.isAway(updated + RaidListing.AWAY_MILLIS));
		assertTrue(l.isAway(updated + RaidListing.AWAY_MILLIS + 1));
	}
}

package com.corclan.sync;

import com.google.gson.Gson;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import org.junit.Test;

public class AnnouncementTest
{
	private static ClanSnapshot snapshot(String json)
	{
		return ClanSnapshot.of(new Gson().fromJson(json, SyncModels.ClanResponse.class));
	}

	@Test
	public void readsTheBannerFromTheClanFeed()
	{
		Announcement a = snapshot("{\"players\":[],\"announcement\":{\"text\":\"Bandos mass tonight\\n20:00 UTC, W330\","
			+ "\"by\":\"Lavasockz\",\"updatedAt\":\"2026-10-12T17:55:00.000Z\"}}").getAnnouncement();
		assertEquals("Bandos mass tonight\n20:00 UTC, W330", a.text);
		assertEquals("Lavasockz", a.by);
		assertEquals(java.time.Instant.parse("2026-10-12T17:55:00.000Z").toEpochMilli(), a.updatedAt);
	}

	@Test
	public void noBannerWhenMissingNullOrEmpty()
	{
		assertNull(snapshot("{\"players\":[]}").getAnnouncement());
		assertNull(snapshot("{\"announcement\":null}").getAnnouncement());
		assertNull(snapshot("{\"announcement\":{\"text\":\"  <b></b> \\n \",\"by\":\"Lavasockz\"}}").getAnnouncement());
	}

	@Test
	public void anUnreadableTimeStillShowsTheBanner()
	{
		Announcement a = snapshot("{\"announcement\":{\"text\":\"hi\",\"by\":\"JoeBoob\",\"updatedAt\":\"yesterday\"}}").getAnnouncement();
		assertEquals("hi", a.text);
		assertEquals(0L, a.updatedAt);
	}

	@Test
	public void markupNeverGetsThrough()
	{
		assertEquals("Party at the GE", Announcement.clean("<col=ff0000>Party</col> at <img=3> the GE"));
		assertEquals("a c", Announcement.clean("a < b > c"));
		assertEquals("html", Announcement.clean("<html>html"));
		Announcement a = snapshot("{\"announcement\":{\"text\":\"x\",\"by\":\"<b>Lava</b>\\nsockz\"}}").getAnnouncement();
		assertEquals("Lava sockz", a.by);
	}

	@Test
	public void tidiesSpacesAndLines()
	{
		assertEquals("one two\nthree", Announcement.clean("  one    two \r\n\n\n three  "));
		StringBuilder many = new StringBuilder();
		for (int i = 0; i < Announcement.MAX_LINES + 4; i++)
		{
			many.append("line ").append(i).append('\n');
		}
		assertEquals(Announcement.MAX_LINES, Announcement.clean(many.toString()).split("\n").length);
		StringBuilder longText = new StringBuilder();
		for (int i = 0; i < Announcement.MAX_LENGTH + 50; i++)
		{
			longText.append('x');
		}
		assertEquals(Announcement.MAX_LENGTH, Announcement.clean(longText.toString()).length());
		assertEquals("", Announcement.clean(null));
	}
}

package com.corclan.sync;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import com.corclan.CorClanConfig;
import com.google.gson.Gson;
import java.util.Collections;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;
import okhttp3.OkHttpClient;
import org.junit.Test;

/** With "Sync with clan server" off, no request leaves the plugin and every caller still hears back. */
public class ClanApiOffTest
{
	private final AtomicInteger requests = new AtomicInteger();
	private final OkHttpClient http = new OkHttpClient.Builder()
		.addInterceptor(chain ->
		{
			requests.incrementAndGet();
			throw new AssertionError("a request went out with sync off: " + chain.request().url());
		})
		.build();
	private final CorClanConfig syncOff = new CorClanConfig()
	{
		@Override
		public boolean syncEnabled()
		{
			return false;
		}
	};
	private final ClanApi api = new ClanApi(http, new Gson(), syncOff);
	private final SyncModels.Reporter me = new SyncModels.Reporter("-1234567890123", "Lavasockz", "C o R");

	@Test
	public void nothingIsSentAndCallersAreToldItFailed()
	{
		AtomicReference<ClanApi.Outcome> report = new AtomicReference<>();
		api.sendReport(new SyncModels.ReportPayload(me, 0, Collections.emptyList()), report::set);
		assertEquals(ClanApi.Outcome.RETRY, report.get());

		AtomicReference<ClanApi.Outcome> gm = new AtomicReference<>();
		api.sendGm(new SyncModels.GmPayload(me, "gm"), (outcome, result) -> gm.set(outcome));
		assertEquals(ClanApi.Outcome.RETRY, gm.get());

		AtomicReference<String> ping = new AtomicReference<>();
		api.pingRaid(new SyncModels.RaidStopPayload(me), ping::set);
		assertNotNull(ping.get());

		api.fetchClan(response ->
		{
			throw new AssertionError("no answer can arrive with sync off");
		});
		api.fetchRaids(response ->
		{
			throw new AssertionError("no answer can arrive with sync off");
		});
		assertEquals(0, requests.get());
	}
}

package com.corclan.sync;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class ClanApiTest
{
	@Test
	public void successIsOk()
	{
		assertEquals(ClanApi.Outcome.OK, ClanApi.classify(200, null));
		assertEquals(ClanApi.Outcome.OK, ClanApi.classify(204, null));
	}

	@Test
	public void takenNamesAndOtherClansAreToldApart()
	{
		assertEquals(ClanApi.Outcome.NAME_TAKEN, ClanApi.classify(409, "name_taken"));
		assertEquals(ClanApi.Outcome.WRONG_CLAN, ClanApi.classify(403, "wrong_clan"));
		// an unreadable body falls back to the status
		assertEquals(ClanApi.Outcome.NAME_TAKEN, ClanApi.classify(409, null));
		assertEquals(ClanApi.Outcome.WRONG_CLAN, ClanApi.classify(403, null));
		assertTrue(ClanApi.Outcome.NAME_TAKEN.blocksReporter());
		assertTrue(ClanApi.Outcome.WRONG_CLAN.blocksReporter());
	}

	@Test
	public void outagesAndRateLimitsAreRetried()
	{
		assertEquals(ClanApi.Outcome.RETRY, ClanApi.classify(429, null));
		assertEquals(ClanApi.Outcome.RETRY, ClanApi.classify(500, null));
		assertEquals(ClanApi.Outcome.RETRY, ClanApi.classify(503, "unavailable"));
		assertFalse(ClanApi.Outcome.RETRY.blocksReporter());
	}

	@Test
	public void requestsTheServerWillNeverTakeAreNotRetried()
	{
		assertEquals(ClanApi.Outcome.REFUSED, ClanApi.classify(400, "invalid_events"));
		assertEquals(ClanApi.Outcome.REFUSED, ClanApi.classify(403, "banned"));
		// someone who isn't a shamer tried ::shame: refused, but it doesn't stop their other reports
		assertEquals(ClanApi.Outcome.REFUSED, ClanApi.classify(403, "not_a_leader"));
		// a ::shame on someone who hasn't turned on Let leaders shame me
		assertEquals(ClanApi.Outcome.NOT_SHAMEABLE, ClanApi.classify(403, "not_shameable"));
		assertFalse(ClanApi.Outcome.NOT_SHAMEABLE.blocksReporter());
